  },
  "事件详情": "慈恩善恶交战，猛然呼的一声出掌向一灯大师劈去。一灯举手斜挡身子微晃——他发大愿大勇宁受铁掌撞击绝不还手，只盼弟子悔悟。慈恩一掌接一掌劈去，劈到第十四掌时一灯哇的一声喷出鲜血。杨过对一灯钦佩无已，回身提起玄铁重剑绕过一灯身侧挺剑直刺。玄铁剑劲风与慈恩掌风相撞，两人身子各各微摇。慈恩万万想不到荒山猎户竟有如此武功。杨过劝道'大师除恶即是行善何必自悔'，慈恩一怔后猛然想起自己昔日也曾相助异族侵夺大宋江山，杨过的话痛斥其非，怒极提掌劈去。杨过危急中顺掌力纵身后跃撞破板壁飞到屋外，随即身随风至挺剑回刺。两人各运神功剑掌激斗——慈恩掌力虽猛但杨过的重剑剑法是独孤求败绝技，洪水练剑蛇胆增力已仿佛当年剑魔。斗到百余招慈恩渐落下风，杨过铁剑横扫疾风卷雪遮住慈恩双目，玄铁剑搭上其右肩压得他肋骨内缩无法吸气。慈恩生平首次如此接近死亡，心头掠过一个'死'字，大悔一生过恶无法补救。一灯上前伸指轻点剑刃以一阳指功荡开玄铁剑，慈恩扑翻在地跪倒认罪。杨过随即拜见一灯大师说出身份，又引小龙女行礼。",
  "事件概要": "杨过以玄铁剑力敌慈恩并助其回头认罪，一灯师徒关系得以续存，杨过也与一灯正式相认。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第30回-04-杨过玄铁剑斗慈恩救一灯": "见一灯大师一味挨打口喷鲜血，钦佩无已之下提起玄铁重剑挺身而出。以独孤求败重剑剑法与慈恩铁掌激斗百余招——剑掌劲风摧毁了小木屋屋顶。虽断右臂但重剑威力无穷——'顺刺逆击横削倒劈'的剑理发挥得淋漓尽致。最终以铁剑横扫疾风卷雪遮目之计将玄铁剑搭上慈恩右肩将其压倒在地。一灯以一阳指荡开剑刃后即拜见大师说明身份"
      }
    },
    "小龙女": {
      "人物经历": {
        "第30回-04-杨过玄铁剑斗慈恩救一灯": "抱郭襄站在门边观战，神色闲雅殊不惊惶。小木屋在剑掌激斗中崩塌——抱郭襄从窗中飞身而出。一灯大师见她眉间与人中隐隐有一层黑气不禁叫了声'啊哟'，小龙女报以一笑心道'你瞧出来了'。后依杨过指引向一灯裣衽行礼"
      }
    },
    "郭襄": {
      "人物经历": {
        "第30回-04-杨过玄铁剑斗慈恩救一灯": "被小龙女抱着经历了木屋崩塌的惊险——从小窗飞出后又被带入屋外观战，在风雪之中感受了一场高手间的惊天对决"
      }
    },
    "一灯大师": {
      "人物经历": {
        "第30回-04-一灯舍身挨打杨过相救": "挡到杨龙二人身前盘膝坐地口宣佛号。面对慈恩一掌接一掌的铁掌宁可受击绝不还手——舍身度人的大愿大勇。劈到第十四掌时哇的一声喷出鲜血白须僧袍全染满了。见杨过出手与慈恩激斗暗暗称奇——这少年不过二十有余竟能与当代一流高手打成平手。见小龙女眉间黑气知其毒入脏腑暗自担忧。杨过制服慈恩后伸指以纯阳指力荡开玄铁剑救下弟子，微笑说'大觉大悟殊非易易'"
      }
    },
    "裘千仞": {
      "人物经历": {
        "第30回-04-慈恩攻击一灯被杨过制服大彻大悟": "善恶交战——眼中一灯既是恩师又是仇人。连发十四掌击得一灯口喷鲜血仍不还手。被杨过以玄铁重剑激斗百余招后压在剑下——生平首次如此接近死亡，心想'给人杀死如是之惨然则我过去杀人被杀者也是一样的悲惨了'。被制服后跪地大叫'师父弟子罪该万死'——一灯千言万语开导不了的杨过这一剑却令他想到杀人者与被杀者同受其苦。心中恶念被压制善念重占上风"
      }
    }
  },
