{
  "事件地点": "大宋/华山/高冈",
  "触发条件": {
    "类型": "时间",
    "年": 1260,
    "月": 4,
    "日": 5,
    "时": 10
  },
  "事件结束时间": {
    "年": 1260,
    "月": 4,
    "日": 5,
    "时": 11
  },
  "事件引子": "觉远道破九阳真经之秘后，众人群情耸动。张君宝突然喝道我来搜，上前伸手便向尹克西胸口扭去……",
  "后续事件": {
    "事件名": "第40回-06-潇尹携猿离去杨过辞别众人",
    "描述": "张君宝搜索潇尹二人身上皆无经书。尹克西扶起潇湘子向苍猿招手……"
  },
  "事件详情": "张君宝上前要搜尹克西之身被推摔筋斗。觉远出言指点'气沉于渊力凝山根'——众人均想料不到这君子和尚居然也会教徒弟打架。张君宝依言气沉下盘，尹克西竟推他不动。尹克西变招虚推使他俯跌又假意扶起。觉远继续以山峰作喻指点'他自屹立千古如是大风从西来暴雨自东至这山峰既不退让也不故意和之挺撞'——张君宝悟性甚高当即领悟。尹克西连击数掌无奈张君宝体内生出反力——掌力增重抵御之力也相应加强。觉远不断出言指点'虚实须分清楚一处有一处虚实'、'要用意不用劲随人所动随屈就伸'——这些实是九阳真经中上乘武学诀窍。杨过伸手拉住张君宝低声道'你只挨打不还手终是制他不住。我教你一招'——右手袖子在张君宝脸前一拂左拳击到胸前半尺突然转弯击在腰间。张君宝大喜依样使出尹克西被一拳打在胁下痛入骨髓。杨过又连教三招——第一招'推心置腹'左右互调，第二招'四通八达'拳势大开大阖，第三招'鹿死谁手'前后对调全凭步法取胜。张君宝依计使出，尹克西自作聪明料错方位连中数招狼狈不堪。杨过更以弹指神通弹出花瓣小球在尹克西大椎穴上留下红印标记。张君宝以鹿死谁手之法转至尹克西身后左手指节按在大椎穴红印之上——尹克西全身酸麻委顿在地。旁观众人除了潇湘子外个个大声喝彩。张君宝搜遍尹克西全身却无楞伽经。潇湘子纵身欲逃被觉远袍袖一拂挡住——恶念陡起双掌击觉远胸口却被九阳真经反弹之力震出数丈跌晕过去。张君宝搜潇湘子身上也无经书。众人又惊又喜齐口称誉觉远内力了得而觉远茫然不解只念佛号。",
  "事件概要": "张君宝在觉远与杨过指点下制住尹克西，潇湘子亦被震倒，但楞伽经仍未追回。",
  "update": {
    "张君宝": {
      "状态": "在华山与尹克西交手——首次将九阳真经内功用于实战。得觉远和杨过指点后以鹿死谁手制住尹克西大椎穴令其委顿在地。搜遍潇尹二人身上却无楞伽经踪影",
      "境界": "二流-融会贯通",
      "关系网": {
        "郭襄": "感激/60"
      }
    },
    "尹克西": {
      "状态": "在华山被张君宝纠缠交手——竟奈何不了一个十二三岁的孩童颇为狼狈。先被杨过所教拳法痛击胁下痛入骨髓，后被张君宝以鹿死谁手按住大椎穴酸麻委顿在地当众受辱。被搜身无经书——有苍猿为伴"
    },
    "杨过": {
      "状态": "在华山见张君宝连番挨打后伸手拉住他。将'挨何处心要用在何处'的道理化为'打何处心也要用在何处'教张君宝出拳法门。连教三招——推心置腹、四通八达、鹿死谁手——以弹指神通在尹克西大椎穴留下花瓣红印助张君宝制敌。观张君宝成功降敌后大声喝彩"
    },
    "觉远": {
      "状态": "在华山实战中不断以九阳真经精义指点张君宝御敌——虽不会武功但所说深通拳术妙理令杨过也受益不浅。潇湘子双掌击来时因不会武功只有挨打——但九阳真经护体将掌力尽数反弹令潇湘子重伤昏晕。茫然不解只念佛号"
    },
    "潇湘子": {
      "状态": "在华山见尹克西被张君宝制住自知不是对手拍衣说身上并无经书。纵身欲逃被觉远袍袖一拂挡住——恶念陡起双掌击觉远胸口却被九阳真经反弹震出数丈跌落在地缩成一团竟尔昏晕过去"
    },
    "郭襄": {
      "状态": "在华山观张君宝斗尹克西——见其只挨打不还手忍不住大叫出手打他啊。张君宝道谢后挥拳打去觉远摇首长叹——郭襄却看得兴高采烈"
