  },
  "事件结束时间": {
    "年": 1245,
    "月": 1,
    "日": 18,
    "时": 11
  },
  "事件引子": "你听说重阳宫后殿突然破了个大洞落下一口千余斤巨钟，老顽童周伯通闯入宫中引来大群玉蜂，全真教叛徒赵志敬在混乱中被蜂群活活蜇死在巨钟之下。",
  "后续事件": {
    "事件名": "第28回-03-藏经阁越涧潜水归古墓",
    "描述": "杨过与小龙女在玉蜂掩护下冲向后院藏经阁，用绳索越涧脱身，以木箱潜水回到古墓。"
  },
  "事件详情": "杨龙二人拜堂刚毕，殿顶突然破裂——丘处机刘处玄王处一郝大通四人分托一口千余斤巨钟从破洞砸下，对准孙不二头顶直堕而下。杨过立即抽出玄铁剑刺出，剑尖以风雷之势击中铜钟，巨钟凌空一偏向前斜了二尺，眼看就要压死孙不二。杨过心念一转——'今日是我夫妇大喜的日子，何苦伤害人命？'右手袖子拂出推动蒲团，将孙不二送入钟底逃过一劫。四道又惊又喜，门人却依嘱闯入进攻。正纷乱间，老顽童周伯通飞奔进殿，身后跟着大群玉蜂——原来是他在终南山上偷玩玉蜂蜜浆引来蜂群。杨过接过周伯通抛来的蜜瓶交给小龙女，小龙女挥手呼叱指挥玉蜂分成两队，一队开路一队断后，拥卫着杨龙二人冲了出去。周伯通躲在巨钟之下，又将门下叛徒赵志敬掷入钟底。赵志敬在钟下拾得蜜浆瓶，企图以此要挟周伯通饶命。周伯通假意说蜜浆是假的让赵志敬拔开瓶塞验证——瓶塞一开芳香馥郁，玉蜂闻到蜜香纷纷钻入钟底。赵志敬全身沾满蜜浆，举手投足碰到无数玉蜂，狂呼惨叫后终于寂然无声，被蜂群活活蜇死在巨钟之下。",
  "事件概要": "周伯通引玉蜂助杨龙突围，赵志敬死于蜂群之下，全真教内乱与逼杀旧债再少一名当事人。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第28回-02-周伯通闯宫与赵志敬之死": "殿顶破洞落下一口千余斤巨钟对准孙不二头顶砸下。杨过抽玄铁剑刺出，剑尖击中铜钟令其凌空偏移。本可让巨钟压死孙不二，却心想今日是大喜日子何苦伤人性命，拂袖推动蒲团将孙不二送入钟底救了她性命。全真弟子攻入殿来，杨过抱着小龙女边退边以鸳鸯连环腿踢倒数道。周伯通带着玉蜂闯入后，接过蜜瓶交给小龙女，小龙女指挥玉蜂护着二人冲出重围"
