  },
  "事件引子": "杨过在山脚遇见一个妙龄道姑，她问上山的路，却原来是冲着活死人墓来的...",
  "后续事件": {
    "事件名": "第6回-12-石床机关断隔杨过割腕喂血",
    "描述": "李莫愁现身之后，小龙女启动石床机关落入下层石室，与李莫愁师徒隔断"
  },
  "事件详情": "树后走出一名妙龄道姑背插双剑，正是李莫愁的大弟子洪凌波。她问杨过上山路径，杨过因恨全真教装聋作哑。洪凌波使出古墓派功夫——腰带挥出缠住杨过右足将他拉回，拔出长剑抵在他胸口逼带路。杨过确定她是同门后更装傻到底，依言到农舍取来短斧披上破衣，被洪凌波揽着上山故意跌跌撞撞又重踹她脚背。洪凌波虽恼却只道他是傻子，拿出地图寻找路径。杨过说树林有鬼，洪凌波大喜知活死人墓在此。原来洪凌波听师父谈论玉女心经留墓中，此次趁机来盗经。杨过假意怕鬼让她再三答应赶鬼后领路入墓。入墓后杨过在黑暗中毫不迟疑东转西绕开门拉石熟悉异常，带洪凌波直入小龙女卧室。洪凌波点烛见小龙女卧床，自称弟子行礼参见。小龙女缓缓转身，洪凌波见到她秀丽绝俗容颜大吃一惊自惭形秽。小龙女命她出去，洪凌波见她重伤病容放下提防之心，竟用冰魄银针威逼交出玉女心经。小龙女又急又怒晕了过去。杨过眼见事势危急假称有鬼扑过去抱住洪凌波背心，顺手在她'肩贞''京门'两穴各点一指，又重点'巨骨'穴——洪凌波做梦也想不到这傻蛋有一身上乘武功，全身酸麻软瘫在地。杨过用衣襟裹指拾起银针说要刺她几下，洪凌波吓得魂飞魄散。就在此时身后一个娇媚女子声音响起：'师妹，你好啊？我早来啦。'烛光下只见门口俏生生站着一个美貌道姑杏眼桃腮嘴角似笑非笑，正是赤练仙子李莫愁。",
  "事件概要": "杨过以机变挟持李莫愁换得喘息，但师门内外的追逼已全面合拢，脱身只剩险着。",
  "insert": {
    "洪凌波": {
      "人物经历": {
        "第6回-11-洪凌波逼经杨过智擒李莫愁现身": "趁师父派去长安杀仇家之机径上终南山来。在山脚遇杨过装傻——被问路后使出古墓派功夫腰带缠其右足拉回，逼他带路去古墓。被杨过一路上装傻戏弄，揽着他上山时被重重踹脚背。到墓前杨过警告树林有鬼，听他说到大坟女鬼之事后大喜——确知活死人墓在此。随杨过入墓见他熟悉异常暗暗生疑。点烛见小龙女卧床重伤病容，自称弟子拜见师叔。小龙女命其出去时反放下提防，用冰魄银针威逼小龙女交出玉女心经。小龙女急怒晕去时正自得意，不料杨过扑过来抱住背心被点中肩贞京门巨骨三穴，全身酸麻软瘫在地。见杨过拾起银针要刺她吓得魂飞魄散。"
      }
    },
    "李莫愁": {
      "人物经历": {
        "第6回-11-洪凌波逼经杨过智擒李莫愁现身": "早料到洪凌波要自行来盗玉女心经，派她到长安杀人实为有意安排。一直悄悄跟随其后——见到洪凌波如何与杨过相遇入墓逼经中计失手，始终未被察觉。直至洪凌波被杨过点中穴道方才现身，站在门口叫'师妹你好啊我早来啦'，冷指杨过问祖师婆婆遗训古墓不准臭男子踏进一步为何容他在此。拂尘挥动使出三燕投林却被杨过轻描淡写闪开，暗暗吃惊认出是本门武学。"
      }
    },
    "杨过": {
      "人物经历": {
        "第6回-11-洪凌波逼经杨过智擒李莫愁现身": "遇洪凌波问路装傻不答。见洪凌波使锦笔生花剑法认出是古墓派功夫——心中更无疑惑她是李莫愁弟子来找姑姑麻烦。装傻到底被腰带缠足拉回也不抵抗。依命取短斧披破衣被揽上山时故意跌撞重踹她脚背。说树林有鬼大坟住女鬼引洪凌波确信古墓所在。黑暗中熟门熟路东转西绕带洪凌波入墓至小龙女卧室。见小龙女轻嗯一声忍不住大哭。见洪凌波用冰魄银针逼小龙女献经，假称有鬼扑过去抱住她背心点中肩贞京门巨骨三穴将其制服。拾起银针裹指要刺她时忽听身后李莫愁娇媚声音响起。"
      }
    }
  },
