    "时": 15
  },
  "事件结束时间": {
    "年": 1244,
    "月": 10,
    "日": 28,
    "时": 16
  },
  "事件引子": "金轮法王明已得手却被杨过搅局——连自己纵横无敌的金轮也被打落在地。这是生平从所未遇的大挫折。盛怒之下再也顾不得宗师身份——不待杨过起身呼的一掌劈空击去。",
  "后续事件": {
    "事件名": "无",
    "描述": "蒙古众人退去后陆家庄欢声雷动——武林盟主之位终究归了中原。但金轮法王既已记下这笔仇怨，誓必再图报复。而英雄大宴的余韵尚在，众人还要商议共御外侮的大计。"
  },
  "事件详情": "金轮法王明已得手却被杨过搅局——连自己纵横无敌的兵刃也被他打落在地，盛怒之下呼的一掌劈空向尚未起身的杨过击去。郭靖见他抬肩缩臂知要猛下毒手——危急中不及细思一招'飞龙在天'跃在空中向他头顶搏击下来。金轮法王掌力急转回掌与郭靖相交——这是两位武学大师的二次交掌。郭靖人在半空无从借力——顺势翻半个筋斗向后落下消解掌力。金轮法王虽稳站原地却大耗内气真气——胸口凝住一股滞气。杨过死里逃生后爬起身来奔向小龙女——两人齐声互问你没事么，同时点头双手互握满心喜悦。杨过随即举起金杵将金轮顶在杵上耍盘子般转动——高声叫道'蒙古众武士听者——你们大国师的兵刃已给我缴下还说什么天下武林盟主'。金轮法王正暗运内力打通胸口滞气——杨过见情状猜到三分，忙一口气连问三声'你是不是输了'——乘法王无法开口抢先说是认输。随即将金杵金轮交给郭靖。金轮法王气得脸皮紫胀——忌惮郭靖武功又见中原武士人多势众，只得说'中原蛮子诡计多端倚多为胜'——右手一挥率蒙古众武士向厅外退出。杨过想起霍都中毒之事叫换解药——金轮法王自恃玄功通神不理会径自去了。陆家庄前前后后欢声雷动——为杨过与小龙女力胜金轮法王喝彩。",
  "事件概要": "郭靖再度出手逼退金轮法王，杨过顺势夺下金轮，中原群雄得以保住英雄宴胜局。",
  "update": {
    "金轮法王": {
      "状态": "含恨率众退出陆家庄（两个徒弟皆败于杨过之手——连自己的金轮也被杨过打落。与郭靖二次对掌虽占上风内里吃亏。被杨过乘自己运气不能开口时抢先逼问'认输'——脸皮紫胀却无可奈何。元气未复不敢以空手与郭靖争金轮——只得率众退走。对杨过恨之入骨誓必再图报复）",
      "所在位置": "大宋/大胜关/陆家庄外",
      "人物经历": {
        "第13回-08-金轮法王盛怒对杨过下杀手被郭靖所阻含恨退走": "盛怒之下一掌劈向杨过——郭靖飞身跃起以'飞龙在天'搏击头顶。掌力急转与郭靖二次交掌——郭靖顺势翻筋斗消解掌力，金轮法王稳站原地却大耗内气真气胸口凝住滞气。暗运内力打通滞气时——杨过一口气连问三声自己是否输了。气得脸皮紫胀——又忌惮郭靖武功金轮落入他手自己空手难夺。见中原武士人多势众己方一群斗定要一败涂地——只得说'中原蛮子诡计多端倚多为胜不是英雄好汉'率众退出。向郭靖遥施礼说'青山不改绿水长流咱们后会有期'——袍袖飘动转身向外头也不回大踏步出厅。杨过叫以解药交换霍都的解药——毫不理睬径自去了"
      },
      "关系网": {
        "郭靖": "对手/55（二次对掌已领教郭靖的降龙十八掌凌厉无伦——知此人武功与自己不相上下。对郭靖的武功既忌惮又不得不佩服——'郭大侠黄帮主今日领教高招'）",
        "杨过": "刻骨仇敌/-90（纵横无敌的金轮被打落、两个徒弟被击败、武林盟主之位被夺——全拜这个十六岁少年所赐。恨极杨过狡猾无礼——见他举金轮耍弄气极却无法开口。对杨过的每一句话都听得清清楚楚——心中恼怒愈甚）"
      }
    },
    "郭靖": {
      "人物经历": {
        "第13回-08-郭靖二次救杨过与金轮法王对掌收回金轮": "见金轮法王怒视杨过抬肩缩臂要下毒手——暗叫不好。危急中一招'飞龙在天'跃在空中向法王头顶搏击——掌力相交顺势翻了半个筋斗向后落下消解敌力。杨过将金杵金轮交给他后——待要还给法王却被杨过高声叫住嘲讽法王。向金轮法王躬身答礼——'大师武功精深在下佩服得很贤师徒的兵刃就请取回'。金轮法王袍袖飘动大踏步而去"
      },
      "关系网": {
        "金轮法王": "对手/55（二次对掌——以武学正道顺势退让消解掌力。对法王武功精深表示佩服——仍以礼相待要归还兵刃。对金轮法王的人品已有警惕——知其因杨过搅局而衔恨在心）"
      }
    },
    "杨过": {
      "状态": "大获全胜意气风发（连胜霍都和达尔巴两场——又救下师父缴了金轮法王的兵刃逼退蒙古众人。牵着小龙女的手双手互握满心喜悦。成为英雄大宴上力挽狂澜的少年英雄）",
      "人物经历": {
        "第13回-08-杨过终局逼退金轮法王被群雄喝彩": "金轮法王掌劈时被郭靖救下死里逃生——爬起身奔向小龙女身旁二人双手互握满心喜悦。举起金杵将金轮顶在杵上耍盘子般转动——高声叫道'蒙古众武士听者你们大国师的兵刃已给我缴下还说什么天下武林盟主'。见金轮法王正暗运内力不敢开口说话——忙抢在头里一口气连问三声'你是不是输了''你默不作声就是认输'。随即将金杵金轮交给郭靖——怕师父抵挡不住金轮法王来夺。听蒙古武士纷嚷又向法王说'还不认输你的兵刃都失了还有什么脸面'。叫住法王要以解药交换霍都之毒——法王不理径去。陆家庄欢声雷动——众人围集议论他打败霍都报以其人之道还治其人之身"
      }
    },
    "小龙女": {
      "人物经历": {
        "第13回-08-小龙女与杨过共享胜利喜悦": "杨过脱险后也正过来探视——两人齐声互问你没事么，同时点头双手互握满心喜悦。对武林盟主之名毫不在意——只要杨过平安无事便心满意足"
      }
    },
    "黄蓉": {
      "人物经历": {
        "第13回-08-黄蓉观金轮法王退走": "见朱子柳合上眼沉沉睡去——心想此间聚集了不少使用喂毒暗器的名家总有人能治得他身上之伤。见金轮法王不肯交换解药——却也不甚在意"
      }
    }
  },
  "参与人物": [
    "金轮法王",
    "杨过",
    "郭靖",
    "小龙女"
  ]
}

