  "事件引子": "你听说活死人墓外树林中有人闯入了禁地，被玉蜂蜇伤昏倒……",
  "后续事件": {
    "事件名": "第5回-02-孙婆婆拒交杨过斗全真群道",
    "描述": "孙婆婆带杨过出墓，恰遇全真教道人前来索人，双方冲突一触即发"
  },
  "事件详情": "杨过从小较中逃出后在树林中慌不择路，终因体力不支摔下山坡，滚入长草丛中昏晕过去。不知过了多久，他忽觉身上刺痛，睁眼见无数白色蜂子在身周飞舞，全身奇痒入骨又晕了过去。活死人墓中的孙婆婆听到玉蜂异动，出外查察，发现杨过已中毒晕倒，念他年幼且遍体伤痕，破例违抗门规将他救入墓中，以冰凉清香的玉蜂浆灌入其口中解毒。杨过醒来见到一张生满鸡皮疙瘩的丑脸正瞪着自己，虽惊却不害怕，因那笑容中含着仁慈温柔。杨过出言相谢后忍不住求婆婆别让师父来捉他。此时帷幕掀开，一个白衣如雪、容貌清丽绝俗的少女走了进来——正是活死人墓主人小龙女。她虽秀丽出尘却冰冷淡漠，令杨过心生恐惧。孙婆婆让杨过讲述身世遭遇，听得不住叹息，对黄蓉偏袒、赵志敬欺人连连斥责。小龙女却始终不动声色。待杨过讲完，小龙女站起来冷冷命孙婆婆送他出去。杨过大嚷死也不回去，孙婆婆求情亦被回绝。",
  "事件概要": "孙婆婆救回昏迷的杨过并带入古墓，杨过因此脱离全真追索，命运开始转向古墓派。",
  "insert": {
    "孙婆婆": {
      "人物经历": {
        "第5回-01-孙婆婆救杨过入古墓": "听到玉蜂声音知有人闯入墓地外林，出外查察见杨过已中毒晕倒、遍体伤痕。心下不忍破例相救——抱入墓中以玉蜂浆解毒。见杨过醒来后举止有礼人品俊秀，心中说不出的喜爱。听杨过讲述身世遭遇后不住叹息，语语护着杨过斥责黄蓉偏袒女儿、赵志敬心胸狭隘"
      }
    },
    "小龙女": {
      "人物经历": {
        "第5回-01-孙婆婆救杨过入古墓": "听孙婆婆说有个孩子哭个不停，掀开幕帷走进来察看。见杨过头上被玉蜂蜇刺的伤势，伸手摸他额角看是否发烧——手掌寒冷异常令杨过打个冷战。淡淡说已喝玉蜂浆半天就好。听杨过讲述身世遭遇时始终不动声色，悠悠闲闲坐着，只在听到李莫愁之事时与孙婆婆对望数眼。待杨过讲完便命孙婆婆送他出去"
      },
      "关系网": {
        "杨过": "闯入墓地的陌生少年/15"
      }
    },
    "杨过": {
      "人物经历": {
        "第5回-01-孙婆婆救杨过入古墓": "摔在山坡滚入树林长草丛中昏晕。被玉蜂蜇伤全身奇痒入骨。苏醒时觉口中灌入冰凉清香的甜浆。睁眼见一张奇丑却含仁慈温柔之意的脸。向孙婆婆和小龙女磕头拜见。孙婆婆问起遭遇时将身世从头至尾说了——口齿伶俐加之新遭折辱言语更加激动。见小龙女容貌清丽冰冷淡漠竟自心生恐怖。听到小龙女命送自己出去时大嚷死也不回去"
      },
