    "日": 10,
    "时": 10
  },
  "事件引子": "你听说潼关道上出了件奇事——一个小道士自称全真教门下，向赤练仙子的弟子借剑去斗丐帮两个八袋老丐，竟以一敌二将人打得直追了二里地……",
  "后续事件": {
    "事件名": "第9回-05-逆行经脉夺拂尘逃逸",
    "描述": "杨过还剑洪凌波时李莫愁叫住了他"
  },
  "事件详情": "天亮后杨过将墨水抹在陆无双脸上，又用煤灰和水涂了自己满脸，将申志凡姬清虚穴道踢开后离开客店。买了两匹劣马向东南行去。行了一个多时辰后休息时，道路转角处两个背负八只布袋的老丐并肩走来，二丐身后申志凡和姬清虚一探头就缩了回去——原来三个道士已告知丐帮二人改了道人打扮。两个老丐拦住去路要押二人去执法长老跟前评理。就在此时西北方金铃响起，李莫愁洪凌波已赶到。李莫愁见四人剑拔弩张的样子欲袖手观斗。杨过灵机一动，转身走到洪凌波跟前嘶哑着嗓子打问讯借剑，称自己是全真教门下被恶丐拦截。洪凌波望师父点头后将剑倒转递过。杨过生怕老丐揭破陆无双秘密，挺剑抢上分刺二人胸口小腹，使出全真派\"一气化三清\"剑术——他化不来三清，但化二清倒也似模似样，每一剑一分为二刺出时只有一招手腕抖处剑招分而为二。两个老丐辈份虽高竟全然抵挡不住，他一十八剑刺过二丐倒退五十四步一招也还不了手。李莫愁在旁看得暗暗心惊，心道全真教果真人才辈出。杨过又施展轻功绕二丐急转圈圈——步伐是全真派身法，呼吸运气却是古墓派轻功心法，天下无双。他如鬼魅般在二丐背后穿梭，长剑如白光闪烁。急转数十圈后二丐累得头晕眼花脚步踉跄几欲晕倒。杨过追出两里有余，笑嘻嘻放慢脚步夺了二丐铁棒又双手捧还，指着李莫愁说：'赤练仙子明明在此，两位何不找她去？'又以'萨华滋'（杀化子）假名戏弄二丐后方回返。",
  "事件概要": "杨过借剑挑起丐帮与李莫愁对峙后脱身，二老被迫卷入，追兵局面愈发复杂。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第9回-04-借剑斗丐退二老": "离开客店后先在陆无双和自己脸上涂了墨水煤灰改装。骑马行一个多时辰后休息时遇两个八袋老丐拦路——申志凡姬清虚已将二人改装之事告知丐帮。李莫愁洪凌波赶到时杨过急中生智走向洪凌波借剑，自称全真教门下遭恶丐拦截。生怕二丐揭穿陆无双秘密，抢先出剑以全真派'一气化三清'剑术分攻二人——化不来三清但化二清也已似模似样，一十八剑逼退二丐五十四步。又施展古墓派轻功绕二丐急转圈圈将人拖得头晕眼花，直追出二里夺下铁棒。假意客气归还后又以言语激二丐去找李莫愁算账，自报假名'萨华滋'（杀化子）戏弄二丐后得意离去。李莫愁在旁袖手观斗竟看不出他全真剑法似是而非。"
      }
    },
    "陆无双": {
      "人物经历": {
        "第9回-04-借剑斗丐退二老": "被杨过在脸上涂了淡墨水易容，见两名八袋老丐拦住去路心中叫苦——偏巧自己改了装束仍被化子撞上，若被他们揭穿身份师父转眼就到。见杨过向洪凌波借剑自称全真教门下，心中大为担忧——师父与全真教大小十余战，全真派武功哪一招一式逃得过她眼去？在旁观杨过以全真剑法斗八袋老丐，见李莫愁未曾识破才松了口气。杨过借剑斗丐、巧言激将、假名戏弄的智计令她又惊又服。"
      }
    },
    "李莫愁": {
      "人物经历": {
        "第9回-04-借剑斗丐退二老": "在路上见两个小道士与两个八袋老丐对峙，认出两个小道士背影似曾见过。袖手旁观杨过向洪凌波借剑斗丐，见小道士全真剑法精奇暗暗心惊，心道再过十年自己哪里还是他对手。看杨过以轻功戏弄二丐占尽上风，对全真教名头更加忌惮。始终未看出杨过剑法似是而非底子其实是古墓派功夫。"
      }
    },
    "洪凌波": {
      "人物经历": {
        "第9回-04-借剑斗丐退二老": "在路上遇杨过扮作的小道士打问讯借剑，见他说到太上老君不便拒却，望师父点头后将剑倒转递过。在旁观看小道士以全真剑法独斗两名八袋老丐，剑法精奇神驰目眩——万万料不到这小道士便是先前在古墓中和自己交手的杨过。"
      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/终南山/潼关道",
      "状态": "逃亡中（借洪凌波剑以全真剑法退两名八袋老丐，又以'萨华滋'假名戏弄丐帮后回返。改装易容仍被丐帮认出，危机一重接一重）"
    },
    "陆无双": {
      "所在位置": "大宋/终南山/潼关道",
      "状态": "逃亡中（脸上涂墨易容仍被丐帮认出，在旁观杨过斗丐帮八袋老丐又惊又服。危机四伏中全靠傻蛋智计周旋脱身）",
      "关系网": {
        "杨过": "救命恩人/75（借剑斗丐巧言退敌的智计胆略令她又惊又服——他虽疯疯癫癫却总是在最危急关头化险为夷）"
      }
    },
    "李莫愁": {
      "状态": "追捕中（在路边袖手旁观两个小道士与丐帮化子冲突，对全真教小道士剑法精奇暗暗心惊，仍不知这便是杨过）"
    },
    "洪凌波": {
      "状态": "随师追捕（被小道士借去长剑，旁观其独斗两名丐帮八袋老丐精奇剑法，心中惊佩不已）"
    }
  },
  "参与人物": [
    "杨过",
