  },
  "事件结束时间": {
    "年": 1238,
    "月": 8,
    "日": 13,
    "时": 20
  },
  "事件引子": "陆家庄大厅墙壁上赫然印着三排九个殷红如血的手掌印，庄主陆立鼎面色凝重，似是预感到了什么可怕的灾祸。",
  "后续事件": {
    "事件名": "第1回-03-陆家庄夜来不速客",
    "描述": "武三娘携二子前来陆家庄借宿，带来了新的变数与转机。"
  },
  "事件详情": "程英与陆无双逃回陆家庄，陆无双一路大嚷'疯子在挖大伯大妈的坟'。父亲陆立鼎正抬头呆望厅壁——墙上赫然印着三排九个殷红如血的手掌印，触目惊心。陆立鼎闻言大惊，提刀急奔兄嫂坟前，只见坟墓已被挖破，棺木打开，石灰纸筋凌乱不堪，尸首却踪影全无。他又惊又怒，想起兄长陆展元临终遗言：有个叫李莫愁的道姑，外号'赤练仙子'，武功高强且心狠手辣，当年因情变之恨声言十年之后必来报仇。她杀人之前会在墙上留下血手印，一个手印便是一条人命。陆立鼎掐指一算，今日正是十年之期。可陆家庄连主带仆不过七口人，墙上却有九个血手印。他呆坐厅中望着血手印，心中寒意阵阵，大祸临头之感压得他透不过气来。",
  "事件概要": "陆立鼎确认血手印与掘坟皆出自李莫愁，陆家庄正式进入十年前旧仇兑现之夜，满庄性命危在旦夕。",
  "insert": {
    "陆立鼎": {
      "人物经历": {
        "第1回-02-陆立鼎惊见血手印": "女儿陆无双和姨甥女程英从湖边归来，报告有人掘兄嫂坟墓。陆立鼎提刀急奔坟前，见坟墓已破、棺木打开、尸首无踪，又惊又怒。回到庄中细看墙上九个血手印，想起兄长陆展元临终遗言——赤练仙子李莫愁十年之期已到。掐指一算，今日正是十年期满，心中寒意阵阵，忧虑万分。"
      }
    },
    "程英": {
      "人物经历": {
        "第1回-02-陆立鼎惊见血手印": "与表妹陆无双逃回陆家庄后，向姨丈陆立鼎证实武三通掘墓之事，看到厅壁上的九个血手印，虽不明所以，也感到气氛异常紧张。"
      }
    },
    "陆无双": {
      "人物经历": {
        "第1回-02-陆立鼎惊见血手印": "奔回陆家庄后大声叫嚷'疯子在挖大伯大妈的坟'，向父亲咭咭咯咯讲述湖边遭遇。看到墙上的血手印，却不知这背后的凶险。"
      }
    },
    "陆二娘": {
      "人物经历": {
        "第1回-02-陆立鼎惊见血手印": "从丈夫口中得知墙上血手印为赤练仙子李莫愁所留，兄嫂坟墓被盗尸，心惊担忧，开始寻思如何躲避灾祸、保护两个孩子。"
      }
    }
  },
  "参与人物": [
    "程英",
    "陆无双",
    "陆立鼎"
  ]
}

