  },
  "事件详情": "杨过与小龙女在猎户小屋中围着火堆烤獐肉喂郭襄时，东边传来踏雪之声。杨过不愿见世人，让小龙女抱郭襄进内室假装生病。他自己抓起柴灰涂抹脸颊，将帽沿压低，又将玄铁剑藏入内室，在衣衫上乱抹獐肉油腻，装扮成穷猎户模样。两个丐帮中人——一胖一瘦的老者来拍门借宿。杨过粗声粗气应付二人，给他们两条烤獐腿，假称明早要去装机捉狐狸。他走进内室与小龙女配合演戏——小龙女咳嗽装病，又摇醒郭襄让婴孩哭叫，一家三口装得维妙维肖。杨过在板壁缝中偷听二丐谈话，听到瘦丐提及终南山大火和蒙古军剿灭全真教之事，又听彭长老得意洋洋谈论蒙古皇帝要封他做'镇南大将军'、建立南派丐帮。杨过猛地记起这胖老丐曾在大胜关英雄会上穿着蒙古装束为金轮法王献策，正是丐帮中降了蒙古的叛徒彭长老，顿时起了除奸之心。",
  "事件概要": "杨过识破彭长老叛蒙图谋并决意除奸，猎户小屋的短暂安稳转为一场暗中的清算与试探。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第30回-01-杨过伪装猎户接待二丐偷听阴谋": "在猎户小屋中听到踏雪声，让小龙女抱郭襄进内室装病。以柴灰涂面、帽檐低压、獐肉油腻抹衣装扮成穷猎户。给二丐獐腿充饥，与小龙女合演一家三口猎户的戏码——咳嗽声夹婴孩哭叫维妙维肖。在板壁缝中偷听二丐谈话，认出胖丐是当日大胜关见过的蒙古奸细彭长老，得知其欲建南派丐帮投靠蒙古的阴谋，暗起除奸之心"
      }
    },
    "小龙女": {
      "人物经历": {
        "第30回-01-杨过伪装猎户接待二丐偷听阴谋": "依杨过安排抱郭襄进内室躺在床上装病。配合杨过大咳几声，又以婴孩哭叫作掩护，将一家猎户演得维妙维肖。一生从不作伪，这般精灵古怪的勾当想都没想过，只因眼见杨过喜欢便顺着他玩闹"
      }
    },
    "郭襄": {
