  },
  "事件引子": "你听说嘉兴郊外突然响起两股声震数里的长啸——一雄壮、一清亮，如大鹏小鸟比翼齐飞，惊得三大高手各自远遁。",
  "后续事件": {
    "事件名": "第2回-10-郭靖带杨过回客店寻药疗伤",
    "描述": "杨过惊厥晕倒，郭靖又惊又喜发现他是杨康之子，夫妻二人抱他回到客店配药救治"
  },
  "事件详情": "郭靖沉思半晌忽然张口长啸，那少年耳畔异声陡发吓了一跳。啸声远远传送出去，惊得雀鸟四下乱飞，柳枝垂条震动不已。他一啸未已第二啸跟着送出，啸上加啸声振重叠，犹如千军万马奔腾远去。黄蓉知道丈夫在发声向李莫愁挑战，当下气涌丹田跟着发声长啸——郭靖啸声雄壮宏大，黄蓉清亮高昂，两股啸声交织在一起，有如大鹏与小鸟比翼齐飞越飞越高，小鸟竟始终不落大鹏之后。夫妻二人在桃花岛潜心苦修内力已臻化境，双啸齐作回翔九霄声闻数里。那倒行怪人欧阳锋听到啸声足步加快疾行而避；抱着程英的青袍客黄药师听到啸声哈哈一笑说'他们也来啦，老子走远些免得啰嗦'；挟着陆无双奔行的李莫愁听到啸声，先是冷笑停下要会郭靖，听到黄蓉啸声相和后心中一凛万念俱灰，叹了口长气抓着陆无双去了。此时武三娘已扶丈夫带同二子与柯镇恶作别离去。柯镇恶带郭芙循啸声奔来，郭芙投入黄蓉怀里撒娇。郭芙随即向杨过招手叫他去摘花编花冠，瞥见他手掌漆黑便嫌他手脏不跟他玩。杨过最恼被人小看冷然便走，郭靖追上询问他却自称'姓倪名字叫作牢子'（你老子），还在骂人。黄蓉见他狡猾惫懒神情与杨康极为相似，出手按住他后颈运劲试他——杨过运力相抗时黄蓉劲力忽松，杨过不由自主仰天一交摔倒。黄蓉凝视他双眼缓缓道：'你姓杨名过，你妈妈姓穆，是不是？'杨过惊骇无比胸间气血上涌手上毒气回冲，脑中一阵糊涂登时晕了过去。原来黄蓉记得当年王处一试穆念慈武功——洪七公独门运功使力法门前跌后仰正是其标志，一试之下便揭穿杨过真实身份。",
  "事件概要": "郭靖黄蓉以啸声震慑群敌，杨过的真实身份与去留随之明朗，李莫愁一方不敢轻犯。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第2回-09-郭黄双啸惊群雄黄蓉智识杨过": "被郭靖长啸吓了一跳，又被郭芙嫌手脏不跟他玩刺伤自尊。郭靖追上问姓名时故意说'姓倪名字叫作牢子'（你老子）讨便宜，又挥拳打郭靖小腹反被吸住拔不出手。黄蓉以洪七公独门运气法门相试——按住他后颈运劲忽松，杨过仰天一交跌倒。黄蓉说出'你姓杨名过，你妈妈姓穆'后，杨过惊骇无比，胸间气血上涌毒气回冲，脑中糊涂晕了过去"
      }
    },
    "郭芙": {
      "人物经历": {
        "第2回-09-郭黄双啸惊群雄黄蓉智识杨过": "在柯镇恶带领下循父母啸声会合，投入黄蓉怀里撒娇说'大公公刚才打跑了一个恶女人，他老人家本事可大得很哩'，被郭靖斥责要老实说话。向杨过招手叫他摘花编花冠，见其手掌漆黑嫌脏不跟他玩，见杨过摔倒后又拍手大笑"
      }
    },
    "郭靖": {
      "人物经历": {
        "第2回-09-郭黄双啸惊群雄黄蓉智识杨过": "张口发出长啸向李莫愁挑战，啸声如千军万马奔腾而去。黄蓉附声长啸，双啸交织远传数里。见女儿郭芙归来欣慰不已。追上离去的杨过询问姓名，腹肌吸住杨过拳头却毫不在意。听杨过自称'倪牢子'（你老子）只觉好笑。黄蓉揭破杨过身份后，郭靖又惊又喜——他果然是结义兄弟杨康的儿子"
      }
    },
    "黄蓉": {
      "人物经历": {
        "第2回-09-郭黄双啸惊群雄黄蓉智识杨过": "附声与丈夫同时长啸，啸声清亮高昂如小鸟比翼大鹏越飞越高。见杨过狡猾惫懒神情与杨康极为相似，以洪七公独门运功法门试他武功家数——按住后颈运劲，杨过往后跌而非前倾——这正是洪七公独门路数，穆念慈的武功渊源。黄蓉凝视杨过双眼说出他的真名实姓，杨过惊骇晕倒，黄蓉急忙扶住"
      }
    },
    "柯镇恶": {
      "人物经历": {
        "第2回-09-郭黄双啸惊群雄黄蓉智识杨过": "适才一番剧战后怕李莫愁去而复返带郭芙找隐蔽处躲藏。听到郭靖黄蓉啸声大喜，带郭芙循声会合"
