{
  "事件地点": "大宋/绝情谷/丹房",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 11,
    "日": 29,
    "时": 6
  },
  "事件结束时间": {
    "年": 1244,
    "月": 11,
    "日": 29,
    "时": 7
  },
  "事件引子": "杨过久等公孙绿萼不归出门寻找。发现公孙止正在丹房审问女儿——追问绝情丹下落。绿萼宁死不肯出卖杨过，公孙止竟亲挥黑剑欲杀亲生女儿。杨过飞身闯入——二人一同坠入丹房下深渊。",
  "后续事件": {
    "事件名": "第19回-01-鳄潭杀鳄得周伯通遗物",
    "描述": "杨过与公孙绿萼坠入丹房下的深渊水中。黑暗中杨过双手托住绿萼护她性命。深渊之下不知是生是死——绝情谷的风波远未结束。"
  },
  "事件详情": "杨过等了良久始终不见公孙绿萼现身，越等越担忧——纵然取药不得她也必过来告知，瞧来此事凶多吉少。于是溜出石室却不知公孙绿萼陷身何处。忽听转角处脚步声响——两名绿衫弟子各执荆杖而去。杨过大怒以为公孙止要对小龙女动刑逼迫，放轻脚步跟随在后。来到一间石室前从窗中向内张望——不见小龙女却见公孙绿萼垂首站在父亲之前。公孙止接过荆杖追问女儿为何叛己——'你看中了那姓杨的小子我岂有不知'。公孙绿萼朗声道'女儿钦慕杨公子为人正派有情有义。但女儿知他心目中只有龙姑娘一人。女儿所以救他就是瞧不过爹爹的所作所为别无他意'。公孙止问绝情丹下落，绿萼否认拿丹说她去丹房找了半天没找到。谷主厉声追问，公孙绿萼指着四名弟子要先叫他们出去——然后解去外衫裙子只留贴身小衣，证明身上并无丹药。杨过在窗外见她全身晶莹洁白心中怦的一动——随即自责此时若再看一眼便是禽兽不如急忙闭眼，但心神烦乱之际额头碰到窗格子发出微声。公孙止知觉后将三座丹炉推移将丹藏好，假意允诺饶杨过性命。随即以谷规擅入丹房者处死之名要杀女儿。绿萼低声说'饶他'——宁死不肯求饶。公孙止抽出黑剑挥剑往她头顶直劈下去。杨过大惊从窗口飞身跃入大叫'且慢'又跟着叫'该当杀我'——右足落地突觉足底一软似踏了个空。公孙止双掌在女儿肩头一推——公孙绿萼身不由主撞向杨过。二人一齐笔直堕下，杨过危急中双手将绿萼身子托起护住她性命。眼前一片黑暗足底空虚——扑通一声两人摔入水中往下急沉——丹房下竟是个深渊。",
  "事件概要": "公孙止挥剑逼杀亲女，杨过与公孙绿萼同坠深渊，绝情谷风波转入地底绝境。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第18回-12-飞身救公孙绿萼同坠深渊": "久等公孙绿萼不归出去寻找。发现公孙止正在审问女儿并以荆杖威逼。见公孙绿萼为保自己宁可解衣受辱——心中怦动随即自责。公孙止挥剑杀女时大叫'且慢'飞身从窗口跃入丹房——跟着叫'该当杀我'。右足落地踏中机关陷阱——公孙止推女儿撞向杨过。二人一同坠入丹房下深渊。危急中双手将公孙绿萼身子托起护住她性命。扑通摔入水中下沉——黑暗中不知将落于何处生死未卜。"
      },
      "关系网": {
        "公孙绿萼": "生死相依/90（公孙绿萼为救自己不惜解衣受辱宁死不肯出卖——杨过飞身闯入丹房救她。二人同坠深渊——杨过危急中托住她身子护她性命。二人命运已被深渊紧紧绑在一起——同生共死患难与共）",
        "公孙止": "仇敌/誓死对抗（公孙止以情花酷刑逼小龙女就范、审问亲生女儿挥剑欲杀、推女儿与杨过同坠深渊——此人之阴险狠毒已至极点。杨过与他已是不共戴天）"
      }
    },
    "公孙绿萼": {
      "人物经历": {
        "第18回-14-父亲挥剑欲杀与杨过同坠深渊": "宁死不肯求饶——低声说出'饶他'任父亲挥剑劈下。被公孙止推肩撞向杨过——二人一同坠入丹房下的深渊。在急坠的黑暗中感受到杨过将自己身体托起护住——心中既是恐惧又是温暖。扑通摔入水中下沉——与杨过同命相连暗夜深渊生死未卜"
      },
      "关系网": {
        "公孙止": "父女已破裂/5（父亲亲手挥剑要杀她、推她坠入深渊。父女之情已荡然无存——她心中既痛且寒。'女儿钦慕杨公子为人正派有情有义。女儿所以救他就是瞧不过爹爹的所作所为'——这是她一生中最勇敢的宣言）",
        "杨过": "倾慕/90（倾心钦慕——明知杨过心中只有龙姑娘一人仍甘冒生命危险舍命相救。杨过飞身入丹房救她反同坠深渊——二人命运已被紧紧绑在一起。在深渊黑暗中杨过托住她身子护她性命——这份情义刻骨铭心）"
      }
    },
    "公孙止": {
      "人物经历": {
        "第18回-14-设陷阱推女儿与杨过同坠深渊": "在女儿面前设下巧妙陷阱——将三座丹炉推移转位藏好绝情丹。假意允诺饶杨过性命骗得女儿信任。以谷规'擅入丹房者死'之名亲挥黑剑杀女。杨过闯入后趁机双掌推女儿撞向杨过——令二人一同跌入丹房下深渊。面不改色心不跳——对自己的亲生女儿和外人痛下杀手眼都不眨"
      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/绝情谷/鳄潭",
      "状态": "与公孙绿萼一同坠入丹房下深渊——坠下数十丈后双双摔入水中。危急中双手托住公孙绿萼护住她性命。黑暗中不知深渊通向何处——生死未卜。身中情花剧毒又坠深渊——然求生之念未灭心中想着要救小龙女要报父仇"
    },
    "公孙绿萼": {
      "所在位置": "大宋/绝情谷/鳄潭",
      "状态": "与杨过一同坠入丹房下方的深渊水中——被杨过双手托住护着。父亲竟要亲手杀自己心中冰凉比深渊之水更寒。黑暗中惶恐不安却因有杨过在身边而感到一丝温暖与依靠"
    },
    "公孙止": {
      "所在位置": "大宋/绝情谷/丹房",
      "状态": "已将杨过和女儿公孙绿萼一同推入丹房深渊。小龙女虽已当面允婚但实非真心情愿——今晚洞房花烛再做计较。金轮法王等外人尚在大厅——须得一并处置以免后患"
    }
  },
  "参与人物": [
    "杨过",
    "公孙绿萼",
    "公孙止",
    "小龙女"
  ]
}

