{
  "事件地点": "大宋/终南山/潼关道",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 9,
    "日": 9,
    "时": 22
  },
  "事件结束时间": {
    "年": 1244,
    "月": 9,
    "日": 10,
    "时": 7
  },
  "事件引子": "你听说潼关道一家客店里出了怪事——一个老道人自称重阳真人的弟子，还有个年轻道姑是赤练仙子李莫愁，把客店闹得天翻地覆……",
  "后续事件": {
    "事件名": "第9回-04-借剑斗丐退二老",
    "描述": "天亮后杨过与陆无双改装涂面离开客店，在道上遇丐帮八袋老丐和李莫愁"
  },
  "事件详情": "杨过与陆无双在市镇客店住下正要吃饭，门口人影一闪，申志凡与姬清虚探头进来见到二人即缩头，侧身掠过奔入大堂抢向陆无双。就在此时蓦地里传来叮玲叮玲一阵铃响——李莫愁师徒已到客店门口。洪凌波飕的一声上了屋顶把守；李莫愁最恨别人提\"老\"字，听掌柜称呼\"老人家\"拂尘挥出立时送了他的老命。杨过欲从后门溜走，忽听东角落里一个青衫客人站起来低声道：\"我来设法引开敌人，快想法儿逃走。\"说罢走出大门。猛听得铃声大振向北响去——原来青衫客骑走了李莫愁的花驴。李莫愁追出后杨过灵机一动闯进申志凡姬清虚房间，不容二人站起手指连挥点倒二人，招呼陆无双换上道袍。陆无双换衣时发现炕上棉被中还探出一个道士头——竟是重伤养病的皮清玄。杨过将皮清玄提起塞入炕底，又将申志凡也塞了进去，解开姬清虚穴道按住其背心死穴。李莫愁二次来搜，见房中仍是三个道士，姬清虚脸如死灰，不疑有它便搜第二间房去。杨过点倒姬清虚后与陆无双在炕上并头躺卧，闻到她身上少女温馨香味不禁大乐。陆无双心中思潮起伏一动不敢动。次日清晨杨过醒来见陆无双双颊晕红唇瓣微翘，情窦初开伸头要去亲她口唇。尚未触到已闻一阵香甜，心中一荡热血上涌，瞥见她睡梦中微蹙的双眉想起断骨之痛，登时想起小龙女及自己立的誓言，全身冷汗直冒，拍拍打了自己两个耳光。陆无双惊醒问他干什么，他含糊道蚊子咬脸。陆无双想起整晚同睡满脸通红，低唤\"傻蛋，傻蛋\"，话声竟大有温柔缠绵之意。",
  "事件概要": "客店再遭围堵时青衣女郎出手相助，杨过与陆无双得以脱身，也记下这笔救命之恩。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第9回-03-客店扮道士避李莫愁": "客店中遇申志凡姬清虚来袭，李莫愁突然赶到杀掌柜搜店。一神秘青衫客骑走李莫愁花驴引开追兵。杨过急智闯进申姬房间点倒二人，与陆无双换上道袍扮成道士。又把皮清玄塞入炕底藏匿。李莫愁二次来搜——按住姬清虚死穴逼其配合，李莫愁未认出。与陆无双同卧一炕辗转难眠，闻她身上少女馨香大乐，陆无双也思潮起伏。晨醒见陆无双睡容心中大动伸头要亲她，尚未触到已闻香甜热血直涌——猛然想起小龙女立过的誓言，冷汗直冒打了自己两个耳光。被陆无双问时含糊答蚊子咬脸。心中深深自责对不住姑姑。"
      }
    },
    "陆无双": {
      "人物经历": {
        "第9回-03-客店扮道士避李莫愁": "客店中正吃饭时见申志凡姬清虚来寻仇，紧接着师父李莫愁铃声响起吓得魂飞天外。被杨过叫进二道房间换上道袍扮作道士，换衣时发现皮清玄在炕上偷看，羞怒交集。师父二次来搜时面向里床躺好，一动不敢动。与杨过在炕上并卧整夜心中思潮起伏——说他是傻蛋却聪明无比，说他聪明又疯疯癫癫。又怕他伸手来抱，过了良久他却没半点动静，反而微觉失望。闻到他身上浓重男子气息竟颠倒难以自已。天亮醒转想起整晚同睡满脸通红，低唤'傻蛋，傻蛋'话中大是温柔缠绵。"
      }
    },
    "李莫愁": {
      "人物经历": {
        "第9回-03-客店扮道士避李莫愁": "追至客店听得掌柜称呼自己\"老人家\"，拂尘挥出立毙其人于地。派洪凌波上屋顶把守自己逐一搜查房间。见申志凡姬清虚房中三个道士面目与前相同不再细看。青衫客偷走花驴被诱出追击，夺回花驴后二次搜查客店仍未发现陆无双。在镇上搜遍各处吵得家家鸡犬不宁。"
      }
    },
    "洪凌波": {
      "人物经历": {
        "第9回-03-客店扮道士避李莫愁": "随师父李莫愁追至客店，上屋顶把守住防止陆无双逃走。青衫客偷驴时大叫'师父有人偷驴子'通知师父。后随师父在镇中各处搜索未果。"
      }
    },
