210332.content:
{
  "事件地点": "大宋/绝情谷/大石屋",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 11,
    "日": 23,
    "时": 17
  },
  "事件结束时间": {
    "年": 1244,
    "月": 11,
    "日": 24,
    "时": 6
  },
  "事件引子": "六人将小舟抬过九块大石屏风后继续深入溪涧——两边山峰壁立抬头望天只余一线，山青水碧景色极尽清幽但四下里寂无声息隐隐透着凶险。六人方才一番齐心合力自然而然的亲密了几分。",
  "后续事件": {
    "事件名": "第17回-01-绝情谷清晨杨过品情花遇公孙绿萼",
    "描述": "六人在石屋中用罢素饭各自安睡。杨过见这谷中一切不近人情直比寺庙还更严谨无聊——他住惯古墓对惯冷若冰霜的小龙女丝毫不以为意。众人卧听马光佐如雷鼾声一夜无话。"
  },
  "事件详情": "六人弃舟登陆沿着小径向深谷中行去。山径只有一条越行越高也越是崎岖，天色渐黑仍不见绿衫人影踪。正感焦躁忽见远处火光，发足向前奔去——到了山峰顶上一处平旷之地，只见一个极大的火堆熊熊而燃，火堆之后有座石屋。尼摩星大声叫门——石屋门缓缓打开出来三男一女正是日间擒走周伯通的绿衫人。四人躬身行礼自称贵客远来未克相迎。法王与众人走进石屋——屋内空荡荡地除几张桌椅之外一无陈设。尹克西笑吟吟将五人身份一一介绍了，绿衫人说此处荒僻得紧从无外人到访。尹克西问起周伯通——第一个绿衫人恨恨不已讲述老顽童闯谷大闹：踢翻丹炉——那丹炉正烧到紧急的当口被他一脚踢翻要再采全药材不知要到何年何月；折断一株四百多年的灵芝——那少女说她爹爹原定在新婚之日和继母分服却被毁了；撕毁三本道书冲进书房抢书便撕说'这些骗小孩子的玩意有什么大不了'；放火烧剑房——踏进室门大发脾气说兵刃太多东挂西摆险些刺伤了他。四人合力拦他不住，追出谷去以渔网将他擒回交由谷主发落。四个绿衫人入厨端饭——四大盆菜青的是青菜白的是豆腐黄的是豆芽黑的是冬菰竟没有一样荤腥。谷中摒绝荤腥连酒也不许用——说是数百年来的祖训。六人默默吃罢，绿衫人退出不再进来。当晚六人在石屋草席上安睡——杨过住惯古墓对惯冷若冰霜的小龙女丝毫不以为意。尼摩星气愤愤说'老顽童拆屋放火大大好的'马光佐登时大声喝彩。法王说要见机行事尹克西叮嘱大家小心在意。一夜中只有马光佐鼾声如雷。",
  "事件概要": "杨过等人循迹入绝情谷，这座封闭奇谷自此成为后续风波的中心。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第16回-13-六人追踪入绝情谷": "与法王等六人弃舟登陆沿山径向深谷行去。在峰顶石屋中见到四名绿衫人——听他们讲述周伯通大闹山谷：踢翻丹炉、折断四百多年灵芝、撕毁三本道书、放火烧剑房。杨过笑说'他还怪你不理他说你的不对是不是'——对老顽童脾性了然于胸。向绿衫人说'不知谷主如何处置但盼别伤他性命才好'——虽起过除周伯通之念但此刻真心关切他的安危。与众人同吃素饭——见这谷中一切不近人情但他在古墓中对惯冷若冰霜的小龙女丝毫不以为意。睡草席上听马光佐鼾声如雷"
      }
    },
    "金轮法王": {
      "人物经历": {
        "第16回-13-六人追踪入绝情谷": "与五人弃舟登陆沿山径至峰顶石屋会晤四名绿衫人。听他们讲述周伯通大闹山谷之事——微微一笑说'这老顽童性子希奇古怪武功可着实了得原是不易拦他得住'。对绿衫人的神秘来历暗自警惕——身为六人之首决策见机行事。吃素饭时对谷中规矩颇为不适但仍保持从容高僧姿态"
      }
    },
    "潇湘子": {
      "人物经历": {
        "第16回-13-六人追踪入绝情谷": "与众人一同弃舟登陆至峰顶石屋。见四名绿衫人神情拘谨言语无味——整日板着脸不露笑容觉得十分不近人情。吃素饭时闷声不语——素来孤僻倒也毫不在意"
      }
    },
    "尼摩星": {
      "人物经历": {
        "第16回-13-六人追踪入绝情谷": "大声叫门'喂喂有客人来的你们快出来的'。在石屋中听绿衫人讲述周伯通大闹山谷之事——气愤愤说'老顽童拆屋放火大大好的'表示赞同老顽童的胡闹之举。吃素饭时满心不愿——问法王'明儿咱们给他客气客气呢还是打他个落花什么水的'——对谷中不近人情的古怪规矩极是不满"
      }
    },
    "馬光佐": {
      "人物经历": {
        "第16回-13-六人追踪入绝情谷": "听到绿衫人请吃饭立时大叫'妙极妙极'容光焕发。哪知四大盆菜全是素：青菜豆腐豆芽冬菰连油星也不见半点——不禁大失所望。举碗喝了两口发现是清水而非酒——大嚷起来'主人家忒煞小气连酒也没一口'。嚷着要乘夜归去——'没酒没肉这不是存心折磨人么这日子我是半天也不能过的'。被潇湘子板脸一喝才不敢再作声。当夜睡得不稳但鼾声如雷——有时梦中大叫'来来干杯这块牛肉好大'"
      }
    },
    "尹克西": {
      "人物经历": {
        "第16回-13-六人追踪入绝情谷": "最擅言词——笑吟吟将五人身份一一介绍了。与绿衫人对答时说自己'名叫尹克西是个波斯胡人我的本事除了吃饭就是识得些珠玉宝物'——圆滑世故藏拙不露。问绿衫人擒周伯通之事——听罢心中暗暗纳罕：这些人武功路数古怪来历神秘自己在中原多年却也从未听闻。劝马光佐留下见谷主明日再定行止"
      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/绝情谷/大石屋",
      "状态": "身处绝情谷（与金轮法王等六人追踪绿衫人进入绝情谷。在石屋中与四名绿衫男女会谈——听他们控诉周伯通大闹山谷毁丹炉折灵芝撕道书烧剑房。吃素饭睡草席——此谷一切不近人情但杨过住惯古墓对惯冷若冰霜的小龙女反而丝毫不以为意。心中挂念周伯通安危）",
      "关系网": {
        "马光佐": "损友/35（见马光佐因无肉无酒吵嚷不休——取笑他'你明日不小心给他们抓住了关一辈子整日价喂你清水白饭青菜豆腐只怕连你肚里的蛔虫也要气死了'。马光佐连说'好兄弟我听我听'）"
      }
    },
    "金轮法王": {
      "人物经历": {
        "第16回-13-六人追踪入绝情谷听绿衫人诉周伯通大闹山谷": "与五人弃舟登陆沿山径至峰顶石屋会晤四名绿衫人。听他们讲述周伯通大闹山谷——微微一笑说'这老顽童性子希奇古怪武功可着实了得原是不易拦他得住'。对绿衫人的神秘来历暗自警惕——身为六人之首决策见机行事。谷中规矩古怪一切十分不近人情——心中更加戒备。尹克西低声叮嘱小心在意时法王亦深以为然"
      }
    },
    "潇湘子": {
      "所在位置": "大宋/绝情谷/大石屋"
    },
