      "人物经历": {
        "第33回-03-郭襄听神雕侠审丁大全连称有趣": "听宋五讲述神雕侠乔装县官夜审丁大全的事迹，噗哧一笑连说'有趣有趣'。对神雕侠的机智与侠义越发钦佩，与姊姊斗嘴后拔下金钗请众人喝酒吃肉，央求宋五继续讲神雕侠的故事。天真潇洒引得众人暗中相助。"
      }
    },
    "郭芙": {
      "人物经历": {
        "第33回-03-郭芙阻郭襄请客与妹斗嘴斗武": "见郭襄拔金钗请众人喝酒心中不悦，与妹妹斗嘴起来。说到'你小时候给坏人掳了去我才不着急要找你回来'惹得郭襄心软求饶。姊妹俩以巧妙的小擒拿手法拆解七八招——郭襄要呵姊姊腋底，郭芙运肘压制——姿势好看之极。屋角有人低喝'好俊功夫'，两人方才住手。郭破虏提醒爹爹叫不可随便显露功夫。"
      }
    },
    "郭破虏": {
      "人物经历": {
        "第33回-03-郭破虏劝姊勿露功夫": "见两位姊姊当众以小擒拿手法拆解，出声提醒'爹爹叫咱们不要随便显露功夫'。被郭襄笑称'小老头儿少年老成'。"
      }
    }
  },
