  },
  "事件引子": "你听说活死人墓中断龙石轰然落下，自此古墓内外隔绝……",
  "后续事件": {
    "事件名": "第7回-02-李莫愁见石棺知断龙石惊怒下杀手",
    "描述": "断龙石已下无路可出，小龙女带师姊李莫愁前往师父灵柩所在的石棺灵室。"
  },
  "事件详情": "杨过随小龙女穿越甬道奔出古墓，在星光下呼吸自由空气大喜不已，便要去找寻机关放断龙石将李莫愁师徒闷死墓中。小龙女却摇头阻止，道师父嘱咐她好好看守此墓决不能让旁人占了去，自己要回进墓中。杨过心头热血上涌，伸手挽住她手臂说听她的话就是。小龙女克制心神生怕激动，摔脱他手走进墓门背脊向外不再回望。杨过心意已决，抬头上望满天繁星，心道这是最后一次瞧见天星了。他奔到墓碑左侧依小龙女先前指点运劲搬开巨石，抓住下面圆石用力一拉，细沙从孔中急速流出，两块重逾万斤的断龙石缓缓落下。小龙女听到巨石下落之声忍不住泪流满面回过头来。杨过待巨石离地约二尺时，突然使出玉女投梭身如箭般从空隙中窜入墓中。腾腾两声猛响两块巨石着地，墓门从此封死。小龙女惊喜交集激动过度险些晕去，倚靠石壁喘气良久，终于牵着杨过的手走向内室，二人决意同生共死。",
  "事件概要": "杨过为陪小龙女折返墓中，断龙石一落，二人自此与外界隔绝，只能共困古墓。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第7回-01-放下断龙石杨过窜回墓中": "随小龙女出墓后本欲放下断龙石闷死李莫愁师徒，见小龙女坚持遵守师父遗命回进墓中，心头热血上涌毅然跟随。放下重逾万斤的断龙石后，趁巨石离地约二尺使出玉女投梭身如箭般窜入墓中。小龙女惊喜交集二人决意同生共死。"
      }
    },
    "小龙女": {
      "人物经历": {
        "第7回-01-放下断龙石杨过窜回墓中": "虽出墓却因师父遗命须看守古墓，坚持回进墓中令杨过放下断龙石。听到巨石下落之声忍不住泪流满面。不料杨过趁断龙石未完全落地之际从二尺空隙中窜回，惊喜交集激动过度险些晕去，终于牵着杨过的手决意共死。"
      }
    }
  },
  "参与人物": [
    "杨过",
    "小龙女",
    "李莫愁"
  ]
}

