{
  "事件地点": "大宋/大胜关/大镇酒楼",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 10,
    "日": 30,
    "时": 14
  },
  "事件结束时间": {
    "年": 1244,
    "月": 10,
    "日": 30,
    "时": 15
  },
  "事件引子": "杨过已走下楼梯数级，猛见争端骤起黄蓉眼下就要受辱，不由得激动了侠义心肠——还顾得什么生死安危，飞身过去拾起武敦儒掉下的长剑向金轮法王后心刺去...",
  "后续事件": {
    "事件名": "第14回-07-双剑合璧大败金轮法王临别赠药",
    "描述": "杨过与小龙女双剑合璧越使越得心应手，金轮法王节节败退"
  },
  "事件详情": "黄蓉隔袖摔飞蒙古武士后，金轮法王大踏步上前要亲自出手擒拿。杨过已走下楼梯几级，眼见黄蓉将要受辱，侠义心肠激动之下不顾生死安危——飞身拾剑以'青龙出海'急刺法王后心。法王翻指一弹震得他右臂发麻剑尖垂落。法王以软硬兼施之言劝杨过快走，赞他年纪轻轻将来成就远胜于己。杨过笑道此位黄帮主自幼养他长大求法王别难为她。金轮法王闻言细看黄蓉果见容色憔悴病势不轻——心想这两个少年男女何惧，当即冷笑抢到梯口说'那你也留下罢'。小龙女被隔开心中不乐从法王身畔掠过与杨过并肩。两人使玉女心经功夫挺剑向法王刺去。杨过不以力斗而以纠缠游斗——踢推桌椅阻挡法王、投掷酒壶翻泼菜盘，楼面酒菜淋漓。黄蓉乘机拉过郭芙，但见二人出尽全力仍难招架，不肯舍之而去站在楼头观战。金轮法王使出千斤坠踏碎桌椅后攻势大猛——杨龙失了阻隔只得以真功夫抵挡。危急中二人同时遇险——杨过身子贴地斜飞使全真派'雁行斜击'刺向法王后心，竟收到奇效。跟着又是一招全真派'白虹经天'平剑拍打飞轮——无意中用上九阴真经的功夫以四两拨千斤将铁轮打飞向法王头上飞去。法王盛怒下重手飞轮，杨过劲力用得不正长剑被震脱手。小龙女急刺相救，这一招用的是玉女心经最后一章的武功飘逸无比。杨过脱口大叫'姑姑浪迹天涯'——小龙女应声使同招，虽名称相同但全真与玉女两招大异。双剑合璧威力立时大得惊人——法王无法齐挡身上两处衣服被划破吓出一身冷汗。杨过又叫'花前月下'、'清饮小酌'——两人剑招越来越怪却相互配合呼应天衣无缝，所有破绽全由另一人补去。杨龙修习此剑法数度无功，此刻身遭奇险相互情切关心——都不顾自身安危先救情侣，正合上了剑法的主旨。二人越使越是得心应手，灵犀暗通威力倍增。",
  "事件概要": "杨过冒死救黄蓉并与小龙女初成双剑合璧，二人联手之威第一次真正成形。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第14回-06-杨过舍身救黄蓉初使双剑合璧": "本已走下楼梯要去找郭靖报信——但见黄蓉就要受辱激动侠义心肠不顾生死飞身拾剑刺向金轮法王后心。被法王劝退时以嬉笑相激——'黄帮主自小养我大的你还是别难为她罢'。与小龙女以游斗纠缠——踢推桌椅、投掷酒壶、翻泼菜盘。危急中被迫以真功夫相抗——身子贴地斜飞使全真派'雁行斜击'竟收奇效。又无意识以九阴真经功夫使全真剑法'白虹经天'以四两拨千斤打飞铁轮。长剑被震脱手后死里逃生——猛想起'我和姑姑二人同使玉女剑法难以抵挡但若我使全真剑法她使玉女剑法却均化险为夷'。脱口大叫'姑姑浪迹天涯'——小龙女应声出招双剑合璧威力立时大得惊人。接连再呼'花前月下''清饮小酌'——二人剑招相互配合呼应天衣无缝。他和小龙女修习此剑法数度无功——此刻身遭奇险相互情切关心不顾自身安危先救情侣正合上了剑法主旨"
      }
    },
    "小龙女": {
      "人物经历": {
        "第14回-06-小龙女与杨过初使双剑合璧": "被金轮法王隔在梯间心中不乐——从法王身畔掠过与杨过并肩。与杨过以古墓派功夫挺剑刺去。使玉女心经最后一章武功——纤腰微摆长剑急刺风姿绰约飘逸无比。杨过大叫'浪迹天涯'时未及多想依言使出心经所载同名剑招——虽名称相同但全真与玉女两招大异，双剑一合威力立时大得惊人。跟着杨过呼'花前月下'时单剑颤动如鲜花招展风中来回挥削——只晃得法王眼花缭乱。又使'清饮小酌'——剑尖上翻指向自己樱唇宛似举杯自饮。当下与杨过心意相通——二人都不顾自身安危先救对方正合上了祖师婆婆创此剑法的本意"
      }
    },
