  "事件详情": "杨过与陆无双纵马狂奔至黄昏，怕李莫愁追来又催马急驰一阵。天色渐黑时前面传来几声马嘶，见一个村庄外系着百余匹战马——正是日间所见那队蒙古骑兵。杨过让陆无双等着，自己闪身村中一间大屋窗下，见一个蒙古官员背窗而立。待其转身时他轻轻揭窗跃入。那官员倏地转身双手十指似鹰爪猛插过来，使的竟是\"大力鹰爪功\"。杨过闪身避开，几招过后跳高按住他双肩内力直透双臂喝道\"坐下\"，那官员双膝一软坐倒在地胸中郁闷几欲吐血。杨过伸手在他乳下穴道揉了揉，官员胸腹登松站起身来。杨过笑了笑反问身份，官员又怒扑上来却被随手化解。杨过说\"你肩头受了伤别使力才好\"——官员摸双肩果然各有一处隐隐作痛，原来杨过刚才按肩时已暗中刺入两枚玉蜂针。杨过微笑说大暗器无毒小暗器自然有毒，毒气每天延伸一寸六日便毒气攻心。那官员还想拼命又被杨过将两枚玉蜂针插进掌心，两掌麻木之下再不敢倔强。此人乃蒙古大丞相耶律楚材之子耶律晋，现任汴梁经略使南下赴任。杨过将陆无双带来后要耶律晋向她磕头，陆无双反手给了杨过一巴掌——耶律晋不知二人玩闹惯了的，只道陆无双武功比杨过还高。杨过听耶律晋几句上乘马屁一拍大喜，当即用吸铁石吸出玉蜂针敷上解药。说要投靠大人做侍从，耶律晋心喜二人武功高强可以护卫自己。二人换穿蒙古军官服饰——陆无双照镜见自己貂衣锦袍明眸皓齿居然是个美貌少年军官。次晨起程后轿中听到李莫愁鸾铃声从旁掠过，此后两日不再闻铃声。",
  "事件概要": "杨过制住耶律晋后顶替侍从身份，顺势混入耶律家队伍，行路处境顿时安全许多。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第9回-06-智取耶律晋乔装侍从": "黄昏时发现蒙古骑兵营地，闪身潜入大屋。与蒙古官员耶律晋交手——避其大力鹰爪功后跳高按住其双肩运劲喝坐，暗中已刺入两枚玉蜂针。说毒气六日攻心令耶律晋不敢倔强。带陆无双来时要耶律晋向她磕头反被陆无双打了一掌——耶律晋竟以为陆无双武功更高。被耶律晋几句上乘奉承拍得心中大喜，伸手吸出玉蜂针敷了解药。称有极厉害仇家追赶要投靠做侍从躲避。二人换上蒙古军官服饰，杨过扮作侍从模样。次日乘轿起程，听到李莫愁鸾铃声从旁掠过，坐在轿中舒舒服服躲过了连日追捕。此后两日再听不到铃声。"
      },
      "关系网": {
        "耶律晋": "利用/30（以玉蜂针胁迫耶律晋收留二人扮作侍从，被其奉承得心中大悦，又教其武功换取庇护）"
      }
    },
    "陆无双": {
      "人物经历": {
        "第9回-06-智取耶律晋乔装侍从": "随杨过纵马狂奔至黄昏，在村外等待。被杨过带进蒙古官员耶律晋屋中，杨过要耶律晋向她磕头被她反手打杨过一掌——耶律晋看呆了只道她武功比杨过还高。换上蒙古军官服饰后照镜见自己貂衣锦袍明眸皓齿居然是个美貌少年军官，自感甚是有趣。次晨乘轿赶路，听到师父鸾铃声从旁掠过大喜——心道在轿中舒舒服服养伤当真再好不过，就这么让他们抬到江南。此后两日再听不到师父鸾铃声——想是李莫愁一直向北追去不再回头，全真教和丐帮也没发现她的踪迹。"
      }
    },
    "耶律晋": {
      "人物经历": {
        "第9回-06-智取耶律晋乔装侍从": "南下汴梁赴任途中在村庄驻扎，忽有少年轻轻揭窗跃入。施展'大力鹰爪功'却被对方轻描淡写避开——被杨过按住双肩运劲喝坐，又不知何时被刺入玉蜂针。想拼命时掌心又被刺入两针麻木难当，只得认输。自报身份是耶律楚材之子、汴梁经略使。见杨过带来陆无双又被杨过要求磕头正不知所措，陆无双打杨过一掌让他更搞不清状况。以上乘奉承话哄得杨过大喜，杨过替他吸针敷药后说要投靠做大人的侍从——实为躲避仇家。求之不得，立即吩咐侍从取衣。次晨起程后两日间再听不到追兵铃声。"
      }
    }
  },
  "update": {
    "杨过": {
      "状态": "潜伏中（以玉蜂针制住耶律晋后与其达成交易，扮作蒙古侍从乘轿赶路。两日来李莫愁鸾铃声不再可闻，暂时安全）"
    },
    "陆无双": {
      "状态": "潜伏中（换上蒙古军官服饰扮作少年军官乘轿赶路，两日未闻师父鸾铃声——暂时摆脱追捕，断骨逐渐愈合）"
    },
    "耶律晋": {
      "状态": "赴任途中（被杨过以玉蜂针胁迫收留二人为侍从，每日向杨过请教武学奉承讨好，一行人往汴梁方向前进）",
      "关系网": {
        "杨过": "敬畏/60（虽被胁迫但见识其神功后心生仰慕，每日高帽一顶顶送来请教武学）"
      }
    }
  },
  "参与人物": [
    "杨过",
    "陆无双",
    "李莫愁",
    "耶律楚材",
    "耶律晋"
  ]
}

