  "事件引子": "你听说古墓石棺中，小龙女发现了王重阳留下的十六字遗言……",
  "后续事件": {
    "事件名": "第7回-06-李莫愁偷袭点穴九阴解穴法脱困",
    "描述": "二人发现九阴真经和出墓秘道后疲倦睡去，却被李莫愁师徒发现地下石室偷袭得手。"
  },
  "事件详情": "杨过正高兴间忽见小龙女颤抖不止难以自制，她颤声道好冷。适才击出两掌虽然劲力极轻使的却是内家真力，重伤后元功未复牵动之下受损不小。她一生在寒玉床上练功原是至寒底子，此时制力一去如堕万仞玄冰之中奇冷彻骨。杨过情急之下将她紧紧搂在怀中欲以自身热气助她抗寒，却觉她身子越来越冷渐渐自己也抵挡不住。小龙女自觉内力不断消失叫杨过抱她去放石棺的地方。杨过将她放在石棺盖上点燃蜡烛，小龙女请他把自己放入棺中。杨过推开棺盖抱她轻轻放入，随即也跃进棺中和她并头卧倒挤在一处。小龙女又是欢喜又是奇怪，问他做什么，杨过说自然跟她在一起让那两个坏女人睡那口石棺。小龙女心中十分平安寒意便已不如先前厉害。她微感害羞转过脸去，忽然见到棺盖内侧似有字，凝目瞧去果见十六个大字：'玉女心经，技压全真。重阳一生，不弱于人。'这十六字以浓墨所书笔力苍劲。小龙女认出是王重阳所写。杨过爬出石棺后小龙女翻身到彼端观看小字，连读两遍忽感手上无力烛台跌落。她脸色异样，定神片刻后说出王重阳在棺盖上留言：祖师婆婆死后王重阳来吊祭，见到石室顶上的玉女心经竟将全真武功尽数破去，他便在此留字说玉女心经所破不过是全真派粗浅武功，较之最上乘全真功夫何足道哉。并说在另一石室中留下破解玉女心经之法。杨过好奇心起，小龙女在室中巡视发现石棺棺底可以掀开。杨过跃入棺中依小龙女指点先左转再上提，棺底石板应手而起。待秽气出尽后二人从石棺底进入地下石室。抬头仰望室顶密密麻麻写满字迹符号，最右处写着四字：'九阴真经'。但二人不知此乃武学最高境界，正觉奥妙难解之际，小龙女顺杨过手指看到室顶西南角绘着一幅地图，只看片刻全身僵住。良久之后她伏在杨过胸口哭了出来，说那幅图画是出墓的秘道——她熟知墓中地形因此一见便知。杨过欢喜无已，小龙女含着眼泪说自己以前从来不怕死，可这几天老是想到要到外面去瞧瞧，又是害怕又是欢喜。二人喜悦之余倦困暗生竟沉沉睡去。",
  "事件概要": "小龙女寒毒发作时与杨过发现重阳遗刻，古墓绝境中意外得到九阴相关武学线索。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第7回-05-小龙女寒毒发作石棺发现重阳遗刻": "小龙女寒毒发作全身冰冷颤抖，杨过紧搂在怀以热气助她抗寒无果。抱她到石棺室将她放入石棺后自己也跃进棺中并头卧倒。发现王重阳棺盖内侧所留十六字遗言。依小龙女指点打开棺底石板进入地下石室，发现九阴真经和出墓秘道地图。见小龙女伏在自己胸口哭诉可以出去了，欢喜无已。"
      }
    },
    "小龙女": {
      "人物经历": {
        "第7回-05-小龙女寒毒发作石棺发现重阳遗刻": "打李莫愁耳光牵动内伤致寒毒发作全身冰冷颤抖内力不断消失，被杨过抱入石棺。在棺中偎依杨过心头温暖寒意大减。发现王重阳留下的十六字遗言和破解玉女心经的留言。发现地下石室中九阴真经和出墓秘道地图后，伏在杨过胸口哭泣——以前从不怕死如今却要出去瞧瞧，又是害怕又是欢喜。"
      }
    }
  },
  "update": {
    "杨过": {
      "关系网": {
        "小龙女": "师父且爱慕/99"
      }
    },
    "小龙女": {
      "关系网": {
        "杨过": "师父/98"
      }
    }
  },
  "参与人物": [
    "杨过",
    "小龙女"
  ]
}

