  "事件引子": "你听说小龙女带着杨过回到活死人墓，准备安葬孙婆婆……",
  "后续事件": {
    "事件名": "第5回-08-杨过初睡寒玉床练内功",
    "描述": "安葬孙婆婆后小龙女带杨过到自己房中，命他睡在寒玉床上"
  },
  "事件详情": "小龙女出重阳宫后放下杨过抱了孙婆婆的尸身，带同杨过回到活死人墓中。她将孙婆婆尸身放在其平时所睡的榻上，坐在榻前椅上支颐于几呆呆不语。杨过伏在孙婆婆身上抽抽噎噎哭个不停。过了良久小龙女冷冷说人都死了还哭什么你这般哭她她也不会知道了。杨过一怔觉得这话虽是辛辣无情但仔细想来却也当真如此，伤心益甚不禁又放声大哭。小龙女冷冷望着他脸上丝毫不动声色，又过良久才说咱们去葬了她。杨过伸袖抹了眼泪跟她走。墓道中没有半点光亮，杨过尽力睁大眼睛也看不见小龙女的白衣背影只得紧紧跟随。弯弯曲曲东绕西回走了半晌推开一道沉重石门——空空旷旷的大厅上并列放着五具石棺。小龙女指着第一具说是祖师婆婆、第二具是师父、第三具空棺是孙婆婆。杨过问那两口棺材是何人的，小龙女说我师姊李莫愁睡一口我睡一口，这里还少一口石棺因为我师父料不到你会来。杨过吓了一跳连说不。小龙女说答允孙婆婆要照料他一生一世自己不离开这儿杨过自然也在这儿。她走到第三具石棺前推开棺盖，杨过心中不舍求再瞧婆婆一眼。小龙女皱了皱眉头抱孙婆婆尸身不动。杨过在暗淡灯光下见孙婆婆面目如生又想哭泣。小龙女横了他一眼将尸身放入石棺伸手抓住棺盖一拉——喀隆一声盖得严丝合缝，怕杨过再哭对他一眼也不再瞧说走罢，左袖挥处两盏油灯齐灭登时黑成一团。",
  "事件概要": "孙婆婆安葬后，杨过彻底留在古墓与小龙女相依为命，生死观也开始受她影响。",
  "insert": {
    "小龙女": {
      "人物经历": {
        "第5回-07-小龙女安葬孙婆婆述生死": "将孙婆婆尸身放在她平时所睡榻上坐于榻前椅上一言不发。过了良久冷冷对杨过说人都死了还哭什么。带杨过弯弯曲曲东绕西回走到停放五具石棺的大厅——分别指明祖师婆婆、师父、孙婆婆、李莫愁和自己各一口石棺，又说少一口是因师父料不到杨过会来。告诉杨过自己答允孙婆婆照料他一生一世就不会先他而死——若死必先杀杨过。将孙婆婆尸身放入石棺盖严后灭灯带杨过出墓室"
      }
    },
    "杨过": {
      "人物经历": {
        "第5回-07-小龙女安葬孙婆婆述生死": "在墓中伏在孙婆婆身上抽抽噎噎哭个不停。听小龙女说人都死了哭什么后一怔觉得虽是辛辣无情却也不假伤心益甚。跟随小龙女在黑暗墓道中弯弯曲曲东绕西回走到石棺室吓得打个寒噤。听小龙女说那口空棺是因师父料不到自己会来时吓了一跳急说不。小龙女说要杀他时心想脚生在自己身上不会逃走么。不舍孙婆婆求再瞧一眼，在暗淡灯光下见孙婆婆面目如生又想哭泣，小龙女横他一眼后将棺盖盖严。黑成一团中怕被关在墓室急忙跟出"
      }
    }
  },
  "参与人物": [
    "小龙女",
    "杨过",
    "孙婆婆"
  ]
}

