  "事件引子": "重阳宫中一片喧闹——大殿上钟鼓再次齐鸣，召集全宫道众。道士们神色紧张，有的道袍下暗藏兵刃。殿上只听赵志敬抢先说道：'蒙古大汗既有这等美意自当领旨。可见本教日益兴旺连蒙古大汗也不敢小视咱们。'话音刚落，便有数名道人厉声反驳。",
  "后续事件": {
    "事件名": "第25回-08-蒙古高手围攻重阳宫全真教大败",
    "描述": "赵志敬接任掌教后立即迎入蒙古贵官接受敕封。李志常王志坦等拔剑反抗，潇湘子出手镇住众人。蒙古高手尹克西尼摩星马光佐率武士攻入重阳宫，全真教弟子赤手空拳惨遭大败。"
  },
  "事件详情": "别院中十六名大弟子就蒙古敕封一事展开了激烈争论。赵志敬抢先说自当领旨可显本教日益兴旺，李志常坚决反对——蒙古侵我国土残害百姓怎能受他敕封。赵志敬以丘处机当年领受成吉思汗诏书西行为先例辩解，王志坦厉声道：'蒙古军大举南下急攻襄阳大宋江山危在旦夕，你我都是大宋之民岂能受敌国敕封？'转头对尹志平说若受了敕封便是大大的汉奸本教的千古罪人，'我王志坦纵然颈血溅于地下也不能与你干休。'赵志敬拍桌怒喝对掌教真人竟敢无礼，双方势将拔剑相斗。尹志平双掌一拍说道：'请问诸位师兄，若是王马刘丘四位前辈掌教在此他们是受这敕封呢还是不受？'群道一听不约而同念及丘处机性如烈火忠义过人，齐声叫道：'丘掌教是定然不受！'尹志平缓缓道：'小弟才识庸下不敢违背师训。又何况我罪孽深重死有余辜。方今豪杰之士正结义以抗外侮，全真派号称武学正宗若是降了蒙古有何面目再见天下英雄？'群道轰然喝彩。赵志敬拂袖怒冲冲走出，回头冷笑道：'此事后果如何你也料想得到。'尹志平回到丹房闩上房门，想到数月来担惊受怕受尽折磨，死后一了百了心中反而坦然，抽出长剑便往颈上刎去。赵志敬突然从书架后转出夺下长剑——以小龙女之事要挟尹志平传位。半个时辰后大殿上钟鼓齐鸣召集全宫道众，尹志平脸色惨白当众宣布自己突患急病无法可治，命赵志敬接任掌教。群道大乱纷纷反对，但尹志平依教规强命众人不得争论，赵志敬得意洋洋跨步上前接任。",
  "事件概要": "尹志平率众拒绝蒙古敕封，却被赵志敬以旧事要挟，被迫辞去掌教之位；赵志敬由此接掌全真教并准备领旨。",
  "insert": {
    "赵志敬": {
      "身份": {
        "全真教掌教": "尹志平当众宣布因突患急病将掌教之位传让——在重阳宫三清殿接任全真教掌教。实际是挟持尹志平把柄强迫让位篡夺而来"
      },
      "人物经历": {
        "第25回-07-赵志敬力主领封逼迫尹志平让位": "在别院抢先力主领受蒙古敕封——'可见本教日益兴旺连蒙古大汗也不敢小视咱们'。以丘处机当年西行领诏为先例巧言辩解——被李志常王志坦严词驳斥。为全真教存续与众人激烈争辩——'祖师爷创业艰难本教能有今日的规模祖师爷和七位师长花了多少心血'。被尹志平以四位前辈掌教忠义精神否决后拂袖而去——冷笑以此事后果相胁。躲在尹志平丹房书架后见其拔剑自刎——伸手夺剑以小龙女之事要挟'你只须依我一件事龙姑娘之事我就全力跟你弥缝'。要求尹志平传位——半个时辰后如愿以偿在全宫道众前接任掌教。得意洋洋跨步上前听训——李志常等心有不平但碍于教规不得反抗"
      }
    },
    "尹志平": {
      "人物经历": {
        "第25回-07-尹志平拒受敕封被逼让位赵志敬": "邀十六名大弟子到别院商议蒙古敕封——听众人争论不休双掌一拍请各人安坐听自己裁决。缓缓问出若四位前辈掌教在世会如何抉择——群道不约而同想到丘处机定然不受。慷慨激昂宣告拒受敕封——'方今豪杰之士正结义以抗外侮。全真派号称武学正宗若是降了蒙古咱们有何面目再见天下英雄'。群道轰然喝彩赵志敬拂袖而去。回到丹房闩上房门抽出长剑往颈上刎去——想到死后一了百了心中反而坦然。被赵志敬从书架后转出夺剑——'你败坏我教名誉便想一死了事？龙姑娘守在宫门之外待会她进来理论教咱们如何对答'。被赵志敬以小龙女之事要挟——精神崩溃坐倒在地抱着脑袋喃喃道'你叫我怎么办怎么办'。被迫答应传位——半个时辰后在大殿上脸色惨白当众宣布突患急病不克负荷命赵志敬接任掌教。群道大哗但依教规不得争议——内心极度痛苦却无法挣脱赵志敬的挟制"
      }
    },
    "李志常": {
      "人物经历": {
        "第25回-07-李志常力主拒封": "在别院商议时摇头反对领受敕封——'蒙古侵我国土残害百姓咱们怎能受他敕封'。反驳赵志敬以丘处机西行为先例——'那时蒙古和大金为敌既未侵我国土且与大宋结盟此一时彼一时如何能相提并论'。慷慨陈词全真教上代真人个个不畏强御立志救民水火——'头可断志不可辱'。见尹志平传位赵志敬满腹疑团——瞧尹志平神色确有极重大难言之隐"
      }
    },
    "王志坦": {
      "人物经历": {
        "第25回-07-王志坦慷慨驳斥死谏拒封": "在别院挺身厉声斥责领受敕封便是汉奸——'蒙古军大举南下急攻襄阳大宋江山危在旦夕，你我都是大宋之民岂能受敌国的敕封'。转头向尹志平道：'掌教师兄你若受了敕封便是大大的汉奸便是本教的千古罪人。我王志坦纵然颈血溅于地下也不能与你干休'——声色俱厉"
      }
    },
    "宋德方": {
      "人物经历": {
        "第25回-07-宋德方陈述西征见闻反对敕封": "在别院摇头道今日情势非昔可比——'小弟随师父西游亲眼见到蒙古兵将屠城掠地的惨酷。咱们若受敕封降了蒙古那便是助纣为虐，纵然救得十条八条性命但蒙古势力一大不知将有几千几万百姓因此而死'"
      }
