316859.content:
{
  "事件地点": "大宋/华山/绝顶",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 9,
    "日": 18,
    "时": 8
  },
  "事件结束时间": {
    "年": 1244,
    "月": 9,
    "日": 18,
    "时": 9
  },
  "事件引子": "你听说杨过在武关不别而行走后，只身一人往西北荒野乱闯，不到一月便形容枯槁来到华山绝顶——不料竟在那里遇上了当世五绝之一的九指神丐洪七公，二人在冰天雪地中煮食大蜈蚣……",
  "后续事件": {
    "事件名": "第10回-08-洪七公大睡杨过独守三日",
    "描述": "洪七公吃罢蜈蚣心满意足，倒在雪地中大睡——吩咐杨过守他三日，便是天塌下来也别吵醒"
  },
  "事件详情": "杨过见郭芙与武氏兄弟合攻李莫愁时神情亲密剑法精妙，勾起幼时被殴打郭芙在旁叫好的旧恨——更想起郭靖不肯传自己武功送全真教受群道折磨。满腔怨愤不能自已，突然发足狂奔不循道路只在荒野中乱走。他心中异常只道普天下人都要与自己为难，越行越远不到一月已是形容枯槁衣衫破烂——来到华山。但见山势险峻便发狠往绝顶上爬去。爬到半山天候骤寒铅云低压北风渐紧，天空飘下片片雪花。他心中烦恼尽力折磨自己并不避雪，风雪越大越是在巉崖峨壁处行走。行到天色向晚忽然身后发出极轻的嗤嗤声，转身只见一人伸出三根手指钩在石上身子凌空——凭临万仞深谷武功高到不可思议。杨过恭恭敬敬请老前辈上来。那人哈哈大笑震得山谷鸣响手指一捺跃上崖来——正是九指神丐洪七公。他因藏边五丑在广东滥杀无辜一路跟踪上华山欲等五丑聚会一举屠绝。洪七公见杨过腹中饥饿便扒雪生火煮食蜈蚣——华山之阴是天下极阴寒之处所产蜈蚣最为肥嫩。他用死公鸡诱来百余条红黑相间的大蜈蚣，斩头去尾轻轻一捏壳落肉出雪白透明。起油锅一炸立时香气扑鼻。杨过初时不敢吃被洪七公一激——'天下大言不惭自称英雄好汉之人甚多，敢吃蜈蚣的却找不出几个'——心想除死无大事放入口中一嚼，但觉满嘴鲜美又脆又香清甜甘浓，一生从未尝过如此异味。二人大快朵颐把百余条蜈蚣吃得干干净净。",
  "事件概要": "杨过离群独上华山，并因洪七公指点食蜈蚣疗寒，身心都被逼入新的转折点。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第10回-07-杨过登华山遇洪七公啖蜈蚣": "在武关不别而行走后发足狂奔不循道路只在荒野中乱走。他心神异常自伤身世只道普天下人都要与自己为难——想起郭靖不肯传功、全真教受辱、小龙女离去，越走越远不到一月已是形容枯槁衣衫破烂。来到华山绝顶在风雪中苦行折磨自己——将性命瞧得极是轻贱。忽见身后有人以三指钩石悬空虚临深谷——武功之高不可思议，恭恭敬敬行礼呼叫老前辈。洪七公上崖后没来由厉声喝问他是藏边五丑同党，杨过被骂触动心事放声大哭——想起一生不幸受人轻贱，毕生怨愤屈辱尽数涌上心来哭到伤心处愁肠千结。从洪七公处得知此人便是九指神丐。随洪七公攀上人迹未到的山峰绝顶——洪七公以死公鸡诱来百余条肥美蜈蚣煮食。初时不敢吃被洪七公以'敢吃蜈蚣的找不出几个'相激——除死无大事放入口中，一嚼之下满嘴鲜美又脆又香清甜甘浓，与洪七公你争我夺将百余条蜈蚣一扫而光。"
      },
      "关系网": {
        "洪七公": "忘年之交/70（初见便对他深不可测的武功肃然起敬。被洪七公骂后触动心事号啕大哭——洪七公被他激起往事也放声大笑，一哭一笑竟成奇缘。共食蜈蚣后已视他为可敬可亲的前辈——洪七公也甚是喜爱这少年的胆气轻功）"
      }
    },
    "洪七公": {
      "人物经历": {
        "第10回-07-杨过登华山遇洪七公啖蜈蚣": "在华山绝顶深夜雪中遇杨过。初以为他是藏边五丑同党厉声喝问，杨过被骂触动心事放声大哭——洪七公起初一怔后来越听越奇，见杨过哭得没完没了突然纵声长笑，一哭一笑在山谷间交互撞击震得积雪大片掉落。出手摔杨过却被他以蛤蟆功一个筋斗稳稳立住——大为意外另眼相看。问杨过身世后骂'没中用的小子'激他提气上攀——见他有胆气轻功甚是喜爱，以他见识之博广竟看不出这少年武功来历。以死公鸡诱蜈蚣烹炸——大吃特吃赞天下至乐无逾于此。杨过不敢吃时出言相激笑他是胆小鬼。二人争抢将百余条蜈蚣吃尽——洪七公伸舌头舔嘴边汁水恨不得再有一百条。吃完仰天倒雪地便说要睡三日。"
      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/华山/绝顶",
      "状态": "华山遇丐（独走荒野跋涉近月来到华山绝顶。风雪中苦行折磨自己——心意消沉只觉活在世上多余。遇洪七公后重获生气与他共食蜈蚣——这少年对世间美食竟也大有品味。洪七公睡去后守在旁边为他放哨）",
      "性格": "聪明机灵，狡猾惫懒，自尊心极强且敏感叛逆。自幼失去父母饱尝人世冷暖。得小龙女真心相待后对她敬爱赤诚却懵懂未解男女之情——溪边因完颜萍眼波蓦然醒悟才真正领会姑姑深情。重情重义守约守信——宁可饿死也要守足洪七公三日之约。与洪七公共食蜈蚣后深感此老可敬可亲，视他为忘年之交。遭遇世人轻贱时常自伤自怜，看似轻佻浮脱实则内心血性男儿——可以命守诺不畏生死。美食当前也敢尝天下至奇之物，大事当头更是豁得出去。",
      "关系网": {
        "郭靖": "郭伯伯/30（想起郭靖不肯传自己武功却送全真教受罪——心中怨愤更深。他对郭靖仍怀幼时敬佩却更怨其不明自己心意）",
        "黄蓉": "世伯母/5（想起黄蓉故意不教武功——当年只教读书不传功夫的恨意重燃心头）"
      }
    },
