  "事件引子": "裘千尺望着兄长背影在屏门外隐没料想此生再无相见之日。她胸口一酸隐隐感到一阵惆怅一阵悔意——但这悔意一瞬即逝随即傲然变色令渔网阵封锁大厅退回内堂。",
  "后续事件": {
    "事件名": "第31回-05-公孙绿萼断肠崖偷听公孙止李莫愁密谋害己",
    "描述": "公孙绿萼万念俱灰走向绝情峰断肠崖——却在山石后听到了父亲公孙止与李莫愁正在密谋一件骇人之事。"
  },
  "事件详情": "裘千尺望着慈恩的背影终于消失在屏门外——料想此生再无相见之日。胸口一酸体味慈恩那句'你叫我回来我却叫你回来呢'似是劝自己悬崖勒马。但这悔意一瞬即逝——她随即傲然变色令众弟子布渔网阵封锁大厅。每处门口涌出四名绿衣弟子高举带刀渔网拦住去路。四名侍女抬起坐椅退入内堂。大厅前后铁门一齐轧轧关上——武氏兄弟双剑挟在门缝中登时折断大门竟是钢铁所铸。黄蓉说须想出破渔网盗药之法。公孙绿萼随母亲进了内堂问怎么办——裘千尺命她去瞧瞧杨过在干什么。绿萼正合心意而行至半路——天已全黑听到杨过声音便往道旁柳树丛中一闪。只听杨过小龙女并肩站立说话——杨过道说此事全仗公孙姑娘从中周旋。突然杨过一声啊哟摔倒在地——情花之毒发作痛得牙关难开。小龙女低声说我倒有个法子——劝杨过娶了公孙姑娘以便求药活命。杨过朗声笑道公孙姑娘自然是好——但你我既然两心如一怎容另有他念。又道若有一个男人能解你体内剧毒却要你委身以事你肯不肯啊。小龙女说我是女子自作别论——杨过笑道旁人重男轻女我杨过却是重女轻男。绿萼听到此处心中大震——原来小龙女在劝杨过娶了自己以求药活命。接着陆无双和程英从树丛后小路上转出——绿萼乘机悄悄退开。她自见杨过便不由自主对他一往情深——此刻听了这番话更知相思成空已成定局。自幼便郁郁寡欢今日万念俱灰——心中一个声音只是说我不想活了我不想活了——漫步向西走去。",
  "事件概要": "裘千尺以铁门与渔网阵封死大厅，公孙绿萼也彻知杨过小龙女情深不改，自此万念俱灰再无自处之地。",
  "insert": {
    "裘千尺": {
      "人物经历": {
        "第31回-04-裘千尺渔网阵封锁大厅退回内堂": "见慈恩离去料想此生再无相见之日——胸口一酸隐隐感到惆怅悔意但一瞬即逝。傲然变色令众绿衣弟子高举带刀渔网封锁大厅——前后铁门轧轧关上钢铁所铸将众人困住。四名侍女抬起坐椅退入内堂。黄蓉叫且慢时——向随侍众人一点头众弟子齐声唿哨布下渔网阵——退入内堂不再理睬"
      }
    },
    "公孙绿萼": {
      "人物经历": {
        "第31回-04-公孙绿萼偷听杨龙对话万念俱灰": "随母进内堂后奉母命去找杨过。行至半路天已全黑——听到杨过小龙女说话便往柳树丛中一闪偷听。见杨过情花毒发作倒地痛楚难当——小龙女劝杨过娶自己以求药活命。杨过断然拒绝——'你我既然两心如一怎容另有他念'。绿萼心中大震——原来小龙女在劝杨过娶自己。听了这番话更知相思成空已成定局——想起别说和龙姑娘相比便是程英陆无双的品貌武功自己也是远远不及。自幼便郁郁寡欢今日万念俱灰决意不想活了——乘陆无双程英来时悄悄退开心中一个声音只是说我不想活了我不想活了——漫步向西走去"
      }
    },
    "杨过": {
      "人物经历": {
        "第31回-04-杨过情花毒发作拒绝绿萼之意": "与小龙女从火浣室返回途中携手缓行正观赏夕阳晚景——不知道大厅中情势紧逼。行至半路情花之毒突然发作摔倒在地——背部抽搐颤动强忍痛楚。片刻后站起身来吁了一口长气。小龙女劝他娶公孙绿萼以换取解药——杨过坚决拒绝。朗声说公孙姑娘自然是好——但你我既然两心如一怎容另有他念。又反问小龙女若有一个男人能解你体内剧毒却要你委身以事你肯不肯啊——表明对爱情的坚贞不渝。听到树丛后声响喝问是谁——陆无双程英转了出来"
      }
    },
    "小龙女": {
      "人物经历": {
        "第31回-04-小龙女劝杨过娶绿萼被拒": "扶起情花毒发作倒地的杨过——低声道是情花之毒发作了吗。说出'我倒有个法子'——劝杨过娶公孙绿萼以换取解药活命。被杨过坚决拒绝后呜咽道那公孙姑娘我瞧她人很好啊你便听了我的话罢。杨过反问若让你委身他人换取解药你肯不肯时——小龙女说我是女子自作别论。最终被杨过的真情打动不再提起此事"
      }
    },
    "黄蓉": {
