    "月": 1,
    "日": 12,
    "时": 21
  },
  "事件引子": "你听说在襄阳城外的荒谷中，一个独臂少年每日与神雕搏击，服蛇胆增膂力，更在暴雨山洪中练出了一套震古烁今的重剑剑法...",
  "后续事件": {
    "事件名": "第26回-10-杨过夜入襄阳",
    "描述": "杨过练成重剑后辞别神雕，背负玄铁重剑连夜奔赴襄阳报仇"
  },
  "事件详情": "杨过次晨醒转神雕已衔了三枚深紫色腥臭圆球放在身边——原来是蛇胆。他一口一个吃了静坐调息，突然之间平时气息不易走到的各处关脉穴道竟尔畅通无阻。跃起身来提起重剑出洞又和神雕练剑，此时已去了几分畏惧之心，虽然仍是避多挡少但在神雕凌厉无伦的翅力之间偶然已能乘隙还招。如此练剑数日，杨过提着重剑时手上已不如先前沉重，击刺挥掠渐感得心应手。同时越来越觉以前所学剑术变化太繁花巧太多，想到'重剑无锋大巧不工'八字，其中境界远胜世上诸般最巧妙的剑招。每日服食神雕采来的蛇胆，不知不觉间膂力激增。这一日清晨满天乌云大雨倾盆，神雕咬着他衣襟拉向东北方——转过山峡只见山峰间一条大白龙似的瀑布奔泻而下冲入溪流奔腾雷鸣。神雕跃入溪中站在巨石之上左翅将上流冲下的岩石一次次打回。杨过会意——剑魔独孤求败昔日每遇大雨便到这山洪中练剑。他双足一入水山洪便冲得左摇右晃难于站稳——当即屏气凝息奋力与激流相抗。练到力气渐尽跃回岸上，神雕却不容他歇息挥翅又来搏击。他只得再跃入水心继续苦练。时刻稍久渐渐悟到了凝气用力的法门，山洪越来越大直浸到腰间反而不如先前难以支持。杨过生来要强好胜——不肯被神雕小觑，见到溪流中带下的树枝山石便举剑挑刺向上流反推上去。岩石在水中轻了许多，重剑受水力一托也已大不如平时沉重出手反感灵便。他在水中悟得了许多顺刺、逆击、横削、倒劈的剑理，到这时方始大悟——以此使剑真是无坚不摧剑上何必有锋？那一日他在溪边望着山洪奔腾而下心通其理手精其术，知道重剑的剑法已尽于此不必再练——便是剑魔复生所能传授的剑术也不过如此。将来内力日长所用之剑便可日轻终于使木剑如使重剑——那只是功力自浅而深全仗自己修为。回眼看到右臂断折之处想起郭芙截臂之恨——雄心登起决心要以重剑剑术打得天下群雄束手。连夜回到山洞向神雕辞别——向独孤求败石冢拜了几拜，在谷口与神雕搂抱亲热了一阵依依而别。采了三条老藤搓成一带将重剑系了负在背上，施展轻身功夫直奔襄阳。",
  "事件概要": "杨过在神雕督逼下悟成重剑剑理，内力膂力大进，带着玄铁重剑和断臂之恨重返襄阳。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第26回-09-杨过山洪中悟重剑剑道": "每日服食神雕所采怪蛇蛇胆膂力激增——平时气息不易走到的各处关脉穴道竟畅通无阻。与神雕每日练剑提着重剑时手上已不如先前沉重击刺挥掠渐感得心应手。越来越觉以前所学剑术变化太繁花巧太多——'重剑无锋大巧不工'八字境界远胜世上诸般最巧妙的剑招。大雨中山洪暴发——神雕带他到溪边逼他在山洪中练剑。初时被激流冲得左摇右晃——渐渐悟到凝气用力的法门竟能中流砥柱般屹立不动。举重剑挑刺水中岩石向上游反推——悟得了顺刺逆击横削倒劈的剑理。最终大悟——以此使剑无坚不摧剑上何必有锋。仰望明月心通其理手精其术——知道重剑剑法已尽于此不必再练。雄心登起决心要以此剑术打得天下群雄束手才甘心就死。连夜辞别神雕——采藤条搓带将玄铁重剑负在背上直奔襄阳"
      }
    },
    "神雕": {
      "人物经历": {
        "第26回-09-神雕逼杨过山洪练剑": "每日采蛇胆喂杨过助他增强内力。见杨过力气日增能乘隙还招便不断以翅力扑啄喂招。大雨之日咬杨过衣襟拉向山洪——展示如何在急流中以翅击岩。不容杨过歇息一次次逼他入水练剑——成为最严厉的师父。杨过练成告辞时直送他到谷口——一人一雕搂抱亲热依依而别"
      }
    }
  },
  "update": {
    "杨过": {
      "状态": "在荒谷中随神雕练剑月余——服食蛇胆后内力大增膂力激增。在山洪中练剑悟得重剑剑理——顺刺逆击横削倒劈无坚不摧。已明白'重剑无锋大巧不工'的真谛——重剑剑法已尽于此。臂伤已愈武功反而大进——报仇雪恨之念再也难以抑制。以藤条作带将七八十斤的玄铁重剑负在背上——直奔襄阳",
      "境界": "一流-圆满",
      "功法": {
        "重剑剑法": {
          "掌握程度": "融会贯通（在山洪激流中练成——悟得顺刺逆击横削倒劈的剑理。以此使剑无坚不摧剑上何必有锋。知道重剑剑法已尽于此——便是剑魔复生所能传授的也不过如此。将来内力日长所用之剑便可日轻终于使木剑如使重剑——那只是功力自浅而深全仗自己修为）"
        }
      }
    },
    "神雕": {
      "状态": "每日采蛇胆给杨过服食增强内力。逼杨过在山洪激流中练剑——反复将他赶入水中不容懈怠。在谷口与杨过搂抱亲热依依送别",
      "所在位置": "大宋/襄阳城外/独孤求败荒谷"
    }
  },
  "参与人物": [
    "杨过",
    "神雕"
  ]
}

