  "事件详情": "五人转到山后，只见一株大树旁有间破旧茅舍柴扉紧闭，门上钉着一张白纸写着四行十六个大字：'桃花岛主，弟子众多，以五敌一，贻笑江湖！'黄药师哈哈一笑，随手拾起两粒石子以弹指神通弹出，嗤嗤声中十余步外的两扇板门竟被小小石子撞开。门开处只见李莫愁端坐蒲团手捉拂尘低眉闭目正自打坐，神光内敛妙相庄严俨然是个有道之士——屋内只她一人。杨过一转念便即明白：她讥笑黄岛主弟子多以众凌寡便索性连洪凌波也远远遣开了，她所恃的不是能敌得过黄岛主，而是孤身一人令黄岛主自恃身份不能动她。陆无双拔剑要三人齐上拚了，黄药师却叹道：'黄老邪果然徒弟众多，若是我陈梅曲陆四大弟子有一人在此，焉能让她说嘴？'将手一挥道回去罢。四人不明他的心意跟着回茅舍，只见他郁郁不乐晚饭也不吃竟自睡了。杨过回想日间与傻姑的说话又琢磨李莫愁神情，心想以自己一人之力也未必敌她不过，不如悄悄去跟她恶斗一场——一来雪她辱姑姑之耻，二来也好教岛主出了这口气。他盘膝练气养足精神——这一调息触发体内深厚内力发出龙吟虎啸之声，由此黄药师惊喜之下传授弹指神通与玉箫剑法（此段详见事件06）。不久天色已明，程英走了进来手中托着件青布长袍微微一笑：'你试穿着瞧瞧合不合身。'杨过好生感激接过时双手微微发抖。他与程英目光相接见她眼中脉脉含情温柔无限，走到床边将新袍换上但觉袍身腰袖无不适体。程英嫣然一笑随即露出凄然之色叹道：'师父他老人家走了，又不知几时方得重会。'正想坐下说话忽见门外黄衫一闪随即隐没，知是表妹在外不便多耽，站起身来缓步出门。杨过细看新袍针脚绵密不由得怦然心动：'她对我如此，媳妇儿又是待我这般，可是我心早有所属义无旁顾。若不早走徒惹各人烦恼。'他独自到山后窥察，见李莫愁所居茅舍已化成灰烬——原来她放火烧屋竟已走了。晚间杨过在灯下留书作别，写了一半便又撕了，这一晚翻来覆去难以睡稳。",
  "事件概要": "李莫愁留帖再逼，黄药师飘然离去，程英赠袍送别，情分未明却更难割舍。",
  "insert": {
    "杨过": {
      "重要物品": {
        "青布长袍": "程英亲手缝制——依着杨过原来衣衫式样裁剪，针脚绵密无不适体。杨过心知这件袍子针针线线都是程英的情意"
      },
      "人物经历": {
        "第15回-08-李莫愁留帖黄药师离去程英赠袍": "随黄药师等人去看李莫愁留下的十六字揭帖——'桃花岛主弟子众多以五敌一贻笑江湖'——理解了李莫愁有恃无恐的算计。回茅舍后黄药师郁郁不乐径自睡了。杨过本想独自去斗李莫愁为姑姑和岛主出气，盘膝练气时触发内功长啸由此引出黄药师传授绝艺。次日清晨程英送来亲手缝制的青布长袍，杨过见她眼中脉脉含情温柔无限，换上后无不适体心中感激。见李莫愁已烧屋离去大敌既去，晚间想留书作别却写不下去，翻来覆去难以睡稳——舍不得程英陆无双却又知自己心有所属必须离去"
      },
      "关系网": {
        "程英": "亏欠/85（她这般深情厚意杨过感激不尽——青布长袍针针线线都是心意。但杨过心中已有小龙女，生怕再耽下去徒惹各人烦恼，心中又感动又愧疚）"
      }
    },
    "李莫愁": {
      "人物经历": {
        "第15回-08-李莫愁留帖黄药师离去程英赠袍": "在黄药师茅屋西面山后一间破旧茅舍中打坐，门上钉白纸写着'桃花岛主弟子众多以五敌一贻笑江湖'十六字——讥讽黄药师以多欺少。故意遣开洪凌波孤身一人，料定以黄药师大宗师身份不会对孤身女子出手。黄药师果然因身份所限不能出手郁郁而回。李莫愁随后放火烧了茅舍离去"
      }
    },
    "程英": {
      "人物经历": {
        "第15回-08-李莫愁留帖黄药师离去程英赠袍": "随师父去看李莫愁所留十六字揭帖。见师父郁郁不乐晚饭不吃径自睡了心中难过。次日清晨捧着自己亲手缝制的青布长袍走进杨过房中让他试穿——眼中脉脉含情温柔无限。想起师父已去不知何日重会面露凄然之色。见门外表妹黄衫一闪不便多留缓步出门"
      },
      "关系网": {
        "杨过": "暗恋/95（赠袍之举已将她心中情意表露无遗。然而程英知道杨过心中只有小龙女——她这般温雅的女子不会强求，只在赠袍时眼中流露一点情意，随即凄然退出。她愿杨过养好伤后便去寻他的姑姑）"
      }
    }
  },
  "update": {
    "李莫愁": {
      "状态": "已离去（烧毁茅舍离开荒山。虽以十六字帖羞辱黄药师成功逼得他不能出手，但黄药师身份不会二次出手，她留下也是徒然。烧屋离去宣告此间恩怨暂告一段落）"
    },
    "黄药师": {
      "状态": "已离去（见李莫愁十六字帖羞辱——若陈梅曲陆四大弟子有一人在此焉能让她说嘴——想起当年自毁贤徒心中郁郁。虽已传授杨过武功托其三年后报仇，自己却因身份所限不能出手。将诸事交代后已大笑振衣远去）",
      "人物经历": {
        "第15回-08-李莫愁留帖黄药师离去程英赠袍": "见李莫愁留帖羞辱——虽以弹指神通弹开板门见到李莫愁端坐其中却因对方孤身一人不宜出手。叹道'黄老邪果然徒弟众多若是我陈梅曲陆四大弟子有一人在此焉能让她说嘴'，将手一挥带众人回去。回茅舍后郁郁不乐晚饭也不吃竟自睡了"
      }
    },
    "陆无双": {
      "人物经历": {
        "第15回-08-李莫愁留帖黄药师离去程英赠袍": "见李莫愁留帖羞辱桃花岛——想起父母之仇霍地拔出长剑要三人齐上拚命被黄药师制止。回去后见表姊程英一早从杨过房中出来，心中已知表姊对杨过情深意重"
      }
    }
  },
  "参与人物": [
    "黄药师",
    "李莫愁",
    "杨过",
    "陆无双",
    "程英"
  ]
}

