  "事件引子": "杨过小龙女携手踏入剑室。杨过识破门口机关救了小龙女。二人在剑室中倾诉衷情拥吻缠绵。小龙女不慎被情花刺伤手指。最终选中成双成对的君子淑女剑。",
  "后续事件": {
    "事件名": "第18回-09-双剑合璧斗阴阳情花毒发杨过遭擒",
    "描述": "二人携君子淑女剑回到大厅，以玉女素心剑法合斗公孙止的阴阳双刃。情花之毒突然发作，杨过剑被打落遭渔网擒住。"
  },
  "事件详情": "杨过与小龙女来到第三间房前，小龙女正要跨门槛进去，杨过伸手拉住小心了——左足踏在门槛外右足跨门槛往地板上一点立即缩回。猛听得嗤嗤声响眼前白光闪动，八柄利剑自房门上下左右挺出纵横交错布满入口——若是有人踏步进门武功再高也难免给这八柄利剑对穿而过。小龙女透了口长气说谷主恁地歹毒。身后八名绿衫弟子手持带刀渔网拦住后路——公孙止防二人逃走。二人携手步入剑室随手带上门。室中壁上桌上架上柜中尽皆列满古剑。小龙女凝视杨过半晌突然嘤的一声投入他的怀中，杨过将她紧紧抱住在她嘴上亲去。小龙女在他一吻之中心魂俱醉双手伸出去搂住他头颈。突然砰的一声室门推开绿衫弟子催促进剑。小龙女叹道'待咱们打败了那谷主你再这般亲我'。杨过笑应'我永生永世也亲你不够'。小龙女在壁间逐一看剑时杨过说出识破机关之法——从谷主脸色眼光猜想而知。二人说起玉女素心剑法又谈起法王激将的私心，杨过又问起呕血伤势柔声细语情致缠绵。小龙女道'自从那天在终南山的晚上你和我这般亲热我怎么还能是你的师父。你虽不肯娶我为妻在我心里我早就是你的妻子了'。杨过道'咱们胜了那谷主立即动身回古墓以后不论甚么你永远不能再离开我身边'。小龙女抬起头发誓便是天塌下来也不离开。二人携手去取剑，发现火烧焦痕——原是周伯通曾经来过烧去半截画幅露出两段剑鞘。双剑出鞘都是一段黑木般乌黑无光，既无尖头又无剑锋圆头钝边似薄薄木鞭。剑身分别刻着'君子'和'淑女'二字。杨过笑道剑名君子淑女我可当不起，举剑虚刺觉得轻重合手极是灵便。正要出室时小龙女见桌上花瓶插着一丛娇艳花朵顺手去整理——杨过叫使不得已为时不及，小龙女手指被情花刺中数下。",
  "事件概要": "杨过与小龙女在剑室取到君子淑女双剑，但情花已刺伤二人，为后患埋下毒根。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第18回-08-剑室选剑诉情定约诀别之言永不相离": "在剑室门口识破公孙止的机关——'从谷主的脸色和眼光中猜想而知'，救了小龙女一命。在剑室中将小龙女紧紧抱住亲吻。对小龙女说'我永生永世也亲你不够'。二人说起联手斗谷主的策略和法王的用心。向小龙女提出'咱们胜了那谷主立即动身回古墓以后不论甚么你永远不能再离开我身边'——小龙女答应后天塌下来也不离开。发现周伯通火烧焦痕露出两段剑鞘，取出君子淑女双剑。举剑虚刺觉得轻重合手极是灵便。要解释情花时绿衫弟子已来催促不及细说。"
      },
      "重要物品": {
        "君子剑": "与小龙女的淑女剑成双成对的古剑。剑身乌黑无锋无尖圆头钝边，但轻重合手极是灵便"
      }
    },
    "小龙女": {
      "人物经历": {
        "第18回-07-剑室中与杨过拥吻定约选君子淑女剑": "踏入剑室就投入杨过怀中让他亲吻——心魂俱醉搂住他头颈。被绿衫弟子打断后叹道待打败谷主再亲。向杨过坦露心声——'自从那天在终南山的晚上你和我这般亲热我怎么还能是你的师父。在我心里我早就是你的妻子了'。杨过要求回古墓后永不分离时抬头发誓便是天塌下来也不离开。与杨过一同发现君子淑女剑——喜其成双成对的名字。因不识情花去整理桌上花束时手指被刺中数下——尚不知这情花毒将带来何等劫难。"
      },
      "重要物品": {
        "淑女剑": "与杨过的君子剑成双成对的古剑。剑身乌黑无锋无尖圆头钝边"
      }
    },
    "公孙止": {
      "人物经历": {
        "第18回-09-命弟子催促二人选剑疑女儿告密": "见二人在剑室中耽搁许久极不耐烦向绿衫弟子怒目而视。待二人取出君子淑女剑时心中一凛厉声问是谁教取这剑的——眼光向公孙绿萼一扫随即又定在小龙女脸上。此双剑是他深藏之物竟被二人误打误撞选中。对女儿更加猜疑"
      }
    }
  },
  "update": {
