  },
  "事件结束时间": {
    "年": 1244,
    "月": 12,
    "日": 25,
    "时": 8
  },
  "事件引子": "饭铺众人正要离开，门口白影一闪，小龙女走了进来...",
  "后续事件": {
    "事件名": "第24回-09-法王拉拢赵志敬谋夺掌教",
    "描述": "法王等人抵达忽必烈大营，法王开始拉拢赵志敬谋划夺取全真掌教之位"
  },
  "事件详情": "众人正要离开饭铺，小龙女走了进来在角落小桌旁坐了，向店伴吩咐做一碗口蘑素面。尹赵二人脸上一阵青一阵白惴惴不安，法王也怕杨过随后来到。萨多邀尹赵同去见忽必烈，赵志敬心念一动想借法王相护以逃过小龙女追杀便答应了。各人出店上马而行，小龙女骑了一头驴子遥遥跟随在后。天黑后众人驰了一阵在林中歇马，小龙女与众人相隔十余丈坐在林边。歇了半个时辰上马再行，直至天明小龙女始终隔开数十丈跟随在后。次日来到空旷平原，法王心中毒念陡起想趁无人骤下杀手毙了小龙女。忽听前方驼铃声传来，一彪人马迎头奔来——四头骆驼之间用绳网悬空坐着一人，白须白眉笑容可掬竟是周伯通。周伯通盗了忽必烈的王旗要给结义兄弟郭靖做见面礼。法王大惊暗想王旗被夺脸可丢大了。尹赵二人听到'老顽童'三字脱口呼师叔祖翻鞍下马。周伯通踢出两只鞋子分向二人面门飞去——飞到三尺处突然折回绕圈交叉回到脚上，显了一手极深厚的内功。赵志敬伸手抓空大为骇服，与尹志平一同拜倒叩见师叔祖。法王用激将法骂周伯通是无耻之徒在王帐外偷偷下手盗旗，周伯通大怒拔下王旗掷还——约定今晚再来盗取。法王接旗旗杆入手才知这一掷之力大得异乎寻常忙运内劲相抗仍退了两步方才站住。",
  "事件概要": "周伯通现身夺旗搅乱蒙古军心，法王与尹赵一行被迫改为防他再盗，终南山外的局势由此骤然升级。",
  "insert": {
    "周伯通": {
      "人物经历": {
        "第24回-08-周伯通盗王旗遇法王": "从忽必烈大营盗走王旗——骑四头骆驼用绳网悬空而坐得意非凡。要给结义兄弟郭靖做见面礼——'他在襄阳城跟蒙古人打仗我就偷了蒙古王爷的王旗给他送一份大礼'。途中遇金轮法王一行。尹志平赵志敬认出自己是师叔祖时问'你们是哪个牛鼻子的门下'。以飞鞋倒回的功夫试探二道——两只鞋子飞到面前三尺折回绕圈交叉回到脚上，显了一手极深厚的内力。被法王用激将法骂作无耻之徒后大怒——将王旗掷还给法王约定今晚再来盗取。旗杆掷出之力大得异乎寻常法王退了两步方才站住"
      },
      "关系网": {
        "赵志敬": "师侄孙/20（问清是王处一门下后哼了一声——'全真教的小道士一代不如一代瞧你们也不是甚么好脚色'。以飞鞋功夫相试——赵志敬伸手抓空显是功夫不到家）",
        "尹志平": "师侄孙/20（问清是丘处机门下——对其态度与赵志敬无异。尹志平不敢失礼仍躬身行礼倒是守规矩的）"
