    "月": 9,
    "日": 25,
    "时": 0
  },
  "事件引子": "江湖传言，有人在桃花岛上听闻了关于《九阴真经》起源的惊天秘密。",
  "后续事件": {
    "事件名": "第17回-01-周伯通忆往事",
    "描述": "周伯通被黄蓉言语所激，为了打发时间并证明《九阴真经》并非阴毒武功，开始向郭靖传授经中武学。"
  },
  "事件详情": "郭靖与周伯通结为兄弟后，周伯通兴致大发，向郭靖讲述了自己被困桃花岛以及《九阴真经》的来龙去脉。故事始于北宋文官黄裳，他因校对道藏而无师自通，成为绝顶高手。后因与明教结仇，家人被杀，他躲入深山四十年，悟出破解天下武功之法，写成《九阴真经》。真经问世后，引得江湖腥风血雨。最终由“五绝”在华山论剑，王重阳技压群雄夺得真经，意在平息纷争。王重阳逝世当晚，西毒欧阳锋前来抢经，不料王重阳早已留下后手，破棺而出，以“一阳指”重创欧阳锋，但自己也油尽灯枯而逝。周伯通奉师兄遗命，携下卷经书南下藏匿，途中遇到黄药师与其新婚妻子冯氏，因打赌而将经书借给冯氏观看。冯氏有过目不忘之能，将经文默记心中。周伯通自觉上当，追至桃花岛，但黄药师已凭妻子默写的经文练功，周伯通不敌，从此被困岛上十五年。",
  "事件概要": "郭靖由周伯通知晓九阴真经与桃花岛旧怨的来历，往后围绕真经的争端脉络至此被彻底看清。",
  "insert": {
    "郭靖": {
      "人物经历": {
        "第16回-08-九阴真经的由来": "从义兄周伯通口中，第一次完整地听闻了《九阴真经》的起源、华山论剑的缘由以及王重阳、黄裳、黄药师、欧阳锋等人与这部经书的诸多往事，眼界大开。"
      },
      "重要物品": {
        "《九阴真经》下卷经文皮卷": "从朱聪处得来，原包在匕首之外，被郭靖无意中获得并随手放在怀内，尚不知其为真经秘要。"
      }
    },
    "周伯通": {
      "人物经历": {
        "第16回-08-九阴真经的由来": "向义弟郭靖详细讲述了《九阴真经》的来历和自己被困桃花岛十五年的前因后果，一吐心中郁结多年的秘密。"
      }
    },
    "黄裳": {
      "人物经历": {
        "第16回-08-九阴真经的由来": "其创制《九阴真经》的传奇往事，通过周伯通的讲述而为郭靖所知。"
      }
    },
    "冯氏": {
      "人物经历": {
        "第16回-08-九阴真经的由来": "其为丈夫黄药师默写《九阴真经》下卷，最终心力交瘁而亡的往事，通过周伯通的讲述被提及。"
      }
    }
  },
  "参与人物": [
    "郭靖",
    "周伯通"
  ]
}

428003.content:
{
  "事件地点": "大宋/终南山/潼关道破石屋",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 9,
    "日": 7,
    "时": 4
  },
  "事件结束时间": {
    "年": 1244,
    "月": 9,
    "日": 7,
    "时": 5
  },
  "事件引子": "你听说石屋外传来赤练仙子李莫愁的声音，杨过和陆无双都大惊失色……",
  "后续事件": {
    "事件名": "第8回-08-杨过接骨后抱陆无双连夜逃往江南",
    "描述": "李莫愁师徒离去后，杨过终于为陆无双接好断骨，抱着她连夜逃离。"
  },
  "事件详情": "杨过正要为陆无双接骨时忽听门外李莫愁的声音道这小贱人定然在此方圆二十里之内咱们赶紧搜寻。陆无双听到师父声音吓得面无人色伸手按住杨过嘴巴。原来李莫愁师徒从活死人墓死里逃生回赤霞庄发现陆无双逃走还盗了《五毒秘传》——此书载有五毒神掌与冰魄银针的毒药解药配方，若流传出去她便如赤练蛇被拔去毒牙。李莫愁大怒带洪凌波连日连夜追赶，在潼关附近见一名丐帮弟子被弯刀掷中肩头正是陆无双的银弧刀料她必在左近便追到破屋前。洪凌波推门进屋，她对师妹尚有些情谊举剑往陆无双心窝刺去想免她零碎受苦。李莫愁拍开她的剑冷笑道难道我不会杀人要你忙。陆无双自知无幸把心一横躺着等死，昂然道你与我家累世深仇什么话也不必说。就在此时一头大牯牛急奔入门——牛右角缚了一柄单刀左角缚着烧得正旺的柴火。原来杨过趁三人对峙时溜出后门赶到牛旁绑上柴火单刀驱牛冲入，自己伏在牛腹下一把抱起陆无双藏在牛腹底逃出屋去。李莫愁追上牛背查看无所获跃下往北方追去。杨过抱着陆无双跃入长草中隐藏。陆无双微挣发觉被杨过搂在怀内又羞又急。杨过低声道别上当你师父在骗你——果然李莫愁假意离去后又悄没声掩回。杨过识破她计谋这才当真走了。",
  "事件概要": "李莫愁师徒追至，杨过借牛腹藏身救出陆无双，五毒秘传在外流失的风声也彻底坐实。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第8回-07-李莫愁师徒追至杨过牛腹藏身救无双": "正要给陆无双接骨时听到李莫愁声音大吃一惊，当即溜出后门赶到牛旁，拾起陆无双掉落的单刀和枯柴分别绑在牛角上点着柴枝。伏在牛腹下手脚抱住牛身驱牛冲进石屋，趁李莫愁师徒惊愕之际一把抱起陆无双藏在牛腹下冲出屋去。饶是李莫愁精明也没瞧出破绽。待李莫愁追上牛背查看后跃下远追，杨过已抱着陆无双跃入长草隐藏。李莫愁假意离去又悄没声掩回，杨过识破轻声告诉陆无双别上当，果然李莫愁见无人应声这才真正走了。"
      }
    },
    "陆无双": {
      "人物经历": {
        "第8回-07-李莫愁师徒追至杨过牛腹藏身救无双": "听到师父李莫愁声音吓得面无人色，自料落在她手中必受千般折磨而死。把心一横向李莫愁昂然道你与我家累世深仇什么话也不必说。万料不到那傻蛋牧童竟想出牛角缚柴火的奇计——驱牛冲入石屋趁乱从牛腹下将自己救出。颠动中断骨相撞痛得死去活来，迷糊中不知被救经过。伏在杨过怀中时听他低声道别上当才恍然明白自己逃过一劫。对杨过心存感激却因起始就对他轻视嘲骂不肯改口。"
      }
    },
    "李莫愁": {
      "人物经历": {
        "第8回-07-李莫愁师徒追至杨过牛腹藏身救无双": "从活死人墓死里逃生回到赤霞庄发现陆无双逃走并盗走《五毒秘传》，这一怒非同小可——此书载有五毒神掌与冰魄银针的毒药解药配方，若流传出去赤练仙子便如赤练蛇被拔去毒牙。带洪凌波连日连夜从北到南从南回北兜截几次不见踪影。在潼关附近见到韩姓乞丐肩头插着陆无双的银弧刀，知她必在左近循血迹追至破屋。在屋中见陆无双躺着等死，却突然有怪牛冲入屋内——角上缚着柴火单刀横冲直撞，趁乱间陆无双已影踪不见。追上牛背查看无所获，假意离去又悄没声掩回想诱敌现身，却被杨过识破。一时之间不知向何方追去，与洪凌波一个自北至南一个从西到东分头追寻。"
      }
    },
