    "月": 12,
    "日": 16,
    "时": 16
  },
  "事件结束时间": {
    "年": 1239,
    "月": 12,
    "日": 16,
    "时": 17
  },
  "事件引子": "你听说重阳宫中灯火通明，孙婆婆正被数十名全真道人团团围住……",
  "后续事件": {
    "事件名": "第5回-05-小龙女现身孙婆婆临终托付",
    "描述": "孙婆婆重伤之际，小龙女悄无声息出现在重阳宫大殿门口"
  },
  "事件详情": "孙婆婆打了张志光耳光后，门边两名道士脸色齐变，左右分进合击。孙婆婆晃身从双掌夹缝中窜过，抱起杨过便往墙头跃去。墙外一人纵身跃起双掌迎面推来——二人各退后分别落在墙壁两边。六七名全真教第三代好手连声呼啸将孙婆婆挤在墙角，此上彼退此退彼上波浪般攻了数次，孙婆婆欲携杨过冲出却被硬生生挡住。张志光传令点燃大殿十余根巨烛，烛光下孙婆婆面容惨淡。张志光提出三个放人条件：留下解药、留下杨过、在重阳祖师之前磕头谢罪。孙婆婆哈哈大笑假意下跪，却在弯身低头之际寒光一闪——摸出空瓷瓶以独门暗器手法掷出，击碎在张志光左眼角上血流满面。群道惊怒纷纷拔剑，庭院中剑光耀眼。杨过朗声讥讽全真教威名盖世这等欺侮孤儿老妇的英雄之事若无旁人宣扬岂不可惜，说得群道大半自觉羞愧。孙婆婆以怪异空手入白刃功夫夺下两柄长剑，交一柄给杨过。七道北斗阵渐缩渐小，孙婆婆弃剑抓住一名少年道人胸口逼问让不让路。此时郝大通从身后钻出，连出四掌一掌快似一掌，第四掌使足全真派上乘玄功内力，将孙婆婆推得撞墙——喀喇一响墙上大片灰泥带砖瓦落下，孙婆婆喷出大口鲜血缓缓坐倒委顿在地。杨过大惊伏在她身上舍命相护。",
  "事件概要": "孙婆婆在重阳宫被郝大通重伤，古墓与全真由口角正式变成血仇。",
  "insert": {
    "孙婆婆": {
      "人物经历": {
        "第5回-04-孙婆婆重阳宫遭郝大通重伤": "被六七名全真好手逼在墙角数次冲击不得突围。听张志光提出三个放人条件后哈哈大笑，假意下跪却以空瓷瓶击中张志光左眼角。被群道拔剑围攻时以空手入白刃功夫夺下两柄长剑将一柄交给杨过。弃剑抓住一名少年道人胸口逼问让不让路。终被郝大通连出四掌以全真上乘玄功内力击中——背撞墙壁喷出大口鲜血缓缓坐倒委顿在地"
      }
    },
    "杨过": {
      "人物经历": {
        "第5回-04-孙婆婆重阳宫遭郝大通重伤": "被孙婆婆交予一柄长剑后朗声道自然不怕就可惜没旁人在此——讥讽全真教以众欺寡的英雄之事若无旁人宣扬岂不可惜，说得清脆响亮。群道大半自觉羞愧。见郝大通重伤孙婆婆后大惊伏在婆婆身上大叫你们要杀人杀我便是谁也不许伤了婆婆，张开双手护住孙婆婆将背脊向着郝大通等人全然不顾自己安危"
      }
    },
    "张志光": {
      "人物经历": {
        "第5回-04-孙婆婆重阳宫遭郝大通重伤": "中孙婆婆空瓶暗器后左眼角被碎瓷割伤十多处血流满脸。惊怒中不及细辨还道左眼已被暗器击瞎。心想掌教师伯性子慈和必定吩咐放人自己这只眼睛算是白瞎了，大声叫先拿下这恶婆娘再去请掌教师伯发落。不敢下场进攻只在旁喝令指挥怕血行加剧毒性发作，导致北斗阵威力大为减弱"
      }
    },
    "郝大通": {
      "人物经历": {
        "第5回-04-孙婆婆重阳宫遭郝大通重伤": "夹手抢过孙婆婆抓着的少年道人，跟着一掌当面击来。与孙婆婆对掌硬碰，第三掌快似一掌逼得孙婆婆连退三步背靠墙壁退无可退。到第四掌右掌与孙婆婆手心相抵时朗声要她留下解药和孩子。知孙婆婆与先师渊源不愿相伤掌上留劲不发。不料孙婆婆出腿踢下盘，危急下掌使足全真派上乘玄功内力将孙婆婆推出——喀喇一响墙灰砖瓦落下，孙婆婆喷血坐倒。心下好生后悔欲察看伤势给孙婆婆服药治伤却被杨过遮住"
      },
      "关系网": {
        "孙婆婆": "误伤/40"
      }
    }
  },
  "update": {
    "孙婆婆": {
      "状态": "重伤（被郝大通全真玄功内力击中，撞墙喷血委顿在地，性命垂危）"
    },
    "张志光": {
      "状态": "受伤（左眼角被碎瓷瓶割伤，血流满面）"
    }
  },
  "参与人物": [
    "孙婆婆",
    "张志光",
    "杨过",
    "郝大通"
  ]
}

