  },
  "事件引子": "行到申牌时分，只见前面黑压压一片大树林，林中隐隐传出呼叱喝骂之声——杨过侧耳听去却是金轮法王与郭芙的声音...",
  "后续事件": {
    "事件名": "第14回-11-杨过引法王入石阵法王破阵三人负伤",
    "描述": "杨过以新学的打狗棒法出阵诱敌，将金轮法王引入乱石阵中困住"
  },
  "事件详情": "杨过摸进树林见黄蓉母女、武氏兄弟四人被金轮法王围攻——武氏兄弟脸上衣上都是血渍黄蓉郭芙头发散乱甚是狼狈。黄蓉以乱石布阵，每每危急时躲到石后金轮法王便须远兜圈子方能追及——看来黄蓉等虽危实安只是无法出阵逃走。金轮法王自负才智过人，约退众人凝思乱石阵奥秘——他想通了五行八卦的变化再入阵擒人方显本事。他怔怔看了半天——刚似瞧出端倪左翼对右翼又不对前锋通了后尾又难索解——呆在当地惊佩不已。郭芙一时大意离了阵法蔽障，被金轮法王抓住点中胁下穴道放在地上。杨过见黄蓉竹棒一摆就要奔出去救女——不及细想猛地跃出抓住郭芙后心向乱石堆扑去。金轮法王铁轮飞出——杨过人在半空使个千斤坠身子直落啪地摔在乱石堆上只跌得目青鼻肿。黄蓉抱女悲喜交集忙伸竹棒引杨过入阵。杨过入阵后瞧这乱石阵前前后后好生佩服——黄蓉的聪明才智天下无双。他与黄蓉谈起黄药师悠然神往——'几时能拜见他老人家一面不枉了这一生'。金轮法王再次攻入——杨过拾黄蓉竹棒使出打狗棒法接战。黄蓉接引杨过入阵后决意将打狗棒法中精微变化一并传授——她说洪七公传了杨过三成杨过自己偷了二成今日再传二成。杨过大喜又假意推辞被黄蓉白了一眼戳破狡狯，跪倒拜谢笑道'郭伯母我幼小之时你曾答应传我功夫今日才传也还不迟'。黄蓉微微一笑将棒法奥妙一一说知。不到半个时辰杨过已领悟十之八九——他聪明颖悟胜过鲁有脚百倍，闻一知十举一反三。黄蓉又将乱石阵的三十六般变化说给他——青龙怎样演为白虎玄武怎生化为朱雀。原来这乱石阵乃是从诸葛亮八阵图中变化出来——黄蓉事起仓促未及布全只稍具规模。杨过虽聪明一时间记得明白的也只十余变。",
  "事件概要": "杨过救下郭芙后得黄蓉尽传打狗棒法，为之后独斗法王添上关键倚仗。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第14回-10-杨过奋身救郭芙黄蓉秘传打狗棒法全诀": "摸进树林见黄蓉以乱石布阵抵御金轮法王——心中好生佩服黄蓉的聪明才智。见郭芙离阵被擒黄蓉要出阵救女——不及细想猛地跃出抓住郭芙后心向乱石堆扑去。金轮法王铁轮飞来——人在半空千斤坠身直落摔在乱石堆上撞得目青鼻肿。进石阵后与黄蓉谈起黄药师悠然神往。金轮法王再攻入时拾竹棒以打狗棒法接战。黄蓉决意传授打狗棒法精微变化和乱石阵三十六变——杨过跪倒拜谢笑道'郭伯母我幼小之时你曾答应传我功夫今日才传也还不迟'。黄蓉轻声将棒法奥妙一一传授——不到半个时辰杨过领悟十之八九。又记乱石阵变化——虽只记得十余变但足以困敌。黄蓉抿嘴一笑凉风拂鬓夕阳下风致嫣然——'你若肯来我如何不肯教？你舍命救了我和芙儿两次难道我还似从前这般待你么？'杨过听了胸中暖烘烘极是舒畅——此时黄蓉不论教他做什么他百死无悔"
      }
    },
    "黄蓉": {
      "人物经历": {
        "第14回-10-黄蓉乱石阵中御敌传授杨过打狗棒法": "在树林中以乱石布阵抵御金轮法王围攻——武氏兄弟受伤郭芙头发散乱自己腹中隐痛形势危急。郭芙离阵被金轮法王擒住后心如刀割——正要冒险出阵抢女时杨过突然跃出救人。收郭芙后悲喜交集忙伸竹棒引杨过入阵。杨过赞她聪明才智时微笑着未答——郭芙说出是外公所教杨过对黄药师悠然神往连连点头。见金轮法王再次攻入时将打狗棒法精微变化一并传授杨过——洪七公传了三成杨过自己偷了二成今日再传二成。杨过以退为进假意推辞时黄蓉白他一眼戳破狡狯。不到半个时辰讲完窍要——又解说乱石阵三十六般变化。黄蓉说'你若肯来我如何不肯教？你舍命救了我和芙儿两次难道我还似从前这般待你么'——凉风拂鬓夕阳下风致嫣然"
      }
    },
    "郭芙": {
      "人物经历": {
        "第14回-10-郭芙乱石阵中遇险被杨过舍命救回": "在乱石阵中与母亲武氏兄弟一同被金轮法王围攻。一时大意离了阵法蔽障被金轮法王抓住——点中胁下穴道放在地上周身麻痒难当忍不住呻吟。金轮法王故意不点哑穴让她哀声求救。杨过突然跃出抓住她后心向乱石堆扑去——被杨过推入黄蓉怀中脱险。目睹杨过从乱石堆上爬起撞得目青鼻肿"
      },
      "关系网": {
        "杨过": "好奇且微生感激/-5（杨过今日又一次舍命救了自己——撞得目青鼻肿。这已是第二次救命之恩——心中不能再像从前那般敌视他了。虽然嘴上不说但已欠下杨过两条命的恩情）"
      }
    },
    "金轮法王": {
      "人物经历": {
        "第14回-10-金轮法王树林围攻黄蓉陷入乱石阵": "率众围攻黄蓉四人——武氏兄弟受伤但伤非致命己方反有一名武士被郭芙刺死。见乱石堆大有古怪——自负才智过人退开丈余凝思阵法奥秘。精通奇门妙术却无论如何参详不透乱石阵变化——左翼对了右翼生变前锋通了后尾难解——不禁呆在当地惊佩不已。见郭芙离阵立时擒获点穴后故意不点哑穴诱黄蓉出阵。杨过突然跃出救人时铁轮飞出——竟被他千斤坠落避过功败垂成。被杨过持竹棒使打狗棒法接战——脚下在乱石上绊倒踉跄只得跃出阵去。望见杨过向黄蓉磕头二人有说有笑——隐隐觉得二人似有恃无恐全不将自己放在眼内。素来持重不敢大意定要参透机关再定对策"
      }
    }
  },
