  "事件引子": "次晨杨过醒转只觉肩头湿了一片——微觉奇怪，见小龙女不在室中，坐起身来却见桌面上用金针刻着细细的八个字...",
  "后续事件": {
    "事件名": "第14回-10-杨过奋身救郭芙黄蓉秘传打狗棒法全诀",
    "描述": "杨过午后在树林中发现黄蓉母女与金轮法王激斗，奋身相救"
  },
  "事件详情": "次晨杨过醒转只觉肩头湿了一片——微觉奇怪，坐起身来却见桌面上用金针刻着细细八个字：'善自珍重勿以为念。'而桌面泪痕莹莹兀自未干，肩头所湿处也是小龙女泪水。杨过登时脑中一团混乱神智昏乱推窗跃出大叫'姑姑姑姑'。店小二也说不清白衫女客去向。杨过心知此刻时机稍纵即逝——奔到马厩牵出瘦马一跃而上。郭芙从房中出来叫道'你去哪里'，杨过听而不闻沿大路纵马向北急驰。他一路上大叫'姑姑姑姑'却哪里有小龙女的人影。奔出数十里遇见金轮法王一行人骑在马上正向西行。二人眼光一对便知杨过落了单就非法王敌手——杨过双腿一夹瘦马神骏如疾风般急掠而过。法王心念动处勒马不追——寻思'他师徒分散我更有何惧？黄帮主若是尚未远去嘿嘿……'当即率众向来路驰回去找黄蓉。杨过一阵狂奔数十里内访不到小龙女半点踪迹——但觉胸间热血上涌昏昏沉沉险些晕倒在马背上。心中悲苦万分：'姑姑何以又舍我而去？我怎么又得罪她啦？'忽然想起：'啊是了定是我说在古墓之中日久会厌她只道我不愿与她长相厮守。'想到此处眼前登见光明——'她回到古墓去啦我跟去陪着她便是。'不由得破涕为笑在马背上连翻了几个筋斗。定下神来认明方向勒转马头向终南山而去。过午后在路边小店打尖吃面条——出来时匆匆未携银两觑那店主人不防跃马背急奔而逃只听店主人远远叫骂。行到申牌时分只见前面黑压压一片大树林——林中隐隐传出呼叱喝骂之声，侧耳听去竟是金轮法王与郭芙的声音。",
  "事件概要": "小龙女不辞而别，杨过重回得而复失的痛苦中，转而疯狂追寻她的踪迹。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第14回-09-小龙女深夜不辞而别杨过狂追寻师": "清晨醒转发现肩头湿了一片——小龙女已不在室中。桌面上用金针刻着'善自珍重勿以为念'八个字泪痕犹湿。脑中混乱神智昏乱推窗跃出大叫姑姑不止。问店小二不得消息——心知时机稍纵即逝奔马厩牵瘦马沿大路向北急驰一路狂喊姑姑。途中遇金轮法王一行——互相问答后知不是对手驾瘦马疾掠而过。法王勒马不追率众向黄蓉来路驰回。杨过狂追数十里访不到半点踪迹——胸间热血上涌险些晕倒。猛然想起定是昨夜说'在古墓日久会厌'让小龙女误以为他不愿长相厮守——她必是回古墓去了。破涕为笑勒转马头向终南山而去。过午后在路边店吃面——因未携银两觑店主不防跃马逃去只听得远远叫骂。行到申牌时分望见前面黑压压大树林——林中传出金轮法王与郭芙的声音"
      }
    },
    "小龙女": {
      "人物经历": {
        "第14回-09-小龙女深夜不辞而别": "深夜反复思量后趁杨过沉睡写好金针留言'善自珍重勿以为念'在桌上。在杨过肩头流下泪水洒湿了他的衣襟。独自离去不知去向"
      }
    },
    "金轮法王": {
      "人物经历": {
        "第14回-09-金轮法王途遇孤身杨过率众回追黄蓉": "在道上遇见杨过孤身一骑——二人眼光一对便知杨过落了单就非法王敌手。正要擒拿却被瘦马疾掠逃脱。心念一动勒马不追——寻思'他师徒分散我更有何惧黄帮主若是尚未远去嘿嘿'——当即率众人向来路驰回"
      }
    }
  },
  "update": {
    "杨过": {
      "状态": "焦急寻找小龙女（一觉醒来姑姑又不告而别——肩头泪水犹温桌上金针字犹在。疯狂策马追出数十里全无踪迹。以为自己说在古墓会日久生厌令姑姑伤心——决意追去终南山古墓陪她。一路上破涕为笑甚至在马背上翻筋斗——对姑姑终会回到身边的信心变成了执念动力）",
      "关系网": {
        "小龙女": "师父且爱慕/100（姑姑又走了——杨过痛彻心扉。但他坚信姑姑是回古墓去了自己跟去陪着便是——这份痴心与执念从不曾减弱半分。他以为是自己说长大日久会厌的错令姑姑伤心——却不曾想到那正是小龙女爱他至深才忍痛离去）"
      }
    },
    "小龙女": {
      "状态": "不辞而别不知所踪（深夜趁杨过熟睡悄然离去——泪水洒湿了杨过的肩膀。留下金针刻字'善自珍重勿以为念'。她认定自己是不祥之人——喜欢他疼爱他却反而害得他不快活。含泪写下诀别文字黯然离去。此去哪方无人知晓）",
      "关系网": {
        "杨过": "爱侣/100（爱他至深所以不忍他将来因自己被人瞧不起在古墓气闷苦恼——含泪忍痛离开。诀别八字泪痕满桌——这份深情割舍如同剜心。她认定自己不祥会害杨过不快活——所以即使千般不舍也必须离开）"
      }
    },
    "黄蓉": {
      "所在位置": "大宋/大胜关/树林",
      "状态": "树林乱石阵中被金轮法王围攻（劝走小龙女后黄蓉心中不安——翌日不知小龙女已离去更不知杨过正在狂追。自己与女儿武氏兄弟已在树林中遭金轮法王围攻危险万分）"
    }
  },
  "参与人物": [
    "杨过",
    "小龙女",
    "郭芙",
    "金轮法王",
    "黄蓉"
  ]
}

545054.content:
{
  "事件地点": "大宋/襄阳/城西大校场",
  "触发条件": {
    "类型": "时间",
    "年": 1259,
    "月": 10,
    "日": 24,
    "时": 20
  },
  "事件结束时间": {
    "年": 1259,
    "月": 10,
    "日": 24,
    "时": 21
  },
  "事件引子": "你听说杨过的两件寿礼轰动全场后，郭芙愀然不乐——梁长老正要正式请耶律齐上台接任帮主，忽然丐帮人丛中站起一个五袋弟子，开口便问打狗棒何在、鲁帮主之仇可曾报了。",
  "后续事件": {
    "事件名": "第36回-08-第三件寿礼群侠献俘",
    "描述": "何师我暗算击败耶律齐后站到台口邀人再斗，忽然五百猛兽齐声怒吼——校场入口处八位武林名宿高举火炬而来，神雕侠的第三件礼物到了。"
  },
  "事件详情": "郭芙见丈夫艺冠群雄将丐帮帮主之位拿到手，哪知杨过人尚未到却已将丈夫的威风压得丝毫不剩——歼灭蒙古先锋火烧南阳粮草都是送给妹子的生日礼物，十个烟火大字高悬天空唯恐群雄不知此举全是为了妹子。她愀然不乐转念又想杨过恨自己斩他手臂故意削自己面子。梁长老跃上高台正式请耶律齐上台接任帮主，耶律齐抱拳行礼正要说谦抑之言，忽听得丐帮人丛中有人叫道'且慢'。只见一名背负五只布袋的丐帮弟子站起发问——耶律齐的令尊在蒙古贵为宰相令兄也曾居高官，丐帮与蒙古为敌耶律大爷负此重嫌岂能为本帮之主？又提出打狗棒尚未夺回杀害前帮主的凶手还没找到，这两件大事未办便想做帮主未免太性急。此人名叫何师我，十余年来在丐帮中沉默寡言随众碌碌，相貌奇丑无伦。耶律齐据理力争但何师我理正词严咄咄逼人。郭芙叫丈夫教训这大胆狂徒，何师我冷笑本帮事务帮主夫人却管不得。双方终于动手——何师我掌力分布所及几有一丈方圆功力极深厚，与耶律齐拆了五十余招从容化解。黄蓉细看之下暗惊何师我功力至少有四十年以上勤修苦练，在帮中一直隐晦不露。耶律齐渐占上风掌风将对手全身罩住，眼见何师我非变招不可——蓦地里他双手袍袖齐拂一股疾风将台边十余枝火把尽数吹灭。黑暗中只听得二人大叫，有人跌下台来。火把重新点亮后只见耶律齐站在台下左脸鲜血淋漓破了个酒杯大的伤口，何师我却在台上哈哈大笑手掌中抓着一把鲜血——原来他掌击耶律齐胸口却反被郭芙给丈夫穿的软猬甲刺破。耶律齐夺下的半截兵刃是一根五寸来长的钢条中装机括分为两截，上半截被夺余下半截飞出击伤面颊。何师我暗行诈术取胜却假意称不敢居帮主之位须寻棒杀仇后再议，丐帮中竟有人喝起彩来。",
  "事件概要": "霍都以何师我身份暗算重伤耶律齐并阻断接任，丐帮帮主人选与鲁有脚命案真相再生波折。",
  "insert": {
    "霍都": {
      "人物经历": {
        "第36回-07-霍都化身何师我暗算击败耶律齐": "以丐帮五袋弟子何师我的伪装身份在丐帮大会上搅局。十余年来潜伏丐帮——沉默寡言随众碌碌以帮务勤勉逐步升到五袋弟子隐晦不露。当众以两个问题质问耶律齐：打狗棒何在、鲁帮主之仇可报——理正词严咄咄逼人。施展隐藏功力与耶律齐在高台上大战——功力深厚少说四十年以上。以大风袖功夫吹灭火把后在黑暗中使用中装机括的特制兵刃暗算——上半截被夺余下半截飞出击中耶律齐面颊。掌击耶律齐胸口时反被软猬甲刺破手掌鲜血淋漓。暗行诈术取胜后假意称不敢居帮主之位须寻棒杀仇后再议"
      },
      "重要物品": {
        "打狗棒": "丐帮世代相传的至宝信物——从鲁有脚手中夺来，通体碧绿以翠竹削制，坚逾金石"
      },
      "功法": {
        "大风袖": {
          "掌握程度": "炉火纯青（袖功极为深厚，双袖齐拂可鼓出一股劲风将高台四周十余枝大火把同时吹灭）"
        },
        "特制铁杖": {
          "掌握程度": "炉火纯青（中装机括分为两截的奇门兵刃——上半截可被夺去余下半截陡然飞出伤敌，极是阴险诡诈）"
        }
      },
      "身份": {
        "丐帮弟子(伪)": "化名何师我潜伏丐帮十余年，已升至五袋弟子——以帮务勤勉逐步上升隐晦不露武功深藏，只待今日搅局夺位。身份即将暴露"
      }
    },
    "耶律齐": {
      "人物经历": {
        "第36回-07-耶律齐被何师我暗算落败": "被梁长老请上台准备接受帮主之位时遭何师我当众质疑——针对其出身和寻棒报仇之事理正词严令耶律齐无言以对。与何师我比武——施展空明拳和全真教玄门正宗武功，拆到七八十招后渐占上风掌风将对手全身罩住。不料何师我突然以大风袖吹灭火把，在黑暗中以中装机括的特制兵刃突袭。耶律齐以大擒拿手夺下对方兵器上半截但仍被下半截飞出击中左脸颊——创口见骨鲜血淋漓，又被一掌震下高台。虽败却不失气度——摇头对郭芙说'他便是以智取胜也是胜了何况纵然各拼武功我也未必能赢'"
      }
    },
    "郭芙": {
      "人物经历": {
        "第36回-07-郭芙怒护丈夫眼见耶律齐落败": "见杨过两件礼物压过丈夫威风愀然不乐。何师我出言讥刺丈夫时再也按捺不住——喝道'你是谁胆敢在此胡言乱语'。被何师我当众说帮主夫人管不得帮中事务羞得满脸通红。见丈夫被何师我暗算跌下台惊怒交迸——忙抢上去护持。大不服气叫丈夫上台再决胜负，丈夫摇头认输后只得强忍怒气"
      }
    },
    "郭靖": {
      "人物经历": {
        "第36回-07-郭靖观何师我斗耶律齐推测来历": "在台下凝目观战——见何师我一直未露出本门武功便知是在竭力隐藏自身来历。对黄蓉说再拆七八十招齐儿渐占胜势那时他若不认输便得露出真相。耶律齐被暗算跌下台后与黄蓉对望一眼——知道是软猬甲救了耶律齐一命"
      }
    },
    "黄蓉": {
      "人物经历": {
        "第36回-07-黄蓉观何师我武功疑其隐晦不露": "细看何师我武功竟辨不出何家数——招式驳杂全无奇处但功力极深厚少说四十年以上。心想最近十一二年才在丐帮名册中见何师我积劳逐步上升从没听人称道过他武功——决非最近得逢奇遇功力猛进，在帮中一直隐晦不露难道为的便是今天。耶律齐落败后向他招手命近前看他夺来的半截兵刃——是一根五寸来长的钢条一时也想不到武林中有何人以此作为武器"
      }
    },
    "梁长老": {
      "人物经历": {
        "第36回-07-梁长老遭何师我抢白怒斥": "正式请耶律齐上台接任帮主时被何师我打断。被这五袋弟子当众抢白说'反因为果本末倒置'——身为首席长老竟被人当众斥责大胆已极。怒斥何师我狂妄但何师我武功高强言辞犀利——最终只得默许何师我与耶律齐比武定夺"
      }
    }
  },
