  "事件引子": "你行至终南山脚下，远远望见三名道人骑马上山，身后里许之外一个白衣少女骑着一头花驴不即不离地跟随。其中一名道人取出响箭甩出，呜的一声冲天而起。过不多时，四名黄冠道人从山上急奔而下，向为首道人躬身行礼。",
  "后续事件": {
    "事件名": "第25回-06-尹志平接任全真掌教蒙古敕封",
    "描述": "尹志平在隆重仪式中正式接任全真教掌教。接任典礼刚毕，蒙古贵官与潇湘子便入殿宣读大汗敕封圣旨。"
  },
  "事件详情": "小龙女与周伯通分别后，骑上花驴一路追踪尹志平和赵志敬。途中望见烟尘冲天旌旗招展——蒙古大军正从襄阳方向南撤。她见三乘马从山坡旁掠过，马上乘者黄衫星冠正是三个道人，最后一人正是尹志平，与赵志敬和另一年轻道士并骑在前。那年轻道人祁志诚问赵志敬小龙女是谁，得知是教中大敌后吓了一跳。赵志敬挥鞭狂抽马臀一阵急奔，但坐骑没了力气慢下便被花驴逐步赶上。祁志诚提出回头阻挡让尹志平脱身，并透露是奉师父丘处机之命前来召尹志平回重阳宫接任掌教之位。赵志敬不加理睬，尹志平却神色镇静全无抗拒之念——小龙女要杀便伸颈就戮。四人三前一后默默无言朝北而行，朝行晚宿，一路之上十室九空绝无人迹。途中祁志诚告诉尹志平：全真五子闭关是因大胜关英雄大会上见小龙女杨过武功精绝、全真武功在古墓派手下全然不堪一击，五子年高精力就衰，担心十年后全真非一败涂地不可，便决意闭关钻研一门厉害武功出来相抗。这日到了终南山脚下，祁志诚取响箭甩出，四名道人从山上急奔而下向尹志平躬身行礼改称'清和真人'——只待清和真人一到即便接任掌教。赵志敬被冷落在后又是气恼又是羡妒，暗自盘算掌教之位落入己手时再瞧众人嘴脸。",
  "事件概要": "小龙女一路追随尹志平、赵志敬等人抵达终南山；尹志平将奉命接任全真掌教，赵志敬则因受冷落而暗谋夺位。",
  "insert": {
    "小龙女": {
      "人物经历": {
        "第25回-05-小龙女追踪三道人至终南山": "骑花驴一路追踪尹志平赵志敬——见三乘马上乘着三个黄冠道人最后一人正是尹志平。花驴后劲极长——不疾不徐小跑始终跟随里许不即不离。赵志敬狂抽马臀急奔但坐骑力尽慢下花驴又逐步赶上——他对小龙女如影随形的追踪胆战心惊。傍晚在一所破屋歇宿时小龙女在两株树间悬一根绳子横卧绳上——祁志诚见她如此功夫暗暗心惊只有尹志平坦然高卧理也不理。次日继续跟踪——对千军万马无路可寻两个道士之事心中踌躇却始终没有出手。数日后到了终南山脚下——相隔里许不即不离相随。心中只想跟住她恨极的两人——只消一出手便能将二人杀了但总觉得杀了他们那又如何"
      }
    },
    "尹志平": {
      "人物经历": {
