  },
  "事件引子": "赵志敬向鹿清笃使了个眼色，喝道：'上罢！'两人双剑齐出，向杨过右胁断臂之处刺去。杨过怀中尚有重伤的小龙女，右手空空左臂扶着佳人——看似已是束手待毙。",
  "后续事件": {
    "事件名": "第27回-08-小龙女金针破僵局杨过败法王退蒙古群敌",
    "描述": "杨过叫道：'金轮法王，咱们的帐是今日算呢，还是留待异日？'金轮法王缓步而出，金银铜铁铅五轮拿在手中。"
  },
  "事件详情": "赵志敬与鹿清笃双剑齐出向杨过右胁刺去——赵志敬看准了他断臂不能还手使上了毕生修为劲力。丘处机喝令留情，马光佐高叫'牛鼻子要脸么刺人家的断臂'。突见灰影一闪鹿清笃那高大肥胖的身子飞将起来砰的一声撞在尼摩星身上仰天一交摔倒。杨过右手空袖猛地拂起一股巨力将鹿清笃摔出。赵志敬感到袖力沉猛忙使千斤坠定住身子但长剑低垂被杨过起脚踏住剑刃。杨过冷冷的说让他去罢右足不动足底劲力却突然消除——赵志敬正运强力回夺手中猛地一空剑柄重重撞在胸口一口鲜血喷出仰天跌倒。尼摩星挥杖扑至左手拐杖架开王刘二剑右手拐杖向杨过小龙女头顶猛击。杨过左手抽出背负的玄铁重剑顺手挥出——噗的一声闷响尼摩星右手虎口爆裂铁杖激飞上天直落二十余丈到玉虚洞后。尼摩星生性悍勇左手铁杖劈下，杨过剑尖抖处将铁拐粘住发力下压直戳入土，念其也是断腿之人心起怜悯饶了一命。潇湘子纵身而出挥哭丧棒击来，杨过持剑不动内劲传至剑上——剑棒相交哭丧棒登时断成七八截四下飞散，杨过左击右击两剑将潇湘子双臂齐折。尹克西贪念大炽以金龙鞭卷住玄铁剑欲夺，又左手出匕首偷袭小龙女。杨过情急之下挺剑送出连剑带鞭撞去——尹克西虽早有提防仍被震得连退五六步五脏六腑都似翻转僵立当地。杨过接过玄铁剑轻轻一抖金龙软鞭震成碎块金银珠宝散了满地。",
  "事件概要": "杨过以玄铁重剑连败赵志敬、尼摩星、潇湘子、尹克西，独臂之身威震全场，重阳宫战局被他强行改写。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第27回-07-杨过玄铁重剑大显神威独臂连败众高手": "以空袖拂飞鹿清笃撞倒尼摩星。以右足踏住赵志敬长剑突然收力令其剑柄自撞胸口重伤。抽出玄铁重剑首次以剑魔独孤求败的重剑临敌——先震飞尼摩星铁拐又以柔力粘住铁拐下压入土，再一剑震断潇湘子哭丧棒七八截并连击两剑折其双臂。最后挺剑将尹克西连剑带鞭震得五脏如翻转。一连败尼摩星、潇湘子、尹克西三大高手都是一招之间便伤了对手，众人相顾骇然均想此人的武功当真邪门。"
      }
    },
    "赵志敬": {
      "人物经历": {
        "第27回-07-赵志敬双剑攻杨过反被踏剑自撞重伤": "与鹿清笃双剑齐出刺向杨过右胁断臂之处。被杨过右足踏住长剑用力拔夺不出，杨过突然消去劲力后剑柄重重撞在胸口——剧痛之下一口鲜血喷出眼前一黑仰天跌倒。"
      }
    },
    "鹿清笃": {
      "人物经历": {
        "第27回-07-鹿清笃攻杨过被空袖拂飞撞倒尼摩星": "随赵志敬双剑齐出刺向杨过。被杨过右手空袖猛地拂起一股巨力摔飞出去，正好撞在尼摩星身上。尼摩星双腿已断两手撑着拐杖登时被撞倒，起身后一拐杖打在鹿清笃背上将其打晕过去。"
      }
    },
    "尼摩星": {
      "人物经历": {
        "第27回-07-尼摩星攻杨过被重剑震飞铁拐下压入土": "被鹿清笃撞倒后恶气未出，挥双拐攻向杨过小龙女。左手拐杖架开王处一刘处玄双剑，右手拐杖向二人头顶猛击。杨过抽出玄铁重剑顺手挥出击飞铁杖二十余丈。自恃悍勇左手铁杖再劈被杨过以柔力粘住下压深入土中。杨过念其也是断腿之人同病相怜饶了一命。右臂酸麻全无知觉脸如死灰僵在当地。"
      }
    },
    "潇湘子": {
      "人物经历": {
        "第27回-07-潇湘子欲擒杨过反被震断哭丧棒双臂齐折": "心想快抢先擒了杨过正是扬名立威良机，纵身而出挥纯钢哭丧棒击去。杨过持剑不动内劲传至剑上——剑棒相交哭丧棒登时断成七八截四下飞散。被杨过玄铁剑左击右击两剑双臂齐折，大惊呼叫。"
      }
    },
    "尹克西": {
      "人物经历": {
        "第27回-07-尹克西藏语问于金轮法王": "见杨过以重剑连败尼摩星、潇湘子，认出玄铁剑是天下至宝贪念大炽。以金龙鞭卷住玄铁剑运劲便夺却撼动不得分毫。站近看了分明后左手出匕首偷袭小龙女胸口欲令杨过分心。杨过挺剑送出连剑带鞭猛撞过来——被震得连退五六步五脏六腑如翻转僵立当地。金龙软鞭被杨过轻轻一抖震成碎块金银珠宝散了满地。"
      }
    }
