    },
    "尼摩星": {
      "所在位置": "大宋/终南山/重阳宫",
      "状态": "被杨过以玄铁重剑一击震得手臂酸麻铁拐入土。杨过念同病相怜之情饶其一命——惊魂未定僵立当场。"
    },
    "潇湘子": {
      "所在位置": "大宋/终南山/重阳宫",
      "状态": "被杨过重剑震断兵刃又连折双臂——身受重伤倒地被蒙古武士抬起。"
    },
    "尹克西": {
      "所在位置": "大宋/终南山/重阳宫",
      "状态": "被杨过重剑震得内伤，金龙软鞭已碎成块珠宝散地——不敢运气不敢移动半步僵在当地。"
    }
  },
