    "杨过": {
      "功法": {
        "打狗棒法实战运用": {
          "掌握程度": "初窥门径（首次以正宗打狗棒使打狗棒法——将口诀心法与招式印证贯通，虽未尽得精微但威力远超断桨时。黄蓉临场指点令其威力倍增）"
        }
      }
    }
  },
  "update": {
    "杨过": {
      "状态": "以打狗棒法逼得霍都险败（黄蓉将打狗棒借给他后威力大增——加上黄蓉临场指点口诀，霍都空有一身武功竟被一根竹棒逼得团团乱转。但口诀与招数尚不及融会贯通——越斗越是吃力。全凭黄蓉一句一句出言指点才占上风）",
      "人物经历": {
        "第13回-03-杨过持打狗棒黄蓉临场指点斗霍都": "被霍都掌力困住时黄蓉伸棒将二人隔开——将打狗棒借给他嘱逼霍都交解药。提棒使打狗棒法威力倍增——棒刺霍都关元穴令其改取守势。霍都全力进攻二十余招后已相形见绌——口诀与招数尚未融会贯通。危急中黄蓉不顾帮规不住口出言指点——'棒回掠地施妙手横打双獒莫回头''狗急跳墙如何打快击狗臀劈狗尾'。依诀施展后打狗棒法威力奇强——霍都被逼得团团乱转再无还手余地，大厅中采声四起"
      },
      "功法": {
        "打狗棒法": {
          "掌握程度": "融会贯通（得黄蓉现场指点后已将口诀心法与三十六路招数融会印证——实战中威力大增。黄蓉句句点中窍要杨过机伶无比渐得精要）"
        }
      }
    },
    "霍都": {
      "状态": "被打狗棒法逼得险败（与杨过激斗中被竹棒逼得团团乱转再无还手之力——在天下英雄面前颜面尽失。突然喝止质疑杨过使洪七公武功——借此巧辩以图挽回败局）",
      "人物经历": {
        "第13回-03-霍都被打狗棒法逼得狼狈险败": "与杨过激斗——扇中夹掌困住杨过。不料黄蓉借出打狗棒后杨过威力倍增——被竹棒刺关元穴大吃惊愕之余改取守势。狂风暴雨般攻出二十余招后渐渐被杨过反占上风。黄蓉出言指点杨过后打狗棒法更加凌厉——空有一身武功竟被一根竹棒逼得团团乱转再无还手之力。眼见再拆数招便将落败——突然挥扇攻两招迫开杨过叫'且住'。脸如铁青森然质问杨过使的是洪七公武功非本门武学——借此巧辩以图挽回败局"
      },
