  "事件引子": "你听说完颜萍掷刀奔出后径往郊外溪边，杨过早已在溪畔等候……两人互诉身世后，忽听杨过大叫'姑姑'，发了狂般亲她的眼睛",
  "后续事件": {
    "事件名": "第10回-05-青衣女郎示警三人驰援",
    "描述": "青衣女郎现身告知陆无双已被李莫愁擒走，催促杨过设法救人"
  },
  "事件详情": "完颜萍六神无主直奔郊外小溪旁，望着淡淡星光映在溪中心乱如麻。杨过早已在溪畔等候，上前握住她双手安慰。二人并排坐在大树下，杨过为劝解她说起自己身世——父亲死得不明不白母亲一病不起，连杀父仇人是谁都不知道。完颜萍问是谁养大他，杨过卷起衣袖裤管给她看小时挨打的伤疤抓住她手让她抚摸腿上凹凸疤痕。完颜萍暗想自己虽国破家亡但父亲留下不少亲故旧部，与他身世相较自己幸运得多。默然半晌杨过忽然柔声说'妹子我求你一件事——我要亲亲你的眼睛，你放心，别的什么也不犯你'。完颜萍初以为他要求婚又怕有肌肤之亲，听他只说亲眼睛不由得松了一口气心中却又微感失望。杨过凝视她眼睛忽想起小龙女与自己最后一次分别前也是这般又娇羞又深情地望着自己——蓦地里心中灵光一闪恍然大悟：姑姑对我如此一片深情又说要做我妻子，我竟然辜负她的美意！突然大叫一声扑上去一把抱住完颜萍猛往她眼皮上亲去，口中连叫'姑姑姑姑'声音热情如沸却又极是痛楚。完颜萍闭了眼睛任他恣意领受只觉他嘴唇始终不离自己双眼。正神魂颠倒时背后一个女子声音冷冷道：'劳您两位的驾。'",
  "事件概要": "杨过与完颜萍互诉身世后结成知己，完颜萍答应不再轻生，二人情谊迅速加深。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第10回-04-杨过完颜萍溪边互诉衷肠": "在小溪边等候完颜萍，携她手并坐树下。为安慰她说起自己凄惨身世——父亲死因不明母亲病死，小时无人照顾到处流浪常被人抓住饱打，卷起衣袖裤管让她摸自己腿上的伤疤。说到伤心处自己也哭了起来。凝视她眼睛时忽将黑衣幻想为白衣、瓜子脸幻想为小龙女的容貌——痴痴瞧着她脸上流露祈求想念爱怜种种柔情。求她'我要亲亲你的眼睛'。忽然想起小龙女与自己最后一次分别前也是这般又娇羞又深情望着自己，心中灵光一闪方真正领会姑姑的柔情蜜意——懊丧万端几欲一头撞死。突然大叫扑上去紧抱完颜萍狂吻她双眼，口中不停叫'姑姑姑姑'声音热情如沸又极是痛楚。正自狂乱迷醉时背后响起青衣女郎的声音。"
      }
    },
    "完颜萍": {
      "人物经历": {
        "第10回-04-杨过完颜萍溪边互诉衷肠": "奔至郊外小溪旁望着星光映溪心神大乱。杨过现身握住她双手安慰。听杨过讲述自幼失怙流浪挨打饱受欺凌的身世——摸到他腿上凹凹凸凸的疤痕不禁心中一酸，暗想自己虽国破家亡与他相较幸运得多。杨过轻声求亲她眼睛时芳心怦怦乱跳已自意乱情迷——一双被他坚强粗厚手掌握着难以拒却。听他只说亲眼睛松了一口气心中却又微感失望。忽被他发狂般紧抱在怀中狂吻双眼，心中又惊又喜闭眼任他恣意领受温柔滋味——听他口中叫的却是'姑姑'心中正疑惑。"
      }
    },
    "程英": {
      "人物经历": {
        "第10回-04-杨过完颜萍溪边互诉衷肠": "在郊外溪边大树后现身，身穿青袍头垂双鬟。目睹杨过抱着完颜萍狂吻其眼口中大叫'姑姑'的场面，冷冷说了声'劳您两位的驾'打断二人。"
      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/河南/龙驹寨",
      "状态": "心绪激荡（溪边与完颜萍互诉身世后借亲她双眼宣泄对小龙女的刻骨相思。蓦然醒悟小龙女对自己的一片深情——懊悔无及却又无处可寻她。情绪失控狂吻完颜萍双眼被青衣女郎打断）",
      "性格": "聪明机灵，狡猾惫懒，自尊心极强且敏感叛逆。自幼失去父母，饱尝人世冷暖。得小龙女真心相待后对她敬爱赤诚却懵懂未解男女之情。在溪边因完颜萍的眼波与小龙女相似而蓦然醒悟——终于领会姑姑对自己的一往情深，懊丧欲死。重情重义，对义父欧阳锋愈久愈亲。离开古墓后仍恋红尘，但为小龙女甘愿隐居。对陆无双的感情日渐复杂，又对完颜萍生出怜惜亲近之意——皆因她眼神酷似小龙女而自欺自慰。凡事机变百出，遇强则逞强好胜决意事事胜过旁人。",
      "关系网": {
        "完颜萍": "义妹/80（溪边互诉衷肠后对她越发怜惜——借她双眼想象小龙女以解心中刻骨相思。狂吻其眼后对她更多了几分亲近与愧疚）",
        "小龙女": "师父且爱慕/100（蓦然醒悟姑姑对自己的深情后才真正领会——懊丧自己昔日的懵懂无知，恨不得一头撞死。心中发誓走遍天涯也要寻她回来，今生今世再不负她）"
      }
    },
    "完颜萍": {
      "状态": "芳心已乱（得杨过溪边安慰互诉衷肠后对他愈发亲近。被他狂吻双眼正意乱情迷时被青衣女郎打断——脸上飞红低头抚弄衣角。心中既羞且喜又微感惆怅——他口中叫的却是另一个人）"
    },
    "程英": {
      "所在位置": "大宋/河南/龙驹寨",
      "状态": "暗中随护（奉师命下山后在江湖中行走，寻机助杨过救人。在溪边撞见杨过与完颜萍亲热的尴尬场面，出言打断后彬彬有礼）"
    }
  },
  "参与人物": [
    "完颜萍",
    "杨过"
  ]
}

