{
  "事件地点": "大宋/绝情谷/水仙山庄",
  "触发条件": {
    "类型": "时间",
    "年": 1245,
    "月": 1,
    "日": 30,
    "时": 19
  },
  "事件结束时间": {
    "年": 1245,
    "月": 1,
    "日": 30,
    "时": 20
  },
  "事件引子": "武修文正要追李莫愁时，林中走出五个身穿绿衣的少女。当先一人手提花篮——正是公孙绿萼。她一听到杨过声音矜持之态立失快步上前……",
  "后续事件": {
    "事件名": "第30回-10-公孙绿萼假意骂杨过赠地图密信",
    "描述": "杨过拒绝娶公孙绿萼后携小龙女走向厅门，公孙绿萼忽然追出大骂杨过——实为暗中传递密信"
  },
  "事件详情": "公孙绿萼引众人来到大厅。裘千尺坐在厅中椅上——手足残废无法迎客。慈恩见眼前秃头皱面的丑陋老妇竟是当年娇嫩婀娜的妹子，回首前尘心中迷惘。裘千尺见杨过逾期不返只道他已毒发而死——突然见他活跳跳站在面前心下大奇。杨过道服了解毒良药花毒已消——裘千尺冷笑道'倘若真有解毒良药那天竺和尚跟姓朱的书生又巴巴赶来作甚'。杨过请放了天竺僧和朱子柳被拒。杨过心想让她兄妹相见念着亲情诸事当可善罢，微笑引导。裘千尺眼光扫过众人牢牢瞪住黄蓉咬牙道'你是黄蓉我哥哥是死在你手里的'。杨过吃了一惊。此时慈恩纵身上前叫道'三妹'，裘千尺也叫出'二哥'——二人四目交投心意登通。兄妹相认各有千言万语——慈恩问手足怎地残废，裘千尺道中了公孙止奸计。裘千尺催逼慈恩为大哥报仇杀黄蓉——慈恩眼中异光陡盛。一灯缓步上前柔声相劝'出家人怎可再起杀念'。裘千尺越逼越紧骂慈恩是贪生怕死的懦夫。郭芙忍不住喝道'我妈只是不跟你一般见识难道便怕了你这糟老太婆'。裘千尺冷笑问'你便是郭靖和黄蓉的女儿吗'——'女儿'两字未说完突然呼的一声一枚铁枣核从口中疾喷而出向郭芙面门激射。杨过时时刻刻均在留心见她口唇一动当即疾跃上前抽出郭芙腰间长剑回手急掠——当的一声呛啷一响长剑竟被铁枣核打断成两截。众人齐声惊呼黄蓉郭芙花容失色。裘千尺瞪视杨过没料到他竟敢大胆救人——冷冷道'你今日再中情花之毒刻下纵然未发决计挨不过三日。世上仅有半枚丹药能救你性命难道你不信么'。杨过经她一提不由得气馁——上前一躬到地说'裘老前辈晚辈可没得罪你什么若蒙赐予丹药终身永感大德'。裘千尺道'你应承取郭靖黄蓉首级来此我便赠药救你。岂知你非但没遵约言反而救我仇人又有何话说'。公孙绿萼眼见事急求母亲发慈悲，裘千尺却说半枚丹药是留给女婿的。",
  "事件概要": "裘千尺与慈恩兄妹相认却再起旧仇，杨过救下郭芙后受半枚丹药和婚约相逼，求药局面愈发僵死。",
  "insert": {
    "公孙绿萼": {
      "人物经历": {
        "第30回-09-公孙绿萼引众人入厅见证兄妹相认": "从林中走出引众人入大厅。听到杨过声音矜持之态立失快步上前——'杨大哥你大功告成了罢快见我妈妈去'。引见一灯大师和慈恩却不知这黑衣僧就是亲舅舅。见杨过称黄蓉为郭夫人知是母亲日夜切齿的仇人——杨过非但没杀她反而引入谷来不觉疑心大起。在大厅中目睹母亲与舅舅兄妹相认的感人场面。母亲催逼舅舅报仇时眼见事急求母亲发慈悲——被母亲以'半枚丹药留给女婿'之言羞得满脸通红"
      }
    },
    "裘千尺": {
      "人物经历": {
        "第30回-09-裘千尺与慈恩兄妹相认袭郭芙拒给解药": "在大厅中见杨过未死大惊。被杨过引导与二哥慈恩相认——兄妹数十年睽别相见之时四目交投心意登通各有千言万语。得知裘千丈已死二哥空有一身本领竟未报仇怒火中烧——不住出言相激逼慈恩杀黄蓉。郭芙出言顶撞时以枣核暗器偷袭——被杨过用剑挡住。杨过求药时冷笑道'你应承取郭靖黄蓉首级来此我便赠药救你岂知你非但没遵约言反而救我仇人'——拒绝给杨过解药。声称半枚丹药是留给女婿的令公孙绿萼又羞又急"
      }
    },
    "裘千仞": {
      "人物经历": {
        "第30回-09-慈恩与裘千尺兄妹相认": "纵身上前与分别数十年的妹子裘千尺相认——四目交投心意登通。见当年娇嫩婀娜的妹子变成秃头皱面的丑陋老妇回首前尘心中迷惘。得知妹子手足残废是中了公孙止毒计怒气难抑大叫要将公孙止碎尸万段。被妹子催逼为大哥报仇杀黄蓉——一灯相劝后低头说'师父说得是三妹这仇是不能报的'。被裘千尺骂为懦夫后心中一片混乱"
      }
    },
    "杨过": {
      "人物经历": {
        "第30回-09-杨过以剑挡枣核救郭芙求药被拒": "时时留心裘千尺——见她口唇一动当即疾跃上前抽出郭芙腰间长剑回手急掠挡开枣核。长剑被枣核打断成两截——救人之后经裘千尺一提才想到自己情花毒未解。上前一躬到地求药——'裘老前辈晚辈可没得罪你什么若蒙赐予丹药终身永感大德'。被拒绝后朗声道'我已娶龙氏为妻杨过死则死矣岂能作负义之徒'——携小龙女的手走向厅门决心自行救天竺僧"
      }
    },
    "郭芙": {
      "人物经历": {
        "第30回-09-郭芙顶撞裘千尺险遭枣核穿面": "忍耐不住出言顶撞裘千尺——'我妈只是不跟你一般见识难道便怕了你这糟老太婆你再噜苏不休姑娘可要对你不客气了'。见母亲未阻拦胆子更大。裘千尺冷笑问她是否郭靖黄蓉女儿时坦然承认。不料裘千尺'女儿'二字未说完便以铁枣核偷袭——连想躲避都没来得及想。被杨过以剑挡住逃过一劫——吓得花容失色"
      }
    },
    "黄蓉": {
      "人物经历": {
        "第30回-09-黄蓉在大厅中应对裘千尺": "进大厅后面对裘千尺的目光——被认出击杀大哥的仇人。裘千尺逼慈恩杀她时心中已盘算了好几条脱身之策。郭芙出言顶撞时本想喝阻但转念一想裘千仞正受激按捺不住女儿出来打岔可分散心神便不出声。裘千尺偷袭郭芙时花容失色——万万想不到她身不动足不抬手不扬头不晃竟会无影无踪射出如此狠辣暗器"
      }
    },
    "一灯大师": {
      "人物经历": {
        "第30回-09-一灯劝慈恩勿起杀念": "见慈恩眼中异光陡盛缓步上前柔声劝道'出家人怎可再起杀念何况你兄长之死是他自取其咎怨不得旁人'。见裘千尺越逼越紧暗自为弟子担忧——带慈恩来绝情谷本就有使其多历磨难坚其心志的深意"
      }
