617571.content:
{
  "事件地点": "大宋/绝情谷/水仙山庄",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 12,
    "日": 2,
    "时": 10
  },
  "事件结束时间": {
    "年": 1244,
    "月": 12,
    "日": 2,
    "时": 11
  },
  "事件引子": "公孙止惨呼着逃出大厅——裘千尺凛然坐在椅上冷冷的目光扫过众贺客……",
  "后续事件": {},
  "事件详情": "公孙止逃走后裘千尺凛然坐在椅上冷冰冰的目光令厅上众贺客心头发毛。杨过与小龙女见公孙止落得如此下场也是大出意料，牵手并肩往厅外走去。裘千尺突然大喝'杨过你到哪里去'——怒容满脸道'我将独生女儿许配于你怎地既不改口称我岳母又这么匆匆忙忙的便走了'。杨过愕然说虽将女儿许配于己可自己并没答应。裘千尺当众便要二人即刻成亲——'咱们武学之士也不必婆婆妈妈你们二人今日便成了亲罢'。杨过左手挽小龙女右手按剑柄郑重回绝道'晚辈心有所属实非令爱良配'。裘千尺向小龙女怒目横了一眼骂她'小狐狸精'。马光佐哈哈大笑说'这谷中的夫妻当真是一对活宝老公逼人家闺女成亲老婆也硬逼人家小子娶女'——裘千尺波的一声喷出枣核打落他三颗门牙，又两枚枣核打中其双腿穴道令他摔倒在地。公孙绿萼在大庭广众间受此羞辱再也抵受不住，拔出匕首指向胸口——'妈你再问一句女儿当场死给你看'。裘千尺再喷枣核击飞匕首插入木柱。杨过弹剑吟道'茕茕白兔东走西顾衣不如新人不如故'携小龙女转身便走。裘千尺高声道'杨过你不肯娶我女儿连性命也不要了吗'。小龙女心中一凛朗声问是否有丹药能治情花之毒。绿萼也跪下求母亲报恩——若不是杨过援手母亲尚困身石窟大难未脱。裘千尺嘿嘿冷笑后从怀中取出世间唯一一枚绝情丹——以指甲切成两半——'你不肯做我女婿那也罢了可是你须得答允为我办一件事'——取郭靖黄蓉的首级来换另外半枚丹药。杨过正因郭靖是杀父仇人大喜应允。裘千尺将半枚丹药交杨过吞下并告知情花毒性——服半枚后毒势加速十八日内必须再服另半枚否则毒发身亡。杨过与小龙女当下作别，跃出高冈翻山出谷。",
  "事件概要": "裘千尺逼婚不成，改以半枚绝情丹要挟杨过去取郭靖黄蓉首级，杨过因此背上十八日死限。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第20回-02-拒婚公孙绿萼服半枚绝情丹应允杀郭靖黄蓉": "听裘千尺当众要自己即刻娶公孙绿萼时愕然——'你虽将女儿许配于我可我没说要啊'。左手挽小龙女右手按剑柄郑重回绝——'晚辈心有所属实非令爱良配'。怕裘千尺狂怒喷枣核按剑以防。朗声吟道'茕茕白兔东走西顾衣不如新人不如故'携小龙女转身便走——当众宣告了自己对小龙女坚贞不渝的心意。听裘千尺说须取郭靖黄蓉首级时大喜——这二人正是自己的杀父仇人。将半枚绝情丹放入口中咽唾液吞下。知须在十八日内取二人首级换另半枚丹药——与小龙女快步出了水仙庄不再循来路乘舟而出翻越高山离去"
      },
      "状态": "已将裘千尺给的半枚绝情丹服下。十八日内须取郭靖黄蓉首级来换另半枚丹药否则情花毒发作更快——三十六日缩短为十八日。虽有生路但也仅十八日之期。与小龙女一同翻越高山离开绝情谷",
      "重要物品": {
        "半枚绝情丹（已服）": "裘千尺将世间唯一一枚绝情丹用指甲切成两半给的半枚——已服下。情花毒势聚在一处发作反而快了一倍——十八日后再服半枚立时解毒否则毒发身亡"
      }
    },
    "小龙女": {
      "人物经历": {
        "第20回-02-力主救杨过与杨过同拒婚离谷": "听裘千尺逼迫杨过娶公孙绿萼时心中自然不悦但未出声。当杨过吟'衣不如新人不如故'携她手离开时脸含微笑——这诗句正是对绿萼最明确的回应。听见裘千尺说有丹药治情花毒时心中一凛朗声追问——满心只盼能为杨过找到解药。听杨过应允杀郭靖黄蓉换取丹药——虽然暗自担心但知只有此路可保杨过性命。与杨过一起向裘千尺作别快步出庄翻越高山离开这个险地"
      }
    },
    "公孙绿萼": {
      "人物经历": {
        "第20回-02-当众受辱拔刀自尽反求母救杨过": "在大庭广众间被母亲先后逼婚羞得面红耳赤再也抵受不住。拔出腰间匕首指在胸口——'妈你再问一句女儿当场死给你看'——宁死不愿母亲继续逼迫杨过。被母亲喷枣核击飞匕首后心知自己的一片痴情只是单方面的。听母亲说可用丹药救杨过时顾不得女儿家仪节颜面转身跪下求母亲——'若不是杨大哥援手你尚困身石窟之中大难未脱杨大哥又没丝毫得罪你之处咱们有恩报恩你设法解了他身上之毒罢'。又大声道'女儿最恨三心两意喜新厌旧的男子这姓杨的若是舍却旧人想娶女儿女儿便是死了也决不嫁他'——裘千尺听来入耳但一转念便明白女儿用心：她是爱极了杨过只盼先救他性命再说"
      }
    },
    "马光佐": {
      "人物经历": {
        "第20回-02-直言大笑被裘千尺枣核打落门牙": "听裘千尺逼婚哈哈大笑——'这谷中的夫妻当真是一对活宝老公逼人家闺女成亲老婆也硬逼人家小子娶女别人不要成不成'。裘千尺冷冷说'不成'后波的一响枣核射向眉心打落三颗门牙。大怒虎吼扑去又被两枚枣核打中双腿环跳阳关两穴摔倒在地爬不起来。被杨过扶起解穴后倒也极肯服输——'老太婆你本事比我大老马不敢得罪你啦'吐出三枚门牙满嘴鲜血"
      }
    }
  },
  "update": {
    "杨过": {
