  },
  "事件结束时间": {
    "年": 1244,
    "月": 10,
    "日": 24,
    "时": 19
  },
  "事件引子": "中午饭罢，丐帮帮众在陆家庄外林中聚会。新旧帮主交替是丐帮最隆重的庆典，各路英雄也均受邀观礼...",
  "后续事件": {
    "事件名": "第12回-06-金轮法王率众闯入争盟主",
    "描述": "到得晚间，陆家庄内内外外挂灯结彩开英雄大宴。正热闹间，全真四道去而复返报讯有敌人前来捣乱，随即金轮法王率众闯入"
  },
  "事件详情": "中午饭罢，丐帮帮众在陆家庄外林中举行新旧帮主交替大典。十余年来鲁有脚一直代黄蓉处理帮务，公平正直敢作敢为，污衣净衣两派齐都心悦诚服。黄蓉按帮规宣布后将打狗棒交与鲁有脚，众弟子一齐向他唾吐，唾得满头满脸都是痰涎，帮主接任之礼告成。杨过正欲禀报洪七公逝世讯息，忽见一个老年乞丐跃上大石，传达洪老帮主之令。群丐闻讯齐声欢呼声振天地，有的甚至泪流满面。老丐说半年前在广南东路遇见洪老帮主，他身强体健要去查察藏边五丑的恶行。又说洪老帮主命帮众心存忠义誓死杀敌力御外侮，要牢牢记着'忠义'二字。杨过见群丐正义凛然大有所感，暗自庆幸未在大会上说出洪七公死讯——否则百口莫辩。到得晚间陆家庄开了二百余席，天下英雄倒有大半赴宴。黄蓉替杨过安排座次在她身旁，郭芙与武氏兄弟反而坐得甚远。郭芙越想越怕——以为母亲已依从了父亲要将自己许配杨过，既担心又气愤。",
  "事件概要": "鲁有脚正式接任丐帮帮主，英雄大宴随之开场，中原群雄开始共商抗敌大事。",
  "insert": {
    "鲁有脚": {
      "人物经历": {
