{
  "事件地点": "大宋/晋南/倒马坪",
  "触发条件": {
    "类型": "时间",
    "年": 1259,
    "月": 10,
    "日": 8,
    "时": 0
  },
  "事件结束时间": {
    "年": 1259,
    "月": 10,
    "日": 8,
    "时": 1
  },
  "事件引子": "你听说万兽山庄史氏兄弟与西山一窟鬼在雪地中激斗不休，群兽环伺——就在危急关头头顶传来一声清啸。",
  "后续事件": {
    "事件名": "第34回-01",
    "描述": "神雕侠杨过现身之后，西山一窟鬼与万兽山庄的纷争以及郭襄与杨过的初遇仍在继续。"
  },
  "事件详情": "雪地之中十人分四团厮杀：长须鬼钢杖斗史伯威虎头双钩旗鼓相当；史仲猛以烂银点钢管以一敌三——催命鬼地堂刀、丧门鬼链子枪、讨债鬼铁帐簿；吊死鬼长索圈圈变化与大力神史季强青铜杵相斗虽力弱却仗兵刃奇特周旋；史孟捷判官双笔招数精奇以一敌二——大头鬼八角铜锤加俏鬼提刀。笑脸鬼撒毒雾迷倒史季强被吊死鬼长索套住双腿。病奄奄的青甲狮王史叔刚扶病起身，左手一拍右手一托将吊死鬼和笑脸鬼震得踉跄跃开，俯身解穴拉断长索救出四弟。史伯威纵声长啸群兽齐吼扑向十鬼。郭襄见三头雄狮围攻大头鬼情急之下除下皮帽戴在大头鬼头上——群兽戴皮帽者不咬——大头鬼得救。四头花豹围住郭襄却只挨擦亲热竟不抓咬——原来她幼时吃母豹乳汁长大体气被豹类引为同类，又惊又喜搂住豹颈。西山一窟鬼人人受伤命在顷刻，十人却互掷皮帽争相舍己相救——竟是谁也不肯独生。猛听得头顶清啸冷冷，神雕侠杨过坐在大树横干之上旁蹲神雕，身穿灰布长袍右袖束在腰中断了一臂。郭襄初见其相貌——脸色焦黄木僵枯槁如僵尸——不禁大失所望，但再望时却见他眸子精光四射英气逼人，那闪电般的眼光扫过她脸时略一停留似乎微感奇怪。郭襄心口一阵发热不由自主晕生双颊低下头来，隐隐约约觉得这神雕侠倒也不怎么丑陋了。",
  "事件概要": "杨过现身压住兽群与乱斗，郭襄终于亲见神雕侠本人，也由此正式踏入与杨过及万兽山庄诸人的交集。",
  "insert": {
    "催命鬼": {
      "人物经历": {
        "第33回-08-催命鬼参与万兽山庄大战": "在万兽山庄外雪地中参与大战——使地堂刀与丧门鬼、讨债鬼合斗史仲猛。被群兽围攻后奋力杀毙数头恶兽仍不免受伤。"
      }
    },
    "讨债鬼": {
      "人物经历": {
        "第33回-08-讨债鬼持铁帐簿参战": "在万兽山庄外雪地中跃上相助催命鬼与丧门鬼——以精钢铸成的铁帐簿（五张可翻动铁片）与史仲猛相斗，兵刃形状奇特相互撞击当当作响。被群兽围攻受伤。"
      }
    },
    "俏鬼": {
      "人物经历": {
        "第33回-08-俏鬼提刀助大头鬼斗史孟捷": "见大头鬼有些招架不住史孟捷的判官双笔，提刀上前相助。一刚一柔相辅相成，阴声阴气说笑分散敌人心神。被群兽围攻受伤，接过大头鬼掷来的皮帽后立即掷给长须鬼让他先逃。"
      }
    },
    "笑脸鬼": {
      "人物经历": {
        "第33回-08-笑脸鬼毒倒史季强后群兽围攻中舍己": "扑向史季强以双鞭迎战被青铜杵震断双鞭，一个打滚翻出抓毒粉扬手撒出淡红薄雾毒倒史季强。被史叔刚掌力震退后不敢近身。群兽围攻时五条恶狼缠住他——脸上仍带笑意口中大声咒骂。长须鬼将皮帽抛在他头上保命却腾不出手掷还。"
      }
    },
    "吊死鬼": {
