688198.content:
{
  "事件地点": "大宋/终南山/潼关道",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 9,
    "日": 10,
    "时": 10
  },
  "事件结束时间": {
    "年": 1244,
    "月": 9,
    "日": 10,
    "时": 11
  },
  "事件引子": "你听说潼关道上赤练仙子李莫愁吃了大亏——被一个小道士倒立着夺去了她仗以扬威十余年的拂尘……",
  "后续事件": {
    "事件名": "第9回-06-智取耶律晋乔装侍从",
    "描述": "杨过与陆无双纵马狂奔至黄昏，前方村庄外系着百余匹蒙古战马"
  },
  "事件详情": "杨过回返将长剑双手捧到洪凌波面前还剑。正欲转身，李莫愁忽道\"且慢\"——她见这小道士武艺了得，想趁其功力未及自己便随手除掉。杨过将长剑又往前递让洪凌波抓住剑柄，李莫愁没了兵刃交手之机。李莫愁问他是全真七子谁的门下，杨过竟答：\"我是王重阳的弟子。\"李莫愁心道此人不知天高地厚，重阳真人去世时他还未出生。杨过见李莫愁眉间微蹙正自沉吟，便即编造谎言——说看到那跛脚姑娘被丐帮擒走，还从她怀里掏出一本书来，又给化子打了耳括子。李莫愁听得五毒秘传落入丐帮手中不禁微现焦急。此时一队蒙古骑兵拥着锦袍官员经过，李莫愁不欲多生事端。她拂前尘土时陆无双吓得心跳欲裂，只觉这拂尘随时会落到自己头上。杨过继续编谎说几个化子掳了姑娘向北方去了。李莫愁点头道谢，自称赤练仙子，杨过当面夸她美貌如天仙下凡。李莫愁心中一乐，对洪凌波说再借剑给他——洪凌波拔剑时只听擦的一响，剑柄中剑刃早已在还剑时被杨过暗中捏断。李莫愁脸上变色。杨过提出空手接她拂尘三招，李莫愁一口答应。黄影晃动间李莫愁使出\"无孔不入\"点他周身大穴，杨过一个筋斗头下脚上运起欧阳锋所授逆行经脉之法，全身穴道尽数封闭。李莫愁明明点中他多处穴道居然仍能还击，心中大奇。第二招\"无所不至\"攻他偏门穴道又被倒立法避过。第三招\"无所不为\"专打眼睛咽喉小腹等柔软处——却因杨过头下脚上全打在了脚背小腿和大腿上，毫无功效。杨过趁李莫愁一呆，张口咬住拂尘尘尾翻身站起将拂尘夺了过来。当年华山论剑欧阳锋一口咬中黄药师手指的功夫在此重现。杨过脸上泥沙在急转中剥落露出本来面目，李莫愁失声叫道：\"咦，是你！你师父呢？\"洪凌波也认出陆无双。杨过左足一点飞身上了李莫愁花驴，一枚玉蜂针射进洪凌波驴子脑袋，随即倒转拂尘柄将花驴打得脑浆迸裂，大叫：\"媳妇儿，快随你汉子走！\"二人纵马疾驰，李莫愁不敢过分逼近只施展小擒拿手夺回拂尘。洪凌波驴子发狂冲咬李莫愁后四腿一软倒毙。但此时杨陆二人早已奔出半里之外再也追赶不上了。",
  "事件概要": "杨过逆行经脉夺下拂尘并再度逃脱，还借假消息把五毒秘传的风波引向别处。",
  "insert": {
    "杨过": {
      "重要物品": {
        "玉蜂针": "古墓派暗器，小龙女所授，以细如发丝的玉针淬以蜂毒制成，射入驴脑可使其发狂倒毙"
      },
      "人物经历": {
        "第9回-05-逆行经脉夺拂尘逃逸": "还剑时暗使手脚捏断剑刃。被李莫愁叫住后自称王重阳弟子——不肯比杀死孙婆婆的郝大通矮一辈。编造谎言说陆无双被丐帮擒走、五毒秘传被夺，将李莫愁骗得微现焦急。当李莫愁自称赤练仙子时当面夸她美貌如天仙下凡令她心中一乐。李莫愁要动手时约定空手接她三招。第一招'无孔不入'使来时一个筋斗头下脚上运起欧阳锋所授逆行经脉之法封闭全身穴道——明明被点中多处穴道仍能还击。第二招'无所不至'仍以倒立法避过。第三招'无所不为'专打柔软处却因头下脚上全打错了地方。趁李莫愁惊呆之时张口咬住拂尘尘尾夺下她仗以扬威十余年的兵刃——用的是当年欧阳锋咬黄药师手指的奇功。脸上泥沙剥落露了本来面目被李莫愁认出。飞身上驴射出玉蜂针杀洪凌波驴子，又倒转拂尘柄打死李莫愁花驴令其不能再追。大叫'媳妇儿快随你汉子走'与陆无双纵马狂奔而去。"
      }
    },
    "陆无双": {
      "人物经历": {
        "第9回-05-逆行经脉夺拂尘逃逸": "在旁观杨过与师父交手，见他谎称王重阳弟子当面夸师父美貌，心中又是好笑又是担忧。蒙古官兵经过时师父拂尘每动一下她心就剧跳一下——只觉这拂尘随时会落到自己头上脑浆迸裂。见杨过头下脚上以怪异身法破解师父'三无三不手'，又一口咬住拂尘夺下师父兵刃，惊喜交集。被洪凌波认出后大惊失色。杨过杀驴大叫一起逃命时立刻纵马疾驰，奔出半里外回头见师父不再追来才松了一口气。"
      }
    },
    "李莫愁": {
      "人物经历": {
        "第9回-05-逆行经脉夺拂尘逃逸": "见小道士还剑时已捏断剑刃心中暗惊。听杨过自称王重阳弟子心中认定他在捣鬼。杨过编造陆无双被丐帮擒走的谎言令她微现焦急——五毒秘传落入他人手中便如赤练蛇被拔毒牙。蒙古兵马经过时让在道旁。答应与杨过空手过三招，使出平生最得意的'三无三不手'——无孔不入、无所不至、无所不为——却万料不到杨过头下脚上逆行经脉，三招毒招全无效力。冷不防被他张口咬住拂尘尘尾夺去兵刃，这一惊非同小可——她一生见过不少大阵大仗，却从未见过如此不可思议的功夫。待认出杨过真面目更加震惊。花驴被杨过打死，洪凌波驴子也倒毙，无法再追眼睁睁看着二人逃走。虽夺回拂尘却已大失面子。"
      }
    },
    "洪凌波": {
      "人物经历": {
        "第9回-05-逆行经脉夺拂尘逃逸": "杨过双手捧剑还来时伸手接过，拔剑时擦的一声只拔出个剑柄——这才醒悟杨过还剑时暗中将剑刃捏断。被师父叫再借剑时已无剑可借。在旁观师父与小道士过三招看得心惊肉跳。杨过露出真面目时认出他就是古墓中交过手的杨过，又认出陆无双叫道'师父是师妹啊'。驴子被杨过射入玉蜂针突然发狂冲向师父张嘴大咬，用力勒缰拉得驴子满口是血，最终驴子四腿一软翻身倒毙。跃起身来时杨陆二人早已奔远追不上了。"
      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/终南山/潼关道",
      "状态": "逃亡中（以逆行经脉倒立法大破李莫愁三无三不手夺其拂尘，身份暴露后射玉蜂针杀二驴纵马狂奔逃脱。自得于戏弄赤练仙子又全身而退）",
      "功法": {
        "逆行经脉之法": {
          "掌握程度": "初窥门径（已在实战中以头下脚上之法成功破解李莫愁的'三无三不手'夺其拂尘，颇具奇效）"
        }
      },
      "关系网": {
        "李莫愁": "敌对/10（当面夺下她拂尘杀她花驴，从此与她正面为敌）",
        "洪凌波": "敌对/40（借剑捏断、射杀驴子，洪凌波也认出了他）"
      }
    },
    "陆无双": {
      "状态": "逃亡中（身份暴露被洪凌波认出，与杨过策马狂奔逃脱师父追赶。胸口断骨被颠得疼痛难当）",
      "关系网": {
        "李莫愁": "仇人/5（身份彻底暴露，师父势必将以更严厉手段追捕）",
        "洪凌波": "师姊/20（被洪凌波当面认出，彻底断了回头的可能）"
      }
    },
    "李莫愁": {
      "状态": "又惊又怒（被杨过以怪异功夫夺下拂尘、杀了两头花驴逃走。当面被戏弄羞辱，对杨过恨之入骨却对他的怪异功夫心存忌惮）",
      "关系网": {
        "杨过": "敌对/-70（被这小贼道当面夺去拂尘、杀驴逃走、戏弄羞辱，必杀之而后快）",
        "陆无双": "叛徒/-80（陆无双与杨过同谋骗师、当面被认出仍跟随逃走，必严惩不贷）"
      }
    },
    "洪凌波": {
      "状态": "又惊又怒（被杨过捏断剑刃戏弄、驴子被杀，追上屋顶的本事也没了）。师父的功夫竟也制不住这小贼。",
      "关系网": {
        "杨过": "仇敌/-80（被当面捏断剑刃戏耍、驴子被玉蜂针射杀，羞愤难当）"
      }
    }
  },
