      },
      "功法": {
        "天罗地网势": {
          "掌握程度": "融会贯通（实战中以天罗地网势抓起数十柄长剑此上彼落掷出扰乱敌人——活的麻雀尚能拦住数十柄长剑随接随抛在她自是浑若无事。当年传授杨过武功时的掌法今日化为破敌奇策）"
        }
      }
    },
    "赵志敬": {
      "人物经历": {
        "第26回-02-赵志敬连中三剑躲藏无门": "小龙女双剑拦住前后去路。躲在尹克西身后仍被小龙女一剑绕身刺中肩头。逃到潇湘子身旁又被小龙女抽空刺伤手腕。连中三剑自知尹克西潇湘子皆不足倚恃。潇湘子挥掌推他跌出数丈拿桩站住。趁小龙女被三大高手围攻之际闪闪缩缩正要逃到神像之后"
      }
    },
    "尹克西": {
      "人物经历": {
        "第26回-02-尹克西出手斗小龙女金鞭被破手腕受伤": "挥金龙鞭格开小龙女长剑——成为第一个接住她快剑之人。试图套交情说'跟这些贼道生气没的损折了姑娘贵手'。却发现无力护住赵志敬——小龙女竟能隔人伤敌。与潇湘子尼摩星合围小龙女——使'黄沙万里鞭法'反复四次。出主意三人踏上半步逐步挤拢缩小圈子。不料小龙女掷剑乱攻三柄剑缠住其软鞭，小龙女乘隙刺伤其手腕，金龙软鞭呛啷落地——包围圈子立时破裂脸带愧色"
      },
      "功法": {
        "黄沙万里鞭法": {
          "掌握程度": "融会贯通（在三清殿反复使了四次——舞成一团黄光护住身前滴水不漏。但终被小龙女以掷剑乱攻破了鞭网手腕中剑金鞭落地）"
        }
      }
    },
    "尼摩星": {
      "人物经历": {
        "第26回-02-尼摩星参与围攻小龙女受伤叫阵": "与潇湘子尹克西一同围攻小龙女——双腿断折以拐杖撑持舞动铁蛇封住身前。口中恶言'你这小妖女有什么本事一塌胡涂施展出来'——与旁人不同存心要和小龙女拼个死活（因双腿实受杨过与李莫愁之赐）。第一个沉不住气虎吼一声挥铁蛇疾冲被小龙女刺伤左肩。小龙女破围后与潇湘子尹克西一起自愧——'这怪不得尹兄'。听到山后兵刃撞击声便率先寻声追下"
