      "人物经历": {
        "第26回-02-潇湘子出手合围小龙女被掷剑阵逼得惶急": "见小龙女剑法后哼了一声说'龙姑娘剑法不差我也得领教领教'。挥掌将赵志敬推跌数丈哭丧棒同时击出。与尼摩星尹克西从三方围攻——生平罕有地一出手便取守势——先求己之不可胜以求敌之可胜。小龙女掷剑乱攻后哭丧棒舞得虽快但只见惶急。小龙女破围后一时还不能便收兵刃直待数十把长剑一一落地才住手——都有死里逃生之感"
      }
    },
    "马光佐": {
      "人物经历": {
        "第26回-02-马光佐出言讥嘲三大高手围攻小龙女": "与杨过小龙女一直交好——见潇湘子尼摩星尹克西三人围攻小龙女心中大不以为然。高声叫道'不要脸啊真正不要脸三个武林大宗师围攻一个小姑娘'。潇湘子等装作没听到——均想'浑大个儿咱们同来办事你却反助外人回头定要教你吃点苦头'"
      }
    },
    "尹志平": {
      "人物经历": {
        "第26回-02-尹志平被缚观小龙女大战三高手": "与众全真忠义弟子被蒙古武士牵退靠向殿壁——均知眼前四人相斗非同小可。亲见小龙女以一敌三智勇破围——心中愧疚与怜惜交织"
      }
    }
  },
  "update": {
    "小龙女": {
      "状态": "以掷剑之法大破三大高手铜墙铁壁般的合围——击伤尹克西手腕令其金鞭落地破围而出。提气直奔殿后追赶赵志敬",
      "所在位置": "大宋/终南山/重阳宫"
    },
    "赵志敬": {
      "状态": "被小龙女连刺三剑——左肩右肩手腕皆伤鲜血涔涔而下。躲无可躲正要逃向神像之后",
      "所在位置": "大宋/终南山/重阳宫"
