    "时": 18
  },
  "事件结束时间": {
    "年": 1244,
    "月": 11,
    "日": 28,
    "时": 19
  },
  "事件引子": "公孙止左手金刀右手黑剑——两般兵刃一刚一柔性子截然相反。黑剑划圈逼敌笼罩全身要害，金刀配合猛劈令敌无可闪避。杨过初遇这等奇门兵器登时手忙脚乱。",
  "后续事件": {
    "事件名": "第18回-07-小龙女当众拒婚法王激将三人入剑室",
    "描述": "杨过弃兵刃空手让公孙止杀。小龙女当众宣布决意与杨过结成夫妻终身厮守——法王出言激将迫公孙止同意三人比剑。"
  },
  "事件详情": "公孙止黑剑颤动当胸刺去剑尖却在他身前乱转圈子——剑圈越划越大自前胸扩及小腹再到头颈，杨过自颈至腹所有要害尽在剑尖笼罩之下。金轮法王等生平从未见过这般划圈逼敌的剑法无不大为骇异。杨过连避十次剑圈无法还手，当下窜跃向左抖动金铃索击敌左目。公孙止侧头避过挺剑反击。杨过铃索缠住他右腿刚要收力拉扯，谷主黑剑划下嗤的一声轻响金铃索从中断绝。锯齿刀随即劈来，杨过抢起钢杖挡架，杖刀相交二人手臂都震得隐隐发麻。公孙止左刀横斫右剑斜刺——刀法刚猛剑招轻灵，两般兵刃性子截然相反一人同使刀剑分得清清楚楚。杨过运钢杖使打狗棒法封字诀守住门户，但笨重钢杖不及竹棒灵便，被公孙止寻到破绽喀的一声钢杖又给黑剑割断。杨过改用半截钢杖反而灵动。公孙止一刀当头直砍看似呆滞却被黑剑剑圈笼罩了杨过全身令人绝无闪避余地。刀杖数度相交杨过双臂酸麻虎口震出血来。公孙止黑剑倏地刺杨过小腹，掌心虽被手套护住但黑剑弯弯绕过来剑尖正中他下臂鲜血迸出。接着肩头又中袍子上鲜血斑斑。杨过将半截钢杖一掷，除下掌套，拾起割断的金铃索掷给小龙女，双手一拍弹了弹灰尘也不理伤口鲜血汩汩流出，笑道'我空手来你谷中岂有为敌之意你要杀便杀何必多言'。",
  "事件概要": "阴阳双刃逼得杨过遍体受伤仍不屈服，小龙女也因此下定与他共生死的决心。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第18回-06-杨过以钢杖接战阴阳双刃受伤不屈": "面对公孙止一刚一柔相济而攻的阴阳双刃登时手忙脚乱。金铃索被黑剑割断、钢杖被黑剑削断。虽改用半截钢杖勉强支撑但在阴阳双刃合击下左支右绌。虎口震出血、下臂被黑剑刺伤、肩头又中剑——三处伤口鲜血汩汩流出。最终将半截钢杖掷地除下掌套交还金铃索——以空手面对公孙止说你空手来谷岂有为敌之意你要杀便杀。气度闲适面目俊秀虽多处受伤依然谈笑自如行若无事——令公孙止自惭形秽。"
      },
      "关系网": {
        "公孙止": "仇敌/誓死对抗（屡次被阴阳双刃所伤已打定主意——我既然打他不过任他刺死便了。看着小龙女而死那也快活得很。和姑姑心意相通早把身外之事尽数忘了）"
      }
    },
    "公孙止": {
      "人物经历": {
        "第18回-07-阴阳双刃大显威力重伤杨过": "施展金刀黑剑阴阳双刃攻向杨过——先以黑剑划圈逼敌令其无从闪避，再以金刀猛劈配合剑圈合击。此套阴阳倒乱刃法刚柔相济阴阳相辅——刀法刚猛剑招轻灵，双手兵刃越使越急分得清清楚楚。黑剑割断金铃索、削断钢杖、刺伤杨过下臂——大占上风。但见杨过气度闲适谈笑自若竟自惭形秽心想此人非我所及"
      }
    },
    "金轮法王": {
      "人物经历": {
        "第18回-05-观阴阳双刃暗暗称奇": "与尹克西、潇湘子、尼摩星在一旁瞧着公孙止阴阳双刃越使越急极尽变化之能事，均想'这谷主的刀剑实是凌厉凶狠已极，也亏得这小子机变百出竟然躲得过这许多恶招'"
      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/绝情谷/大石屋",
      "状态": "阴阳双刃下多处受伤——虎口震裂、下臂被刺、肩头中剑鲜血斑斑。弃兵刃除手套双手一拍——'我空手来你谷中岂有为敌之意你要杀便杀何必多言'。坦然面对死亡只回头望着小龙女——'我瞧着姑姑而死那也快活得很'。早把身外之事尽数忘了只痴痴与小龙女四目相投",
      "重要物品": {
        "金丝手套": "已除下交还小龙女。在绝情谷中先破刀网阵后挡黑剑——虽被黑剑弯刃刺伤下臂但掌套本身刀枪不入"
      }
    },
    "小龙女": {
      "状态": "见杨过多处受伤鲜血直流心中疼惜不已。杨过弃兵刃空手等死时她脸带甜笑一步步向杨过走近四目相投——二人心意相通早把身外之事尽数忘了。对公孙止的黑剑竟不瞧一眼——早已将生死置之度外。",
      "所在位置": "大宋/绝情谷/大石屋"
    },
    "公孙止": {
      "所在位置": "大宋/绝情谷/大石屋",
      "状态": "以阴阳双刃重伤杨过后见其气度闲适谈笑自若——自惭形秽心想此人非我所及。黑剑剑尖已抵杨过胸口只需臂力微增便透胸而入——但见二人痴痴互望心意相通小龙女也浑然不怕。醋意难平——心道此时杀了这小子柳妹立时要殉情而死。改为计划逼迫小龙女成婚后再杀杨过"
    }
  },
