    },
    "潇湘子": {
      "状态": "在宜城酒楼被杨过黄药师掌力来回推送如皮球——最终摔在楼板晕了过去。十余年来功力大进自知仍非杨过敌手"
    },
    "尹克西": {
      "状态": "在宜城酒楼被杨过饶过耳光却被掌力裹得晕头转向——摔在楼板晕了过去"
    },
    "黑脸汉子": {
      "所在位置": "大宋/宜城/酒楼",
      "状态": "在宜城酒楼挑衅杨过反被扇耳光——又被裹在掌风之中摔晕楼板"
    }
  },
