  "事件引子": "你听说活死人墓中，小龙女带师姊李莫愁进了师父灵柩所在的石棺灵室……",
  "后续事件": {
    "事件名": "第7回-03-杨过小龙女互诉衷肠立生死之誓",
    "描述": "小龙女隔开李莫愁后心情激动，与杨过到孙婆婆房中互诉衷肠。"
  },
  "事件详情": "李莫愁师徒正在四周找寻机关焦急万状，突见杨过小龙女重又现身，喜出望外，李莫愁身形一晃抢到二人身后先挡退路。小龙女冷冷说要带师姊去拜见师父灵柩，李莫愁迟疑不决恐中机关，小龙女冷笑径向门口走去，言语举止自有一股威仪令人违抗不得，李莫愁师徒步步提防跟随在后。进入灵室后，李莫愁念及先师教养之恩心中微觉伤感，但随即想起师父偏心哀戚化为愤怒，竟不向灵柩磕拜。小龙女淡然指向两具空石棺，说一具给李莫愁一具给自己，任她挑选。李莫愁大怒挥掌击向小龙女胸前，小龙女竟不还手，李莫愁掌缘离胸数寸硬生生收回。小龙女心平气和告知墓门断龙石已下。李莫愁脸色惨白，她虽不尽晓墓中机关却知断龙石是最厉害的闭塞杀着，颤声问是否另有出去法子。小龙女淡然道断龙石一闭墓门再不能开，让李莫愁尽管去看玉女心经，要杀尽管下手，但想生离古墓是不成的。李莫愁抓住小龙女胸口的手慢慢松开，念头一转要先杀师徒俩，挥掌击向面门。杨过闪身挡在小龙女身前朗声道先杀我。李莫愁手掌下沉到小龙女胸口留劲不发，抢下杨过腰间长剑指住他咽喉逼问谁死。杨过只是朝小龙女一笑，二人早把生死置之度外。李莫愁长叹一声道出古墓派门规：若有男子心甘情愿为小龙女而死誓言即破可下山。她疾刺杨过，小龙女挥出十余枚玉蜂针逼退师姊，拉杨过奔出灵室按机括落下石门将四人隔开。",
  "事件概要": "李莫愁确认断龙石已下后杀意尽显，古墓内的师门相争正式变成不死不休的绝境。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第7回-02-李莫愁见石棺知断龙石惊怒下杀手": "随小龙女至灵室见李莫愁对师父灵柩不磕拜。李莫愁知断龙石已下惊怒中对小龙女下杀手，杨过闪身挡在师父身前朗声道先杀我，被李莫愁以长剑指住咽喉逼问谁死，杨过只是朝小龙女一笑早将生死置之度外。"
      }
    },
    "小龙女": {
      "人物经历": {
        "第7回-02-李莫愁见石棺知断龙石惊怒下杀手": "带李莫愁师徒至灵室拜见师父灵柩，让李莫愁自选石棺。告知断龙石已下无路可出。李莫愁下杀手时竟不还手，被杨过舍命相护。李莫愁道破古墓派门规誓言已破，疾刺杨过时小龙女挥出玉蜂针救人，拉杨过奔出灵室以石门隔开四人。"
      }
    },
    "李莫愁": {
      "人物经历": {
        "第7回-02-李莫愁见石棺知断龙石惊怒下杀手": "见二人重又现身喜出望外抢挡退路。被带入灵室见师父灵柩初时微觉伤感随即化为愤怒竟不磕拜。得知断龙石已下脸色惨白，惊惶中先要杀师徒俩，却被杨过舍命护师所感。道出古墓派门规——若有男子心甘情愿为小龙女而死誓言即破。对杨过下杀手时被小龙女以玉蜂针逼退。"
      }
    },
    "洪凌波": {
      "人物经历": {
