  "事件引子": "你听说豺狼谷斗罢，那牧童竟赖上了白衣少女，死活要跟着她走……",
  "后续事件": {
    "事件名": "第8回-05-石屋夜戏陆无双杀杨过反被点穴",
    "描述": "杨过跟着陆无双夜宿荒郊石屋，烤了獐腿充饥。夜深后陆无双心起杀意。"
  },
  "事件详情": "五敌逃走后陆无双心中狐疑，四下察看不见人影。见杨过哭丧着脸坐在地上叫苦说牛儿发疯，问为何叫苦，杨过说牛撞烂毛皮回去主人家定要打死他。陆无双掷下两锭银子，杨过却摇头不拾。陆无双恼了转身便走，杨过见她又发怒——那扬眉动唇的嗔怒模样依稀便是小龙女——胸头热血上涌决意要跟着她，伸手抱住她右腿大叫你不能走。陆无双拔刀要砍，杨过料她不会真砍却不料她出手狠辣竟真砍向他头顶，忙打个滚避开。此后陆无双前行他便远远跟随，追来便逃停下便停，二人追追停停天色渐晚。途中路过市集时杨过抱住她腿大哭大叫她是我媳妇儿我媳妇儿不要我还打我，惹得围观群众大乱。陆无双一时挣脱不得只得哄他说不打了，二人奔出市集。她叫杨过去买馒头杨过怕她趁机溜走只是摇头。天色更加黑了，道旁有座破旧石屋二人便进去歇息。杨过在屋外生起火堆烤起黄獐腿肉，陆无双闻到肉香走出来，二人对坐而食。杨过问她名字，她初不肯说，被杨过激将道你也叫傻蛋，她怒道我姓陆——这才道出姓名。杨过借着火光痴痴望着她的怒色，心下思念小龙女。陆无双已决意半夜杀他便回石屋中睡下。",
  "事件概要": "杨过以痴傻之态缠上陆无双同行，二人自此结伴上路，这段同行关系正式确立。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第8回-04-杨过装傻痴缠陆无双同行": "见陆无双发怒神情与小龙女极为相似，胸头热血上涌决意跟着她。装傻到底——躺地大叫胸口疼、在市集抱住陆无双腿大叫媳妇儿打我、被撞后假意闭血脸色惨白。陆无双几番追打杀他都因他不按常理出牌而失败。路上她叫他去买馒头他怕她溜走只是摇头。天黑后二人在破旧石屋落脚，杨过生火烤黄獐腿肉与她分食。借火光痴痴望着她怒气勃勃的面容以解对小龙女的思念。激问她名字得知她姓陆。"
      }
    },
    "陆无双": {
      "人物经历": {
        "第8回-04-杨过装傻痴缠陆无双同行": "被一个肮脏邋遢的牧童死缠住不放。无论轻功急奔、拔刀要砍、乘牛甩脱、肘撞胸口，种种办法都甩不脱这小傻蛋。在市集上被杨过抱住腿大叫媳妇儿打老公引来众人围观劝解。天黑后被迫与杨过在破旧石屋歇宿，吃了杨过烤的黄獐腿肉。被问起名字时不想说出——只因幼时被掳走后改名换姓惯了——却被杨过激将法一激说出姓陆。暗中决意半夜趁杨过睡熟时一刀砍死他。",
        "幼时断腿": "当日在嘉兴南湖与表姊程英、武氏兄弟采莲时摔断了腿。武三娘为她接续断骨时洪凌波奉师命来袭，接骨不甚妥善，伤愈后左足短了寸许，行走时略有跛态成为终身憾事。",
        "被李莫愁掳走": "李莫愁杀了她父母婢仆后将她掳去。只因见到她颈中所系锦帕记起陆展元昔日之情，迟迟不忍下杀手。陆无双聪明精乖，知道落在这女魔头手中生死系于一线，一开始便曲意迎合处处讨好，竟奉承得杀人不眨眼的赤练仙子加害之意日渐淡了。李莫愁有时记起当年恨事将她叫来折辱打骂，她便故意装得蓬头垢面一跷一拐。",
        "拜入李莫愁门下": "将父母之仇暗藏心中丝毫不露。李莫愁与洪凌波练武时她就在旁递剑传巾斟茶送果十分殷勤。心中暗记武功偷练。后来洪凌波趁师父心情好代为求情，陆无双也拜入李莫愁门下做了徒弟。李莫愁对她总是心存疑忌，别说最上乘武功就是第二流功夫也不肯传授。倒是洪凌波见她可怜暗中常加点拨。",
        "盗五毒秘传私逃": "趁李莫愁与洪凌波先后赴活死人墓盗《玉女心经》长久不归，决意逃离魔窟回江南探访父母生死下落。临走还盗走李莫愁的《五毒秘传》——记载诸般毒药和解药的抄本。最恨别人瞧她跛足，客店中两个道人向她跛足多看几眼便出言斥责，动起手来削了两个道人耳朵才有豺狼谷之约。"
      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/终南山/潼关道破石屋",
      "状态": "痴迷（痴痴望着陆无双发怒的嗔态以慰对小龙女的思念，望梅止渴画饼充饥）",
      "关系网": {
        "陆无双": "初识（被她发怒神情吸引引为小龙女替代）/-5"
