      "重要物品": {
        "锦帕(半块)": "李莫愁赠陆展元的定情之物，白缎绣红花绿叶，已被撕成两半，陆无双得半块，系于颈中——正是这块锦帕让李莫愁记起陆展元之情迟迟不忍下杀手",
        "五毒秘传": "从李莫愁处盗走的抄本，记载诸般毒药和解药的药性制法。李莫愁因此大为震怒带洪凌波连日连夜追赶"
      },
      "关系网": {
        "杨过": "厌憎（傻蛋牧童纠缠不休令人烦躁杀又杀不掉）/-40",
        "李莫愁": "仇人/10（曲意逢迎忍辱求生，暗藏父母血仇不敢稍露）",
        "洪凌波": "师姊/50（洪凌波对她尚可，曾代为求情并暗中点拨武功）"
      }
    }
  },
