791991.content:
{
  "事件地点": "大宋/绝情谷/水仙山庄",
  "触发条件": {
    "类型": "时间",
    "年": 1245,
    "月": 2,
    "日": 1,
    "时": 12
  },
  "事件结束时间": {
    "年": 1245,
    "月": 2,
    "日": 1,
    "时": 13
  },
  "事件引子": "大厅中一灯盘膝坐于厅心口宣佛号，慈恩绕圈疾行虎吼连连。铁链已断手铐碰击铮铮有声。裘千尺居中而坐脸色铁青——众人皆知一场大风暴即将来临。",
  "后续事件": {
    "事件名": "第31回-04-裘千尺封锁大厅公孙绿萼偷听杨龙对话万念俱灰",
    "描述": "慈恩飘然离去后裘千尺以渔网阵封锁大厅退回内堂。而杨过与小龙女正在谷中携手缓行观赏夕阳，对大厅中这场惊心动魄的变故浑然不觉。"
  },
  "事件详情": "一灯大师盘膝坐于厅心口宣佛号，慈恩绕圈疾行不时发出惨厉虎吼。他越奔越快额头大汗头顶蒸笼般冒出白气。一灯突然提气喝问善恶之分参悟不透——慈恩一呆扑地摔倒。公孙绿萼上前扶起，慈恩迷糊中见她依稀是当年三妹容貌。裘千尺激他报仇，慈恩想起大哥惨死——一跃而起指着黄蓉要她偿命。郭芙出言顶撞被黄蓉喝退不听反而上前激将。慈恩怒喝声如霹雳——左掌拍出右手成抓同时袭到。黄蓉、武三通、耶律齐三人不约而同纵上各出掌击其左掌。砰的一声四掌相撞——慈恩屹立不动三人同时倒退数步。慈恩一举抓走郭襄举在头顶大叫要先杀此女再杀黄蓉。在场众人无一人武功能胜慈恩，投鼠忌器更无法施救。黄蓉急中生智哈哈大笑拆散头发张开双臂尖声惨笑走向慈恩——模仿瑛姑当年疯状，提起大理皇宫中慈恩击伤刘贵妃孩儿致死的往事。慈恩全身发抖数十年前往事兜上心来——痛悔之念不能自已，呜咽道死了死了好好的小孩儿活活给我打死了。他缓步走到黄蓉面前将郭襄递过说小孩儿是我弄死的你打死我抵命罢。黄蓉正伸手欲接，一灯喝道冤冤相报何时方了手中屠刀何时方抛。慈恩一惊双手松了郭襄往下掉——黄蓉右脚伸出以脚背在婴儿腰间轻轻托住向外送出，郭襄稳稳飞向耶律齐怀中。慈恩面如死灰刹时大彻大悟向一灯合十躬身说多谢和尚点化。一灯还礼恭喜和尚终证大道。两人相对一笑慈恩大袖一挥飘然出了大厅——裘千尺急叫他回来，慈恩回头说你叫我回来我却叫你回来呢。一灯退到厅角低首垂眉再不言语。黄蓉向一灯行礼道歉——一灯微笑道蓉儿蓉儿真乃女中诸葛也。",
  "事件概要": "郭襄平安脱险，慈恩在黄蓉与一灯点化下彻底醒悟离去，大厅中最凶险的一重杀机由此消散。",
  "insert": {
    "裘千仞": {
      "人物经历": {
        "第31回-03-慈恩抓郭襄被黄蓉装疯击中心病大彻大悟离去": "在大厅中绕圈疾行虎吼连声——善恶交战心中如火如沸。被一灯断喝后摔倒。被裘千尺激起大哥之仇——一跃而起指黄蓉要她偿命。郭芙言辞相激后勃然爆发——左掌右抓齐施黄蓉武三通耶律齐三人合力仍挡不住其左掌。一举抓走郭襄举在头顶大叫要先杀此女再杀黄蓉。不料黄蓉突然装疯模仿瑛姑疯状——提起当年大理皇宫击伤刘贵妃孩儿致死之事。慈恩全身发抖数十年前往事兜上心来痛悔不能自已——将郭襄递还黄蓉。一灯点化后双手松开郭襄往下掉——被黄蓉巧妙救回。面如死灰刹时大彻大悟——向一灯合十躬身多谢和尚点化。一灯还礼恭喜和尚终证大道。扬长而出——裘千尺急叫二哥回来，慈恩回头道你叫我回来我却叫你回来呢——飘然出了大厅从此放下屠刀证得大道"
      }
    },
    "黄蓉": {
      "人物经历": {
        "第31回-03-黄蓉装疯救女一灯赞为女中诸葛": "眼见慈恩抓走郭襄无人能救——急中生智哈哈大笑拆散头发张开双臂尖声惨笑模仿瑛姑疯状。提起大理皇宫中慈恩击伤刘贵妃孩儿之事——击中慈恩一生最大心病。慈恩痛悔交还郭襄后——一灯点化时慈恩松手郭襄下坠——千钧一发之际右脚伸出以脚背在婴儿腰间轻轻托住向外送出让郭襄稳稳飞向耶律齐怀中。向一灯行礼道歉——一灯微笑道蓉儿蓉儿真乃女中诸葛也。在场诸人只有武三通隐约知道旧事余人相顾茫然"
      }
    },
    "一灯大师": {
      "人物经历": {
        "第31回-03-一灯点化慈恩大彻大悟": "在绝情谷大厅中盘膝坐于厅心口诵佛经对周遭变故如不见。见慈恩抓郭襄危急之时缓缓抬头——望着慈恩道你要找人家报仇人家来找你报仇却又如何。在紧要关头提气喝道冤冤相报何时方了手中屠刀何时方抛——令慈恩一惊松手。慈恩大彻大悟后合十躬身说多谢和尚点化——一灯还礼恭喜和尚终证大道。两人相对一笑后一灯退到厅角低首垂眉再不言语。黄蓉来行礼道歉时微笑道蓉儿蓉儿真乃女中诸葛也"
      }
    },
    "郭芙": {
      "人物经历": {
        "第31回-03-郭芙顶撞慈恩致郭襄被擒": "进厅后靠在母亲身边接过妹子抱在怀里。见慈恩凶神恶煞般指着母亲喝骂忍耐不住——走上数步说你若再无礼姑娘可容不得你了。黄蓉见她涉险连忙喝退——郭芙却见慈恩疯疯癫癫说了半天不动手心中对他毫不忌惮反而上前激将。慈恩爆发时手足无措——若非黄蓉相救几乎为掌力所伤。见妹子落入慈恩之手心中一片混乱——直到靠到母亲身上方才啊的一声叫了出来。危急中大叫杨过杨大哥快来救了我妹子——数次遭逢大难都是杨过救她出困此时自然而然盼望杨过来救"
      }
    },
    "耶律齐": {
      "人物经历": {
        "第31回-03-耶律齐接住郭襄配合黄蓉行计": "随黄蓉武三通同时纵上各出掌击慈恩左掌——功力最浅退得最远。慈恩抓走郭襄后拔出兵刃准备应战。黄蓉踢出郭襄时伸臂稳稳接住——见女婴乌溜溜眼珠不住滚动正欲大哭鲜龙活跳不似有半点损伤。一怔之下随即会意——料想黄蓉知道郭芙莽撞才将幼女掷给自己。当即伸掌在婴儿口上轻按阻止她哭出声来——大叫啊哟小孩儿给这和尚弄死了——配合黄蓉之计助慈恩痛悔"
      }
    },
    "武三通": {
      "人物经历": {
        "第31回-03-武三通与黄蓉合力抵挡慈恩": "见慈恩爆发攻击郭芙——与黄蓉耶律齐不约而同纵上各出掌击慈恩左掌。三人合力仍被震退数步。隐约知道当年大理皇宫旧事——对黄蓉装疯救女之计心领神会"
      }
    },
    "裘千尺": {
      "人物经历": {
        "第31回-03-裘千尺激兄报仇见证慈恩离去": "出言激兄报仇语气越来越严厉。慈恩抓郭襄时大喜叫道好二哥这才是英名盖世的铁掌水上飘裘大帮主。见黄蓉装疯大出意料之外瞪目凝视惊疑不定。眼见慈恩大彻大悟飘然离去——急叫二哥你回来。慈恩回头说你叫我回来我却叫你回来呢——裘千尺望着兄长背影在屏门外隐没料想此生再无相见之日——胸口不禁一酸体味那句话似是劝自己悬崖勒马回头是岸心中隐隐一阵惆怅一阵悔意"
      }
    },
    "公孙绿萼": {
      "人物经历": {
