      "人物经历": {
        "第10回-01-耶律齐显神技释完颜萍": "第四次与耶律齐交手仍被轻松击败——耶律齐以神乎其技的两指夺刀之法当众夺下她的柳叶刀。与耶律燕再斗时心灰意冷横刀自刎却被耶律齐再次夺刀相救。听耶律楚材讲述辽金世仇后茫然无语。耶律齐以言语相激劝她另寻明师，并以'逼得我用左手即引颈就戮'的誓言给她留有复仇之机。最终昂首走出耶律家，脸上掩不住凄凉之色。"
      },
      "关系网": {
        "耶律齐": "惺惺相惜/-50（数次手下容情以礼相待，武功远胜自己却从不欺凌——心中知他慷慨高义但父母之仇不能不报）",
        "耶律燕": "交手/10（再斗一场讨回兵刃，耶律燕仍不是对手）",
        "耶律楚材": "世仇/-95（听他亲口讲述辽金灭国旧事方知两家恩怨之深，杀父之仇仍是刻骨不忘）"
      }
    },
    "耶律齐": {
      "人物经历": {
        "第10回-01-耶律齐显神技释完颜萍": "当众演示夺刀绝技——以歪斜掌封去路留空隙、笼袖诱敌、两指夹刀的手法轻巧夺下完颜萍柳叶刀，众人看得呆了哄堂大彩。完颜萍横刀自刎时再次以同样手法夺刀相救。见完颜萍纠缠不清，以言语相激劝她另寻明师，立下'只要逼得我使用左手就引颈就戮'的誓言——料她武功与自己相差太远纵得高人指点也难胜单手，盼她心有专注不再自杀。"
      },
      "关系网": {
        "完颜萍": "惺惺相惜/40（见她矢志复仇志气可嘉又怜她身世凄凉，数次手下容情不忍加害，更以自己为靶转移她寻父报仇之念）"
      }
    },
