  "事件引子": "金轮法王伤愈后与杨过交谈，得知他身负杀父深仇，提出二人结盟——法王助杨过报父仇，杨过助法王取武林盟主。二人击掌三下订了盟约。",
  "后续事件": {
    "事件名": "第16回-08-金轮法王引杨过见忽必烈",
    "描述": "金轮法王伤势愈了八九成可行动如常，见杨过于武学之道已进了一层，决意带他去见蒙古王子忽必烈。"
  },
  "事件详情": "杨过将最近得悉郭靖夫妇害死父亲、决意报仇之事向金轮法王说了。法王初时对这狡黠少年半信半疑，但杨过于杀己易如反掌之际反而相助疗伤确是对己绝无敌意，便提出二人联手——他助杨过报仇，杨过助他取武林盟主之位。杨过待要答允却想起蒙古兵将屠戮之惨，说不能相助蒙古。法王直言单枪匹马杀郭靖难上加难。杨过沉吟半晌后答应助法王取武林盟主但须法王助他报仇，且声明只助争盟主不助蒙古攻宋杀害百姓。二人击掌三下订了盟约。法王随后指出杨过武学根本大弊——博采众家却驳而不纯，无一门功夫练到真正第一流的境界。这几句话如当头棒喝说中杨过要害。杨过走出茅棚在山顶上苦苦思索——自辰时想到午后又至深夜，不饮不食，生平所见诸般精妙武功在脑海中此来彼往相互激荡。想到后来不由自主挥拳踢腿施展起来，最终乱成一团仰天摔倒昏了过去。次晨起来又想，七日之中接连昏迷了五次。连想数日后恍然有悟——猛地明白诸般武术皆可为我所用既不能合而为一也不必强求，日后临敌之际当用则用不必去想武功的出处来历也已与自创一派相差无几。想明白此节登时心中舒畅。",
  "事件概要": "杨过与金轮法王达成联手之议，报父仇与武林争斗开始同蒙古势力纠缠。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第16回-07-杨过金轮法王结盟论武": "与金轮法王击掌三下订下盟约——法王助他报杀父之仇他助法王取武林盟主之位，但声明只助争盟主不助蒙古攻宋杀害百姓。被金轮法王一语道破武学根本大弊——博采众家却驳而不纯无一门功夫练到真正第一流境界，如当头棒喝。此后七日不饮不食在山顶上苦苦思索自创武学之路——自辰时想到午后又至深夜生平所见诸般精妙武功在脑海中此来彼往相互激荡，七日之中接连昏迷了五次。连想数日后恍然有悟——猛地明白诸般武术皆可为我所用既不能合而为一也不必强求，日后临敌当用则用不必去想武功出处来历。想明此节登时心中舒畅于武学之道已进了一层"
      }
    },
    "金轮法王": {
      "人物经历": {
        "第16回-07-杨过金轮法王结盟论武": "提出二人联手——他助杨过报仇杨过助他取武林盟主。与杨过击掌三下订下盟约。见杨过武功驳而不纯一语道破其武学根本大弊——博采众家固然甚妙但也不免驳而不纯。见达尔巴要救倒地的杨过时笑阻——'别去拂乱他心思只可惜你才智平庸难明其中的道理'。数日后见杨过神情平和成竹在胸，知他于武学之道已进了一层"
      }
    }
  },
  "update": {
    "杨过": {
      "状态": "武学顿悟（经七日苦思昏迷五次后恍然有悟——明白诸般武术皆可为我所用既不能合而为一也不必强求。日后临敌之际当用则用不必去想武功出处来历也等于自创一派。想明此节登时心中舒畅神情平和一副成竹在胸的模样）",
      "关系网": {
        "金轮法王": "盟友且敬服/55（二人击掌订盟互为助力。法王一语道破自己武学弊病如当头棒喝——真心感激这位前辈的指点。结盟之后对法王的武学见识心生敬意）"
      }
    },
    "金轮法王": {
      "关系网": {
        "杨过": "盟友且赏识/60（击掌订盟后对这个少年更为赏识——见他七日昏迷五次终于武学突破，知他聪慧过人将来成就不可限量。杨过不助蒙古攻宋的法王也尊重其志——人各有志勉强不来）"
      }
    }
  },
