  },
  "事件详情": "杨过与陆无双被李莫愁追逼正急，陆无双惶急无计，杨过忽发奇想，说要玩\"拜天地成亲\"——让陆无双扮新娘子遮住面容躲过师父。事势紧迫，陆无双也无暇斥骂，只得依计行事。乡间小路之上正有一队迎亲队伍抬着一顶八人抬的大花轿，杨过策驴冲上前去，挥鞭摔翻两名阻拦的壮汉，右手一探将骑白马的新郎提了过来抛向空中再接住，吓得众人魂不附体。杨过自称大王劫道，却提出一个荒诞不经的要求——让陆无双扮新娘子、自己扮新郎官。众人面面相觑，不敢违抗。此时李莫愁花驴的鸾铃声越来越近，送嫁喜娘七手八脚为陆无双穿上凤冠霞帔锦衣红裙，杨过也穿上新郎吉服。花轿转头走出十余丈，李莫愁洪凌波师徒追至，洪凌波问便是在问有没有见到一个跛脚姑娘。老者连说没见，二人纵驴掠过后又回转来。李莫愁拂尘挥出撕下半截轿帷，却只瞧见吓得簌簌发抖的新娘子——原来陆无双早料到师父去后必回，已低身躲在新娘裙下。李莫愁笑道\"新娘子挺俊呀\"，竟与洪凌波策驴去了。陆无双钻出来将新娘赶下轿去自己坐着，一行人继续向东南前行。",
  "事件概要": "杨过与陆无双扮作迎亲新人混过追捕，二人得以暂离李莫愁视线继续东行。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第9回-01-迎亲扮新娘躲李莫愁追兵": "带陆无双策驴奔逃中见一队迎亲花轿挡路，灵机一动想出扮新郎新娘的荒诞计策。策驴冲入迎亲队，摔翻壮汉抓走新郎抛接炫技镇住众人。逼送嫁喜娘为陆无双换上凤冠霞帔红裙，自己穿上新郎吉服。花轿转头走出十余丈，李莫愁洪凌波追至，两度查问。李莫愁撕开轿帷时陆无双已躲入新娘裙下，竟未被发现。陆无双最终将新娘赶下轿自己舒舒服服坐花轿。"
      }
    },
    "陆无双": {
      "人物经历": {
        "第9回-01-迎亲扮新娘躲李莫愁追兵": "被李莫愁追逼正急，听杨过提出扮新娘躲师父的主意，虽觉古怪也别无他法。被送嫁喜娘七手八脚换上新娘子凤冠霞帔红裙。听到师父鸾铃声时一颗心怦怦急跳，躲在轿中不敢出声。李莫愁撕开轿帷时她已提前钻入新娘裙下躲藏，成功瞒过师父毒手。脱险后将吓得发抖的新娘赶下轿去，自己舒舒服服坐着花轿往东南行。"
      }
    },
    "李莫愁": {
      "人物经历": {
        "第9回-01-迎亲扮新娘躲李莫愁追兵": "与洪凌波在潼关道上往来搜索陆无双，追上一队迎亲花轿。两次从迎亲队旁掠过，洪凌波问话无果后又折回来。挥拂尘撕下半截轿帷，却只看见轿中一个吓得面如土色的新娘，心想新娘子还算俊俏，未察陆无双就躲在她裙下，笑了一笑便去了。"
      }
    },
    "洪凌波": {
