{
  "事件地点": "蒙古/襄阳城外/忽必烈大营",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 12,
    "日": 25,
    "时": 9
  },
  "事件结束时间": {
    "年": 1244,
    "月": 12,
    "日": 25,
    "时": 20
  },
  "事件引子": "周伯通骑着骆驼远去后，法王将王旗交给萨多，率众人继续前行...",
  "后续事件": {
    "事件名": "第25回-01-周伯通被诱入山洞遭彩雪蛛毒咬",
    "描述": "周伯通当夜果然前来蒙古大营盗取王旗"
  },
  "事件详情": "周伯通远去后，法王凝神思索如何对付这个神出鬼没的老顽童，偶然回顾见尹赵二人交头接耳不住回头望小龙女脸上大有惧色。法王心念一转出言试探——'尹道兄你和龙姑娘素来相识么？'尹志平脸色陡变应了一声。法王更知其中大有缘故，赵志敬乘机说法王在大胜关英雄会上曾输给小龙女此仇不可不报，法王笑道'老衲养气数十年你用言语激我又有何用'。法王意示闲暇双手合十说'老衲先行一步二位了断了龙姑娘之事请来王爷大营过访'纵马便行。赵志敬大急拍马追上请求同行。法王随口问起全真教情况，得知丘处机七十多岁、马钰年老静退，便故意说掌教大任该由赵志敬接充才是。这几句话赵志敬在心中蕴藏了七八年之久，今日被法王说出怨恨之情更是见于颜色。午牌时分一行人来到忽必烈大营，小龙女骑着驴子站在里许之外不再近前。忽必烈正为王旗被盗大为烦恼，见法王携王旗回来大喜忙起座相迎。忽必烈雄才大略对尹赵二人大加接纳摆设酒筵接风，又不住推崇尼摩星忠于所事以致双腿残废请他坐了首位。酒筵过后法王陪尹赵到旁帐休息，尹志平心神交疲倒头便睡。法王邀赵志敬出去走走——详询全真教中诸般情状，赵志敬有问必答尽皆举实以告。法王叹道'贵教能有今日规模实在不易老衲却要说马刘丘王诸位道长见识太是胡涂怎能将掌教大任传于尹道兄'，随即提出'我叫你在半年之内便当上全真教的掌教'。赵志敬大喜将信将疑，法王说出计策——将王旗秘密藏于山洞中让赵志敬悄悄告诉周伯通所在，以此讨得周伯通欢心为强援。二人翻山寻到一处隐蔽山洞记好位置。入夜后赵志敬坐在沙丘旁眺望大营灯火，隐约见小龙女仍坐在那株大树之下。正在洋洋自得之际，忽见一条黑影自西疾驰而至营帐间东穿西插倏忽间已奔到王旗旗杆之下——宽袍大袖白须飘荡正是周伯通到了。",
  "事件概要": "法王借掌教之位成功拉拢赵志敬，并设下王旗诱局图取周伯通与全真教，内外勾结就此成形。",
  "insert": {
    "金轮法王": {
      "人物经历": {
        "第24回-09-法王拉拢赵志敬谋夺掌教": "周伯通走后凝神思索对付之策。回顾尹赵二道神色有异便出言试探——'尹道兄你和龙姑娘素来相识么'一问便知其中大有缘故。赵志敬想激自己出手对付小龙女被识破——'老衲养气数十年你用言语激我又有何用'。意示闲暇纵马先行逼赵志敬求自己同行。随口问全真教内情——得知马钰年老静退丘处机七十多岁，便故意说掌教大任该赵志敬接充——正中其心事。到忽必烈大营后详询全真教势力分布诸处重镇所在——赵志敬感恩有问必答尽举实告。提出帮赵志敬半年内当上掌教——第一步令其在教中得周伯通为强援。与赵志敬翻山找到隐蔽山洞藏王旗——让赵志敬告诉周伯通所在讨其欢心"
      },
      "关系网": {
        "赵志敬": "利用/65（已成功收服赵志敬——答应半年内助其当上全真掌教令其感恩涕零。对赵志敬的才能和野心已了然于胸——此人武功虽不及尹志平精明干练却差得远。利用赵志敬对掌教之位的野心为自己效力——若助他夺得全真教蒙古南征可获大助。已与赵志敬约定藏王旗之事——让他当夜引周伯通去山洞取旗）"
      }
    },
    "赵志敬": {
      "人物经历": {
        "第24回-09-赵志敬被法王拉拢图谋掌教": "法王故意纵马先行时大急拍马追上——生怕小龙女追上前来想起玉蜂蜇身之痛心胆俱裂。法王问全真教内情时起初有问必答。听法王说'掌教大任该由道兄接充才是'——这几句话在心中蕴藏了七八年之久从未宣之于口今日被说出怨恨之情见于颜色。到忽必烈大营后被王爷礼遇喜出望外。法王提出半年内助其当上掌教——赵志敬大喜将信将疑。随法王翻山找到隐蔽山洞——牢牢记住两株大榆树为标记。夜晚独自坐在沙丘旁——见小龙女仍在大树下望着自己。心中洋洋自得想着三月后任掌教声名扬于宇内天下三千道观八万弟子尽数听自己号令"
      },
      "关系网": {
        "金轮法王": "感恩依附/80（法王应允半年内助其当上全真掌教——赵志敬感激涕零不知如何称谢。法王出计帮他获得周伯通欢心为强援更让他死心塌地。对法王的智谋和高义佩服得五体投地——'大师恩德不知何以为报'。从最初想利用法王到如今心甘情愿为其所用）",
        "周伯通": "师叔祖欲利用/60（法王出计让自己将藏王旗之处告诉周伯通——'让他找到王旗岂非奇功一件'。'这定能讨得周师叔祖的欢心'——若得周伯通为强援在教中势力大增。已在沙丘旁等待周伯通过来——准备依计行事）"
      }
    },
    "忽必烈": {
      "人物经历": {
        "第24回-09-忽必烈接见尹赵设宴款待": "正为王旗被盗大为烦恼——王旗是三军表率千军万马全随王旗进退实是军中头等重要的物事。见法王携王旗回来大喜忙起座相迎。听法王引见尹赵二人是全真教高士当即大加接纳显得爱才若渴——对王旗的失而复得竟似没放在心上。吩咐摆设酒筵为二人接风。绝口不提法王等行刺郭靖不成之事，不住推崇尼摩星忠于所事以致双腿残废——请他坐了首位接连把盏"
      }
    }
  },
  "update": {
    "金轮法王": {
      "所在位置": "蒙古/襄阳城外/忽必烈大营",
      "状态": "在忽必烈大营中已成功拉拢赵志敬——答应半年内助其当上全真掌教。将王旗秘密藏于山洞中——要赵志敬将位置告诉周伯通以讨其欢心为强援。对全真教势力分布已了如指掌——暗想若得该教相助于南征大有好处。认为笼络全真教甚至可能胜于刺杀郭靖。王旗已经藏好——正在等待周伯通当夜来盗"
    },
    "赵志敬": {
      "所在位置": "蒙古/襄阳城外/忽必烈大营",
      "状态": "已被法王成功拉拢——答应半年内助自己当上全真教掌教令自己感恩涕零。随法王到山上找到了藏王旗的隐蔽山洞——牢牢记住两株大榆树为标记。夜晚独自坐在沙丘旁等待周伯通到来——心中盘算着三月后任掌教声名扬于宇内天下三千道观八万弟子尽数听自己号令。隐约见小龙女仍坐在里许外的大树下"
