{
  "事件地点": "大宋/晋南/万兽山庄",
  "触发条件": {
    "类型": "时间",
    "年": 1259,
    "月": 10,
    "日": 13,
    "时": 10
  },
  "事件结束时间": {
    "年": 1259,
    "月": 10,
    "日": 13,
    "时": 11
  },
  "事件引子": "你听到万兽山庄外传来兵刃相交之声，一个女子高声喝道：'有没有一个大头矮子在这屋里？我要问他，把我妹子带到哪里去了？'",
  "后续事件": {
    "事件名": "第35回-03-郭芙刺伤史孟捷杨过道破往事",
    "描述": "郭襄持金针离去寻找姊姊，郭芙已与史孟捷、大头鬼动手激斗"
  },
  "事件详情": "酒过数巡，林中猿猴高声啼鸣，史氏兄弟微微变色。史孟捷出厅查看，来人却是郭芙——她硬闯万兽山庄寻找妹子郭襄。郭襄听得姊姊寻来又惊又喜，但见杨过双眼精光闪烁神情特异，那声'姊姊'到了嘴边却没叫出来。郭襄站起身来告辞，一滴泪水落在酒杯之中。杨过心中一动飘身追出，在林中赶上郭襄，柔声询问有何为难之事。郭襄强笑说没为难之事，只是听说'天下没不散的筵席'心中郁郁。杨过心头一震，想起当年怀抱婴儿、捕缚母豹喂她乳吃、在古墓养育多时的往事，不由得痴痴怔住。郭襄托他夫妇相会后带讯到襄阳报喜，杨过大是感激。他目不转睛瞧着郭襄，脑海中浮现十五年前怀中所抱婴孩的小脸，胸中涌起保护照顾之情，慨然道若她有不愿跟爹娘说的缓急之情尽管带讯来。郭襄嫣然一笑。杨过屈指算出她十月廿四的生辰，郭襄大奇。杨过取出三枚小龙女平素所用的金针暗器递给她，说见此金针如见你面，托人持针传命也必办到。郭襄当即用了第一枚金针——要杨过取下面具看看他的真面目，杨过揭下面具露出清癯俊秀的脸孔。郭襄又将第二枚金针塞在杨过手中，求他今年十月廿四生日那天到襄阳一见。杨过答应了。郭襄拈着第三枚金针说要日后再用，便转身窜入林中寻姊姊去了。",
  "事件概要": "杨过以金针为诺应下郭襄生辰之约，郭襄既见其真容又留下日后求见的凭证，这段缘分自此落了实处。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第35回-02-杨过赠三枚金针予郭襄": "追郭襄至万兽山庄外林中，得知她是郭靖黄蓉之女。忆起当年怀抱婴儿、捕豹喂乳、古墓养育的往事。取出小龙女平素所用三枚金针暗器赠予郭襄，许下持针传命必办的诺言。郭襄以第一枚金针求他取下面具，杨过揭面具露出真容；以第二枚金针求他十月廿四生日到襄阳相见，杨过应允；第三枚金针郭襄留待日后再说"
      }
    },
