    "日": 5,
    "时": 14
  },
  "事件结束时间": {
    "年": 1259,
    "月": 10,
    "日": 5,
    "时": 15
  },
  "事件引子": "你听说郭襄拔下金钗请众人喝酒央求宋五再讲神雕侠故事，宋五便说起自己当年被神雕侠以二千两银子赎命的经历。",
  "后续事件": {
    "事件名": "第33回-05-郭芙道破杨过身份郭襄心生仰慕",
    "描述": "中年妇人讲完故事后，郭襄对神雕侠更加倾慕，郭芙终于忍不住说出神雕侠的真实身份。"
  },
  "事件详情": "郭襄请众人喝了十斤酒二十斤牛肉，央求宋五再讲神雕侠故事。宋五便说起五年多前在山东济南府打抱不平杀了一个地痞被判斩决，县官收了土豪一千两银子将罪名全推在他身上。他在狱中喊冤骂赃官却无济于事。哪知过了些日子县官竟笑嘻嘻说查清他是冤枉的、地痞是土豪所杀，将他当堂释放。他百思不解，回家后才知母亲在街上痛哭时遇神雕侠路过，神雕侠给了他母亲二千两银子将他买了出来。三个月后县官被盗四千两银子——他知道定是神雕侠所为。郭芙插口说姓杨的岂肯做赔本之事，郭襄追问'神雕侠姓杨么'，郭芙连忙否认说听错了。郭襄请中年妇人讲她表妹的故事。中年妇人缓缓道来：表妹母女为赎回被蒙古千户掳为奴隶的父亲，卖身勾栏苦熬数年凑足五百两银子，不料千户收钱后又起歹心要强占表妹。姑母哭号无人敢管，姑丈反而劝女儿依从千户又写休书休了姑母。姑母万念俱灰林中上吊，幸得神雕侠经过救下，他当晚闯入千户府——一拳打死负心薄幸的姑丈、将千户投入淮河、救出表妹。神雕侠说生平最恨负心薄幸之人与奴颜事敌之辈。众人听得感慨万千，郭襄更是悠然神往。",
  "事件概要": "神雕侠赎命救人和惩治负心敌奴的名声再添实证，郭襄对其侠义与性情愈发神往，追问真身之念更深。",
  "insert": {
    "宋五": {
      "人物经历": {
        "第33回-04-宋五述说神雕侠赎命救囚": "在郭襄央求下继续讲述：当年因打抱不平杀人被判斩决，被县官与土豪串通栽赃，在狱中冤气冲天却无计可施。神雕侠路过听了母亲哭诉，以二千两银子将他从死牢中赎出。三月后县官被盗四千两——正是神雕侠所为。事后他寻到海边见神雕侠望着海潮出神，才得以当面磕头道谢。"
      }
    },
    "中年妇人": {
      "人物经历": {
        "第33回-04-中年妇人述说表妹一家遭遇": "在安渡老店围炉夜话中，应郭襄之请讲述姑表妹一家的悲惨遭遇：表妹母女为赎回被蒙古千户掳为奴隶的姑丈，卖身勾栏数年方凑足五百两银子。千户收了钱又起歹心要强占表妹，姑丈反劝女儿依从、写休书休妻。姑母林中上吊被神雕侠救下，神雕侠当晚闯入千户府——打死负心姑丈、杀千户、救出表妹。妇人转述神雕侠的话：生平最恨负心薄幸之人和奴颜事敌之辈。"
      }
    },
    "郭襄": {
      "人物经历": {
        "第33回-04-郭襄听赎命与救人故事心生感慨": "听宋五讲述神雕侠赎命经过，又听中年妇人讲述表妹母女悲惨遭遇与神雕侠惩恶救人的故事，心中感慨更深。听郭芙无意中说出'姓杨的'三字，追问神雕侠是否姓杨——姊姊慌张否认更令她确信。听罢中年妇人故事，拿起木柴投在火里，轻声道：'神雕侠虽然急人之难解人之困，说不定他自己却有一件为难的心事。'又听说神雕侠呆望海潮是因为结发妻子在大海彼岸不能相见，轻轻叹道：'我料想这样的人物必是生具至性至情，果然不错。'"
      }
    },
    "郭芙": {
      "人物经历": {
