  "事件引子": "大石屋前两名绿衫僮儿手执拂尘站在门前。众人以为谷主必出门迎接，不料走出一位四尺来高、长须垂地的古怪老者。",
  "后续事件": {
    "事件名": "第17回-05-周伯通假扮潇湘子持剪斗樊一翁身份败露",
    "描述": "假潇湘子口出恶言挑衅绝情谷，持大剪刀与樊一翁激斗，真潇湘子随后闯入揭破身份。"
  },
  "事件详情": "七人来到大石屋前，两名绿衫僮儿手执拂尘站在门前。一个僮儿进去禀报，另一个开门迎客。杨过正思忖谷主是否出门迎接，石屋中出来一个身穿绿袍的长须老者——身材极矮不逾四尺，五岳朝天相貌清奇，一丛胡子直垂至地。杨过心道这谷主怪模怪样生的女儿却美。老者向六人深深打躬请入奉茶。尼摩星心想对方比自己更矮，抢前伸手相握运劲试探，不料对方既不还击也不抗拒，手中如握硬木一般，脸上微闪绿气。尼摩星大感诧异不敢再加劲，哈哈一笑放手。金轮法王见了便双手合十大大方方走进去。潇湘子、尹克西、马光佐鱼贯而入，马光佐饥火与怒火交迸，进门时故意伸大脚往那老者长须上踹去一脚踏在足底。那老者不动声色只道贵客小心，微一摇头马光佐便猛地仰天一跤摔倒。杨过急忙抢上两步伸掌在他屁股上一托将其庞大身躯弹了进去。那老者恍若未见，朗声请谷主见客——众人这才知道这矮子并非谷主。后堂转出十来个绿衫男女左右站开，公孙绿萼也在其中。屏风后转出一人，四十五六岁年纪面目英俊举止潇洒，只是面皮蜡黄容颜枯槁，穿崭新宝蓝缎袍。他便是绝情谷主公孙止。",
  "事件概要": "樊一翁出面接客试手，公孙止也正式登场，绝情谷主人的威势由此立起。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第17回-04-樊一翁接客众人试手公孙止正式出场": "在大石屋前见长须矮老者出来以为是谷主，心想此人怪模怪样生的女儿却美。见马光佐踏樊一翁胡须反被摔倒，抢上两步伸掌托住马光佐屁股将其弹了进去。随后见公孙绿萼站在人丛中，又见公孙止正式出场——四十五六岁面目英俊举止潇洒有轩轩高举之概，只是面皮蜡黄。"
      }
    },
    "樊一翁": {
      "人物经历": {
        "第17回-04-樊一翁接客众人试手公孙止正式出场": "代师父公孙止出迎六位贵客，深打躬请入奉茶。被尼摩星拉手运劲试探时既不还击也不抗拒，手中如硬木一般脸上微闪绿气，让尼摩星知难而退。被马光佐伸脚踏住胡子后不动声色，微一摇头便让马光佐仰天一跤摔倒。随后朗声请谷主见客，在师父出场后垂手站在椅子之侧恭敬随侍。"
      }
    },
    "公孙止": {
      "人物经历": {
        "第17回-04-公孙止接见六位贵客正式出场": "从屏风后转出，向六人一揖随随便便坐在东首椅上。说话间说明本谷数百年来一直茹素，自唐玄宗天宝年间始迁祖便来此隐居。对金轮法王提及世泽绵长时拱手谦辞。面对潇湘子突然怪声怪气问'你祖宗见过杨贵妃么'，从容回答始迁祖当年确在唐玄宗朝上为官，后见杨国忠混乱朝政愤而隐居。"
      }
    },
    "金轮法王": {
      "人物经历": {
        "第17回-04-樊一翁接客众人试手公孙止正式出场": "见尼摩星试樊一翁深浅未果，决定虚实不明不必妄自出手，双手合十大大方方走进去。随后见公孙止正式出场，听其讲述谷中自天宝年间迁来隐居的来历，拱手赞世泽绵长。发现潇湘子脸容忽变更显诡异，暗想此人内功竟如此厉害令容貌也全变了。"
      }
    },
    "尼摩星": {
      "人物经历": {
        "第17回-04-尼摩星试樊一翁深浅": "心想自己是个矮子谷主却比自己更矮，抢前先行伸手与樊一翁相握运劲试探。先使两分劲觉对方既不还击也不抗拒，又加两分劲仍如握硬木，再加两分劲见老者脸上微闪绿气。大感诧异不敢再使全力，哈哈一笑放脱了手。"
      }
    },
    "马光佐": {
      "人物经历": {
        "第17回-04-马光佐踏樊一翁胡子被摔": "见樊一翁长须垂地十分奇特，饥火与怒火交迸之下伸大脚往他长须上踹去，一脚踏在足底。樊一翁微一摇头便仰天一跤摔倒，被杨过伸掌托住屁股弹了进去，站桩立稳后双手摸着自己屁股发楞。"
      }
    }
  },
