    "日": 30,
    "时": 12
  },
  "事件引子": "四人坐在倒塌的木柱之上。杨过向一灯大师约略述说自己如何识得武三通、朱子柳，以及在绝情谷中毒、天竺僧为其求解药被困的来龙去脉……",
  "后续事件": {
    "事件名": "第30回-06-抵达绝情谷杨过救程英陆无双中情花刺",
    "描述": "一行人赶了五六日路程，终于来到绝情谷口，却听到谷中隐隐传来兵刃相交之声"
  },
  "事件详情": "杨过坐在倒塌木柱上向一灯约略讲述识得武三通、朱子柳以及在绝情谷中毒的经过。一灯告知慈恩正是绝情谷女谷主裘千尺的兄长。杨过询问裘千尺近况难以回答——她手足筋脉被丈夫挑断已成废人。一灯伸手搭小龙女双腕脉后脸现忧色——她剧毒已透入重关，若一灯未受伤本可用一阳指暂缓毒质。当下从怀中取出一个磁蛋交给小龙女——蛋破生鸡鸡大生蛋既有其生必有其死——小龙女领悟后击碎蛋壳取出金黄浑圆的丸药嚼碎咽下，保得七日平安。一灯感叹这对少年夫妇实是人间龙凤只有郭靖黄蓉夫妇能与之比肩。次晨四人赶路，一灯伤势不轻仍坚持亲去绝情谷。疾行中小龙女与慈恩以轻功竞速——杨过赶上相护时一灯追上称赞其内力深厚问及师承，杨过答是妻子所教、内力大进或因服过数十枚奇蛇之胆。一灯认出乃菩斯曲蛇——佛经所载行走如风极难捕捉。转过山坳时杨过发现小龙女身后多了一人——原来是白发白须的老顽童周伯通。周伯通将小龙女托上背上的木箱让她休息，暗助她赛轻功赢了慈恩——惹得慈恩大为沮丧。周伯通遥遥见到一灯后大叫'出行不利溜之大吉'，斜刺里窜入树林霎时无影无踪。",
  "事件概要": "一灯赠药为小龙女暂缓七日毒发并随行赴绝情谷，周伯通现身同行，救人求药阵容进一步壮大。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第30回-05-一灯赠药四人相认赶赴绝情谷": "向一灯述说识得武三通朱子柳及绝情谷中毒经过。告知慈恩裘千尺是他妹妹。见一灯为小龙女诊脉忧色时心往下沉双手冰冷。听一灯说可保七日平安后拍腿站起大叫——想到天竺神僧治毒本事出神入化可解毒。与一灯并肩而行交谈内力来源——提及吃过数十枚怪蛇之胆，一灯认出是佛经所载的菩斯曲蛇叹为旷世奇缘。见周伯通暗助小龙女赛轻功胜慈恩颇觉有趣，上前道谢"
      }
    },
    "小龙女": {
      "人物经历": {
        "第30回-05-一灯赠药小龙女服药保七日平安": "伸出双手让一灯搭脉，眼光始终望着杨过——她早没想到能活至今日见杨过担忧便缓缓说'生死有命岂能强求'。听一灯说她毒入重关、本可用一阳指暂缓但受伤后无法使出时淡淡一笑说'大师说得很是'。看着雪花说出'到得明年冬天又有许许多多雪花只不过已不是今年这些雪花罢了'——这番话令一灯点头。击碎磁蛋取出金黄丸药嚼碎咽下后丹田和缓精神健旺。在疾行中以轻功与慈恩竞速，被周伯通托上木箱暗助——坐在箱顶平稳安适犹胜骑马。养足力气后纵身奔跑片刻间越过慈恩，侧头微微一笑"
      },
      "重要物品": {
        "磁蛋丸药（已服）": "一灯大师所赠——内藏金黄浑圆的续命丸药已嚼碎咽下。可保七日平安暂缓剧毒发作"
      }
    },
    "一灯大师": {
      "人物经历": {
        "第30回-05-一灯赠药述说往事四人赶赴绝情谷": "听杨过讲述绝情谷经历后告知慈恩与裘千尺的兄妹关系。为小龙女搭脉诊视——脸现忧色半晌不语，坦诚告知其毒入重关自己受伤后无法使一阳指相救。取出磁蛋赠药保七日平安。听小龙女谈雪花生死之理时点头暗赞。次晨不顾伤势坚持亲赴绝情谷——'我留着可不放心'。路上与杨过交谈内力来历认出菩斯曲蛇叹为旷世奇缘"
      }
    },
    "裘千仞": {
      "人物经历": {
        "第30回-05-慈恩得知妹子下落四人赶赴绝情谷": "向杨过询问妹子裘千尺近况——听说她手足残疾后叹道'我那妹子暴躁任性若是遭到了孽报也不足为奇'，又叹'隔了这许多年大家都老了'呆呆出神追忆往事。赶路中精进轻功向前急冲——以'铁掌水上飘'自负天下无双却一日一夜之间铁掌输杨过轻功输小龙女，大为沮丧。一灯开导'有所欲即有所蔽以你武功之强若非一意争胜岂能不知背后多了一人'"
      }
    },
    "周伯通": {
      "人物经历": {
        "第30回-05-周伯通现身助小龙女赛轻功": "背负全真教藏经阁的木箱在雪地中快步而行。将小龙女托上箱顶——'你到箱子上来歇一歇养养力气不用怕那老和尚'。暗助小龙女赛轻功胜过慈恩——与裘千仞曾从西域追到中原斗脚力对其脚程了如指掌。遥遥见到一灯大师后大叫'出行不利溜之大吉'斜刺里窜入树林霎时无影无踪"
      }
    }
  },
  "update": {
    "周伯通": {},
