917729.content:
{
  "事件地点": "大宋/晋南/黑龙潭",
  "触发条件": {
    "类型": "时间",
    "年": 1259,
    "月": 10,
    "日": 10,
    "时": 8
  },
  "事件结束时间": {
    "年": 1259,
    "月": 10,
    "日": 10,
    "时": 9
  },
  "事件引子": "你来到黑龙潭边，只见方圆七八里内草木不生，眼前一片死气沉沉的泥沼。潭心堆着不少枯柴茅草，隐约有白影闪动——那九尾灵狐便藏身其中。",
  "后续事件": {
    "事件名": "第34回-04-一灯求见杨过长啸逼瑛姑恩怨揭晓",
    "描述": "瑛姑以死相胁不肯交出灵狐，此时身后传来一声佛号，一灯大师求见瑛姑"
  },
  "事件详情": "杨过独自北行前往黑龙潭，郭襄好奇心起缓步跟随。杨过加快脚步试她轻功，郭襄展开家传轻功追赶却越落越远，一交摔在雪地中哭了出来。杨过倏去倏回拾起她掉落的手帕，郭襄反过来诬他抢帕。两人互相试探身份，郭襄不肯先说姓名，杨过也不愿以真面目示人。郭襄说起风陵渡听来的神雕侠事迹，衷心钦佩。杨过一时兴起要她说出几位大英雄才肯带她同行，郭襄说出父亲郭靖、母亲黄蓉、外公黄药师、鲁有脚四位，最后灵机一动说出神雕侠也算一位。杨过笑道大英雄岂能失信于小姑娘，携她同往黑龙潭。到达潭边后杨过以树枝掷入淤泥试出深浅，折下两根树枝缚在脚底在潭泥上滑行如飞。又为郭襄缚好树枝，握住她手带她滑入潭中。两人发现潭心柴草布置暗合五行方位，杨过高声呼喊却无人应答。忽然两只九尾灵狐从草丛中钻出分头逃窜，杨过独自追狐与灵狐在雪泥上风驰电掣般追逐。他以雪团击倒一头灵狐，存心与另一头赛脚力，赶至灵狐之前衣袖挥处将灵狐卷入袖中。不料灵狐竟是装死，郭襄用枯柴探草丛时引出白发老妇瑛姑。瑛姑恶狠狠望着二人，杨过施礼求赐灵狐救治朋友，瑛姑却凄惨大笑说起自己孩儿当年受伤无人肯救的往事。杨过好言恳求，瑛姑提出要郭襄留下陪伴十年作为交换。杨过婉拒，瑛姑出掌攻击，杨过连挨三掌不还手。瑛姑见伤他不得，提起灵狐厉声威胁：若再上前一步便捏死灵狐。",
  "事件概要": "杨过携郭襄追狐至黑龙潭并惊动瑛姑，灵狐仍未到手，求药之事转而系于化解她与旧人的深仇。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第34回-03-杨过郭襄赴黑龙潭追狐遇瑛姑": "加快脚步试探郭襄轻功，见她摔倒急回为她拾帕。听郭襄天真烂漫的称赞后答应带她同去黑龙潭。以树枝缚脚在泥沼上滑行如飞，又为郭襄缚好树枝携她滑入潭中。发现潭心柴草暗合五行方位，推测潭中有人居住。独自追狐与灵狐在雪泥上风驰电掣般追逐，以雪团击倒一头后存心与另一头赛脚力，终以衣袖卷住灵狐。不料灵狐装死骗过他，更引出瑛姑。杨过因捕捉对方心爱之物自觉理亏，连挨瑛姑三记寒阴箭掌力不还手，笑吟吟浑若无事"
      }
    },
    "郭襄": {
      "人物经历": {
        "第34回-03-郭襄随杨过赴黑龙潭追狐": "跟随杨过后被他加快脚步甩远，一交摔在雪地中哭了出来。杨过倏去倏回拾帕还她，她反诬杨过抢帕。说出郭靖黄蓉黄药师鲁有脚四位大英雄后灵机一动加说神雕侠也算一位，杨过笑允带她同去。到达黑龙潭见杨过滑泥绝技，又惊又喜。杨过为她缚好树枝握住她手带她滑入潭中，初时惊慌后觉身子轻飘飘有如御风而行连叫好玩。认出潭心柴草的五行方位，用枯柴探草丛时不料引出白发老妇瑛姑"
      }
    },
    "神雕": {
      "人物经历": {
        "第34回-03-神雕随杨过至黑龙潭": "与杨过并肩而行迈开大步疾如奔马。郭襄伸手拍其背脊时微展翅膀刷的一下将她手臂推开——郭襄不知这神雕于杨过乃半师半友身份大不相同"
      }
    },
    "瑛姑": {
      "人物经历": {
        "第34回-03-瑛姑现身对抗杨过": "隐居黑龙潭多年，养有一对九尾灵狐为伴。见杨过郭襄追逐灵狐大怒，从草丛中钻出举柴枝作势欲打。杨过施礼求赐灵狐时仰天凄惨大笑，提起自己孩儿当年受伤无人肯救的往事。提出要郭襄留下陪伴十年作为交换，被婉拒后出掌攻击杨过，连发三掌见对方浑若无事方知武功远非其敌。厉声威胁若再上前便捏死灵狐"
      }
    }
  },
