  },
  "事件结束时间": {
    "年": 1245,
    "月": 1,
    "日": 17,
    "时": 19
  },
  "事件引子": "蒙古群敌退尽，马光佐也已离去。杨过重剑拄地放眼望去——四下里剑光闪烁，每七个道人组成一队，重重叠叠的将自己与小龙女围在垓心。",
  "后续事件": {
    "事件名": "第28回-01",
    "描述": "杨过带小龙女离开重阳宫回古墓，小龙女伤势极重须得及早救治。二人历经磨难终于重逢。"
  },
  "事件详情": "蒙古群敌退尽后杨过放眼望去只见四下里剑光闪烁——每七个道人组成一队重围叠叠布成天罡北斗大阵。他此时早将生死置之度外，挺剑刺出七剑齐断。王处一喝令璇玑摇光后击，七名道人交叉换位从他身后掠过，又有十四柄长剑指到杨龙二人背后——七柄指杨过七柄指小龙女。杨过若是回剑后击只要剩下一剑小龙女便非受伤不可，至此已无法解救。丘处机举手喝道且住，二十一柄长剑剑尖离二人身周各距数寸停住不动。丘处机说全真教今日倚多为胜赢了也不光彩何况龙姑娘又已身负重伤，提议往日过节无论谁是谁非自今一笔勾销。杨过正要出言答允，小龙女的目光缓缓自左向右瞧去低声问道：'尹志平呢？'这四个字说得甚轻，但尹志平在迷迷糊糊中听来却宛似轰轰雷震。他霍地翻身站起冲入剑林叫道：'龙姑娘，我在这儿！'小龙女凝望片刻但见他道袍上鲜血淋漓脸上全无血色，不由得万念俱灰颤声说出：'过儿我的清白已为此人玷污，纵然伤愈也不能和你长相厮守。但……但他舍命救我，你也别再难为他。总之是我命苦。'她心光风霁月事无不可对人言，虽在数百人之前仍将悲苦照实说了出来。尹志平听得心如刀剜大叫：'师父四位师伯师叔弟子罪孽深重你们千万不能难为了龙姑娘和杨过！'说着纵身跃起扑向众道士手中兀自向前挺出的八九柄长剑——数剑穿身而过登时毙命。群道听了小龙女言语又见尹志平认罪自戕均大为惭愧。全真五子想到此事错在己方更是无言以对。丘处机向四个师兄弟望了一眼喝道：'撤了剑阵！'只听得呛啷啷之声不绝群道还剑入鞘让出一条路来。",
  "事件概要": "尹志平当众认罪自戕，全真教撤去剑阵放行，杨龙与全真教旧案至此摊明，双方恩怨转入无言收场。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第27回-09-杨过被困全真剑阵小龙女当众揭真相": "蒙古群敌退后被全真教天罡北斗大阵重重围困。挺剑刺出七剑齐断威力雄浑前所未见。但全真教变阵奇快——十四柄剑分指二人背后，杨过就算豁出自己性命也已无法解救小龙女。丘处机提议罢斗时正要答允——小龙女突然当众问出尹志平并说出清白被污之事。杨过听到小龙女自揭伤痛心如刀绞。尹志平自戕谢罪后丘处机喝令撤阵——杨过扶小龙女从群道让出的路中离去。"
      }
    },
    "小龙女": {
      "人物经历": {
        "第27回-09-小龙女当众揭受辱真相尹志平自戕": "杨过被困全真剑阵时目光缓缓扫过人群低声问道'尹志平呢'。尹志平冲入剑林现身，小龙女当众说出清白被尹志平玷污之事——光风霁月事无不可对人言。但说'但他舍命救我你也别再难为他'——终是心软饶过了这个大仇人。尹志平自戕后见证了仇人以命谢罪。"
      }
    },
