  },
  "事件引子": "天将黎明黄蓉独处室中，想起武氏兄弟之事恼怒不已，又记着郭靖的伤势到他房中探望...",
  "后续事件": {
    "事件名": "第22回-07-杨过智引敌寇黄蓉临盆生女",
    "描述": "杨过设计引开法王等敌寇，为黄蓉和郭靖争取脱险时机"
  },
  "事件详情": "天将黎明黄蓉独处室中来日大难不禁掉下泪来，又记挂郭靖伤势到他房中探望。郭靖盘膝坐在床上静静运功脸色苍白但气息调匀，只需休养数日便能痊愈。黄蓉见他伤情不禁想起少年时两人同在牛家村密室疗伤的往事。郭靖睁开眼见妻子脸有泪痕嘴角却带笑心中一阵温暖。黄蓉怕他担心绝口不提霍都下战书与武氏兄弟出城之事。杨过推门进来已到城头巡视一周，说众弟兄斗志高扬。黄蓉咳嗽使眼色，杨过会意改口说武家兄弟要为郭靖死战报答恩德。杨过问姑姑在哪黄蓉说她回去睡了。这时杨过因共处数日见郭靖黄蓉赤心为国事事奋不顾身已大为感动，待在蒙古营中一战郭靖舍命救护自己便死心塌地将杀他之心尽数抛却决意竭力以报。他自知再过七日情花之毒便发索性一切置之度外，在这七日之中做一两件好事不枉了一世为人。忽听十余丈外屋顶纵声长笑铮铮两响金铁交鸣——金轮法王到了。郭靖脸色微变顺手拉黄蓉欲藏于身后。黄蓉低声道'靖哥哥襄阳城要紧还是你我的情爱要紧是你身子要紧还是我的身子要紧'。郭靖放开黄蓉的手说'对国事为重'。黄蓉取出竹棒拦在门口眼光却望着杨过——不知他要出手御敌还是要乘人之危既报私仇又取解药。郭靖夫妇短短对答两句听在杨过耳中却如轰天霹雳——他突听到'国事为重'四字又记起郭靖日前所说'为国为民侠之大者''鞠躬尽瘁死而后已'那几句话心胸间斗然开朗。霎时之间幼时在桃花岛上所读'杀身成仁舍生取义'的语句在脑海间变得清晰异常，又是汗颜无地又是志气高昂。他心志一高似乎全身都高大起来脸上神采焕发宛似换了一个人。黄蓉见他脸色自迷惘而羞愧自激动而凝定，听他低声道'你放心'一声清啸拔出君子剑抢到门口。金轮法王站在屋顶手持双轮。杨过笑道此前鬼迷了心窍竟助郭靖逃了回来正自后悔，一面说着一面跃上屋顶站在法王身前数尺之地。谈笑之中杨过斗然嗤的一响君子剑势挟劲风刺向法王左胁——这一剑出其不意近身突袭，法王变招迅捷运劲左臂向外疾掠挡开剑锋但臂上仍被划了一道长长口子深入近寸鲜血长流。杨过笑道'我在蒙古军中受你金轮之伤此刻才还得一剑'又说剑上有些古怪。法王追问时杨过洋洋得意道'我这剑从绝情谷中得来公孙止擅用毒药日后你若侥幸中毒不死那便去找他算帐罢'。法王暗暗吃惊心想莫非剑锋上真喂了毒药，惊疑不定出招稍缓。实则剑上何尝有毒杨过想起黄蓉以热茶吓倒霍都的计策乘机以言语扰敌心神，眼见一言生效当下凝神守御得空便还一招。",
  "事件概要": "杨过彻底弃绝私仇转而护郭靖，法王夜袭反成其践行侠义与国事为重的转折起点。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第22回-06-杨过明志护郭靖金轮来袭": "到城头巡视一周后探望郭靖。因与郭靖夫妇共处数日见二人赤心为国事事奋不顾身已大为感动——自蒙古营一战郭靖舍命救护后已死心塌地将杀他之心尽数抛却。自知七日之内情花毒发将一切置之度外决心在最后七日做一两件好事。听到郭靖黄蓉'国事为重'四字如轰天霹雳心胸豁然开朗——'为国为民侠之大者'令他从私怨中彻底解脱。向黄蓉低声道'你放心'拔剑迎战金轮法王。以笑谈之言令法王放松警惕突然一剑刺伤法王左臂深近一寸。又虚张声势说剑上喂有公孙止的毒药扰乱法王心神占得先机"
      }
    },
    "黄蓉": {
      "人物经历": {
        "第22回-06-杨过明志护郭靖金轮来袭": "天亮前去探望郭靖伤势见他运功休养已无大碍。对郭靖笑说腹中孩儿就要见爹爹了绝口不提危险。杨过来访时使眼色让他改口不提二武相斗之事。金轮法王来袭时取出竹棒守在门口——眼光望着杨过心中猜测他是御敌还是乘危。见杨过神情剧变后低声道'你放心'拔剑迎敌心中大安"
      }
    },
    "金轮法王": {
      "人物经历": {
        "第22回-06-杨过明志护郭靖金轮来袭": "清晨率众入侵襄阳欲刺杀郭靖。在屋顶纵声长笑找到郭靖住所。见杨过跃上屋顶本欲以言语嘲讽他不料杨过突然一剑刺来左臂被君子剑划伤深近一寸鲜血长流。听闻剑上可能有公孙止毒药惊疑不定出招变得迟缓被杨过抢占先机"
      }
    },
    "郭靖": {
      "人物经历": {
        "第22回-06-杨过明志护郭靖金轮来袭": "盘膝运功休养伤势脸色苍白气息调匀。醒转后与黄蓉互相关切。金轮法王来袭时想护黄蓉于身后被黄蓉以国事为重劝住。将黄蓉的手放开决心以国事为先"
      }
    }
  },
  "update": {
    "杨过": {
      "状态": "心境彻底转变——从私仇私怨中解脱出来。郭靖黄蓉'国事为重'四字令他心胸豁然开朗领悟'为国为民侠之大者'的真谛。脸上神采焕发宛似换了一个人。拔剑迎战金轮法王以智计扰敌占得先机",
      "性格": "经历蒙古大营生死之战后彻底明悟——从私仇执念中解脱出来。郭靖黄蓉'国事为重'四字令他将'杀身成仁舍生取义'的道理真正领会透澈。从此心意坚定不再反复——此后活到一百岁也好再活一个时辰也好永远不会反复的了。心志一高似乎全身都高大起来神采焕发。真正领悟了'为国为民侠之大者'的境界"
