  "事件引子": "深夜之中武三通悄然返回陆家庄，将程英和陆无双二女接走藏匿。陆氏夫妇丢了后顾之忧，反而静下心来等待李莫愁的到来。",
  "后续事件": {
    "事件名": "第1回-07-李莫愁血洗陆家庄",
    "描述": "赤练仙子李莫愁踏歌而来，陆家庄大祸临头，一场血腥屠杀即将展开。"
  },
  "事件详情": "夜渐深沉，陆无双伏在父亲怀中沉沉睡去，程英也是迷迷糊糊睁不开眼。武三娘却面带喜色，自言丈夫此番难得通达事理。果然武三通去而复返，在屋顶叫道'抛上来'。武三娘抱起程英走到厅口向上抛去，武三通伸臂接住；又将陆无双掷了上去。陆立鼎大惊跃上屋顶，四下黑沉沉已不见武三通与二女影踪。武三娘劝道武三通是怕李莫愁加害孩子，定是将她们藏到稳妥之处，又说丈夫自从阿沅嫁人后见到女孩便生气，此番竟对程陆二女大是怜爱，实出意料，但愿他从此转性不再糊涂。陆氏夫妇去了后顾之忧，恐惧之心渐减，敌忾之意大增。二人带齐暗器兵刃坐在厅上闭目养神。想起做了十几年夫妻，平日虽为家务小事偶有龃龉，此刻大难临头只觉相偕之时无多，不禁互相依偎、四手紧握，静候李莫愁到来。",
  "事件概要": "武三通连夜带走程英、陆无双避祸，两名女孩暂时脱离陆家庄火线，也让李莫愁的追索转向庄外。",
  "insert": {
    "武三通": {
      "人物经历": {
        "第1回-05-武三通夜返救二女": "去而复返，深夜飞身上陆家庄屋顶呼'抛上来'。武三娘将程英与陆无双先后抛上，武三通一一接住带走。此举大出陆立鼎夫妇意料——武三通自何沅君之事后见到女童便生气，此番却对程英陆无双神色间大是怜爱，竟将二女藏到稳妥之处以避李莫愁。"
      }
    },
    "武三娘": {
      "人物经历": {
        "第1回-05-武三通夜返救二女": "见丈夫武三通去而复返要接走程英和陆无双，面有喜色，主动抱起程英抛上屋顶，又将陆无双掷上。劝慰惊疑的陆立鼎，道丈夫此举是怕李莫愁害了孩儿们。感慨丈夫见到程陆二女神色间大是怜爱，但愿他从此转性不再糊涂。"
      }
    },
    "陆立鼎": {
      "人物经历": {
        "第1回-05-武三通夜返救二女": "见武三通将女儿与姨甥女接走，大惊失色，跃上屋顶追赶不及。听武三娘解释后方知武三通是好意救人。去了后顾之忧后与妻子带齐兵刃坐在厅上闭目养神，互相依偎四手紧握，以平静之心等待李莫愁的到来。"
      }
    },
    "陆二娘": {
      "人物经历": {
        "第1回-05-武三通夜返救二女": "丈夫当局者迷，她却即时会意武三通乃是要藏起孩子避祸。劝慰丈夫安心之后，与丈夫带齐暗器兵刃坐在厅上，夫妻二人四手相握，想起平日为家务小事偶有龃龉，此刻大难临头只觉相偕之时无多，不禁互相依偎。"
      }
    },
    "程英": {
      "人物经历": {
        "第1回-05-武三通夜返救二女": "迷迷糊糊欲睡之际，被武三娘抱起抛上屋顶，由武三通接住带走。与表妹陆无双一同被武三通藏到稳妥之处，因而避开了随后的李莫愁杀戮。"
      }
    },
    "陆无双": {
      "人物经历": {
        "第1回-05-武三通夜返救二女": "在父亲怀中沉沉睡去之时，被武三娘抱起掷上屋顶，由武三通接住带走。与表姊程英一同被武三通藏到稳妥之处，由此逃过一劫。"
      }
