    "事件名": "第37回-04-耶律齐接任丐帮帮主",
    "描述": "杨过与黄药师联手离去后，丐帮四大长老聚头商议后禀明黄蓉，上台宣布立耶律齐为丐帮帮主……"
  },
  "事件详情": "杨过走到郭襄身前温柔问候，郭襄一颗心怦怦乱跳脸颊飞红。杨过左手一挥传令出去，校场口涌进大批人手——竖木打桩东搭木台西挂灯笼，来人虽多却秩序井然。片刻间傀儡戏《八仙贺寿》、戏曲《满床笏》等名班好戏纷纷登场，花炮把戏满场喜庆之声此伏彼起。郭襄见杨过想得如此周到双目含着欢喜之泪。黄药师向黄蓉说起因担忧烟波钓叟对女儿女婿不利才暗中跟来，不料神雕侠竟是忘年交杨过。黄蓉劝父亲留下多聚几日。黄药师招郭襄近前拉着她的手细细端详——黯然道'真像真像'，想起亡妻说郭襄生得像外婆年轻时。郭芙笑说'你叫老东邪她叫小东邪'被郭靖斥责，黄药师却大喜称赞。丐帮四大长老围住杨过不住口称谢欲推他为帮主——杨过抢先推举耶律齐：'耶律大爷文武双全英明仁义是我昔年的知交好友，由他出任贵帮帮主定能继承洪黄鲁三位帮主的大业。'黄药师问了郭襄几句武功后转头招呼杨过近前说话——杨过已走出校场口外。黄药师长袖摆动追到杨过身边，一老一少携手没入黑暗之中。黄蓉追出已在十余丈外，远远听得父亲笑声'咱两个都是野性儿最怕拘束，你便让咱们自由自在的去罢'，最后几字已从数十丈外传来只得回转。",
  "事件概要": "杨过为郭襄盛办庆生并推举耶律齐，黄药师与杨过随即离席远去。",
  "insert": {
    "杨过": {
      "人物经历": {
        "第37回-03-杨过大校场为郭襄安排庆生献艺后离去": "走到郭襄身前笑道'小妹子我来得迟了'。左手一挥传令——大批人手涌入校场搭台挂灯秩序井然。片刻间傀儡戏《八仙贺寿》戏曲《满床笏》等各地名班纷纷登场观众喝彩此伏彼起。与郭襄只说得一句话微笑相对片刻——为她备下三件厚礼后功成身退。对丐帮四大长老推荐耶律齐为帮主。身影微晃已走出校场口外——与黄药师携手没入黑暗之中"
      }
    },
    "黄药师": {
      "人物经历": {
        "第37回-03-黄药师校场见郭襄祖孙重逢后与杨过离去": "向黄蓉述说来意：在洞庭湖上赏月听说烟波钓叟被神雕侠邀赴襄阳——因担心对女儿女婿不利便暗中跟来，不料神雕侠竟是忘年交杨过。招郭襄近前拉手细细端详黯然说'真像真像'——想起亡妻冯蘅。得知郭襄外号'小东邪'大喜称赞。问了郭襄几句武功转头招呼杨过时他已走出校场口——长袖摆动追上杨过，与这忘年小友携手没入黑暗之中。黄蓉追赶不及——远远笑道'咱两个都是野性儿最怕拘束'"
      }
    },
    "郭襄": {
      "人物经历": {
        "第37回-03-郭襄校场庆生感动得泪": "杨过走到身前问候时一颗心怦怦乱跳脸颊飞红。见杨过左手一挥——校场涌入大批人手搭台演戏放花炮玩把戏，全是各地名班卖力出演。见杨过给自己想得这般周到双目含着欢喜之泪一时无话可说。黄药师招手近前行礼——首次见到外公。被外公拉手端详说'真像真像'。杨过离去后心中说不出的惆怅——见姊姊兴高采烈站在姊夫身畔应酬心中伤痛再难忍受转身要回自己家去"
      }
    },
    "郭靖": {
      "人物经历": {
        "第37回-03-郭靖观杨过为郭襄庆生": "虽觉杨过为小女儿如此铺张扬厉未免小题大作——但想他自来行事异想天开，今日为襄阳和丐帮干下三件大事，此刻要任性胡闹也由得他。当下捻须摇头微笑不语。见黄药师与郭襄祖孙重逢黯然说真像——知他又想起了亡妻。听杨过推荐耶律齐为丐帮帮主心中欣慰"
      }
    },
    "黄蓉": {
      "人物经历": {
        "第37回-03-黄蓉与父亲重逢劝留未果": "问父亲为何藏身旗斗——黄药师说担忧烟波钓叟对女儿女婿不利才暗中跟来。劝父亲留下来多聚几日。见父亲与杨过说走便走吃了一惊急忙追出——但二人走得好快已在十余丈外。远远听得父亲笑声说'咱两个都是野性儿最怕拘束'——心中暗暗叫苦只得回转。大校场上锣鼓喧天兀自热闹"
      }
    },
    "郭芙": {
      "人物经历": {
        "第37回-03-郭芙见杨过为郭襄庆生醋意暗生": "生怕父亲要自己相谢杨过救命之恩——抢着向黄药师道谢。想起妹子在羊太傅庙中言语说有位少年大侠要来给她祝寿现下果如所言——不禁暗暗恚怒。拉着黄药师的手问长问短对身周的热闹只作不见"
      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/襄阳/郊野",
      "状态": "与黄药师携手离开大校场没入黑暗之中——功成身退不辞而别。为郭襄备下三件大礼后飘然而去"
    },
    "黄药师": {
      "所在位置": "大宋/襄阳/郊野",
      "状态": "与杨过并肩离了襄阳展开轻功向南疾趋。二人同是野性儿最怕拘束——说走便走片刻不留"
    },
    "郭襄": {
      "状态": "杨过离去后心中说不出的惆怅——见姊姊兴高采烈站在姊夫身畔心中伤痛再难忍受。转身要走时被母亲追到——满眶泪水险些掉下。心中对杨过的情愫已深陷难拔"
    },
    "黄蓉": {
      "状态": "追赶父亲和杨过不及只得回转。见女儿郭襄心神伤痛携她手柔声相问。心中挂念那句要紧话没来得及对父亲说——担心杨过问父亲南海神尼之事"
    }
  },
