987189.content:
{
  "事件地点": "大宋/华山/绝顶",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 9,
    "日": 24,
    "时": 7
  },
  "事件结束时间": {
    "年": 1244,
    "月": 9,
    "日": 29,
    "时": 16
  },
  "事件引子": "次晨杨过尚未睡醒，便听得洞外呼呼风响夹着吆喝纵跃之声——二老又斗得难分难解...",
  "后续事件": {
    "事件名": "第11回-04-二老借杨过口传演武打狗棒法对蛇杖",
    "描述": "二老重伤初愈后分别口授杨过武功招式，以杨过为媒介隔空比试打狗棒法与蛇杖"
  },
  "事件详情": "次晨一早杨过奔出洞外，只见洪七公又与欧阳锋斗得难分难解。他叹了口气，心想这两位老人家返老还童这架有什么好打，只得坐在一旁观看。但见洪七公每一招每一式条理分明，欧阳锋的招数却难以捉摸——每每洪七公已占上风，却被他倏使怪招重又拉成平手。二人日斗晚睡接连斗了四日，均已神困力倦几欲虚脱，但始终不肯容让半招。到第五晚，杨过待欧阳锋睡着后悄声向洪七公借洞外一步说话，离洞十余丈后突然跪倒连连磕头。洪七公登时明白他是要自己可怜欧阳锋有病认输退让，仰天哈哈一笑说道'就是这么着'，倒曳木棒往山下便走。只走出数丈，欧阳锋从洞中窜出挥杖横扫怒喝：'老家伙想逃么？'洪七公让了三招欲待夺路而走，却被他杖风四面拦住脱身不得。高手比武差不得半分，洪七公存了相让之心登时落在下风狼狈不堪。欧阳锋挺杖击向洪七公小腹，洪七公横棒挡格，忽觉杖上传来一股凌厉之极的内力——欧阳锋竟要以内力相攻。二人以前数次比武都不敢行此险着，哪知欧阳锋浑浑噩噩突运内力相攻。从清晨直拼到辰时，又从辰时拼到中午，再到申刻。洪七公渐感内力消竭，欧阳锋也已气衰力竭。杨过眼见二人脸色大变，心想再拼得一时三刻非同归于尽不可，折了一根树干走到二人之间盘膝坐下运功护住全身，一咬牙伸树干往二人杖棒之间挑去。岂知这一挑居然毫不费力——强弩之末不能穿鲁缟，北丐西毒均已精力垂尽，二人给他内力反激同时委顿在地脸如死灰难以动弹。",
  "事件概要": "杨过劝和未成反卷入内力比拼，北丐西毒双双耗尽元气，为后续传招定下局面。",
  "update": {
    "洪七公": {
      "人物经历": {
        "第11回-03-二老连日比武杨过劝退不成反陷内力比拼": "次晨又与欧阳锋斗得难分难解，此后日斗晚睡接连四日均神困力倦几欲虚脱。第五晚杨过跪求退让时明白其意，哈哈一笑倒曳木棒往山下便走。不料欧阳锋窜出挥杖拦截——让了三招后落在下风狼狈不堪数次险些丧命。横棒挡格时惊觉欧阳锋竟要以内力相攻，只得急运功劲抗御——二人已到无可容让不死不休的境地。从清晨拼到中午再到申刻，渐感内力消竭，不知欧阳锋也已气衰力竭。被杨过以树干从中挑开后内力反激委顿在地脸如死灰难以动弹。"
      }
    },
    "杨过": {
      "人物经历": {
        "第11回-03-二老连日比武杨过劝退不成反陷内力比拼": "次晨见二老又斗得难分难解叹气不已，坐在一旁观看。见二老日斗晚睡接连四日均神困力倦仍不肯容让半招。第五晚待欧阳锋睡着后悄声约洪七公出洞——离洞十余丈后突然跪倒连连磕头一言不发，洪七公明白他心意哈哈一笑答允退让。不料欧阳锋窜出拦截，二人转为比拼内力。见二人从清晨拼到申刻脸色大变，心想再拼一时三刻非同归于尽不可，迟疑良久后折树干走到二人之间盘膝坐下运功护住全身，咬牙伸树干往二人杖棒间挑去——居然毫不费力将二人分开。二人内力反激同时委顿在地。惊叫查看二人均呼吸艰难不答，才知受伤极重移动不得，当晚睡在二人之间以防半夜再斗。"
      }
    },
    "欧阳锋": {
      "人物经历": {
        "第11回-03-二老连日比武杨过劝退不成反陷内力比拼": "次晨与洪七公又斗，此后日斗晚睡接连四日——招数难以捉摸每每洪七公占上风时倏使怪招重拉成平手。第五晚见洪七公悄悄出洞便窜出拦截——挥杖横扫怒喝'老家伙想逃么'。洪七公让了三招后抢攻使其落在下风数次险些命丧他杖下。挺杖击向对方小腹时突运内力相攻——内力犹如长江浪涛源源不绝涌来，一浪强过一浪越来越凶猛。从清晨拼到申刻也已气衰力竭支撑维艰。被杨过以树干从中挑开后内力反激委顿在地脸如死灰难以动弹。"
      }
    }
  },
  "参与人物": [
    "杨过",
    "洪七公",
    "欧阳锋"
  ]
}

