987619.content:
{
  "事件地点": "蒙古/襄阳城外/山洞",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 12,
    "日": 26,
    "时": 12
  },
  "事件结束时间": {
    "年": 1244,
    "月": 12,
    "日": 26,
    "时": 13
  },
  "事件引子": "山洞方向忽然传来嗡嗡轰轰的巨响——成千上万只野蜂从各处飞涌而至，疯狂冲向山洞。洞口的蛛网片刻之间便被冲得七零八落，十余只色彩鲜艳的毒蛛也被蜂群刺得僵硬而死。一个藏僧装束的高大身影慌不择路地飞窜而逃，身后紧追着一大群野蜂。",
  "后续事件": {
    "事件名": "第25回-05-小龙女追踪三道人终南山下",
    "描述": "小龙女与周伯通分别后，骑花驴追踪尹志平赵志敬二人。途中遇上丘处机派来传讯的祁志诚，三人一路向北朝终南山而行。"
  },
  "事件详情": "小龙女正要出洞迎敌，忽见一只蜜蜂粘上蛛网不住挣扎——它身躯甚小却不怕彩雪蛛之毒，竟将蛛网撕出一个破洞。小龙女在古墓中与玉蜂终年为伴，视蜂儿如朋友，眼见蜜蜂有难心中不忍，突然转念：毒蛛形貌虽恶我的蜂儿未必便怕它们。她从怀中取出玉瓶催动掌力，热气从掌心传入瓶中，一股芬芳馥郁的蜜香透过蛛网送了出去。此时山谷间野花盛开，四下采蜜的野蜂闻到甜香登时从各处飞涌而至。数十只数百只野蜂冲上山洞，粘上蛛网便挣扎撕扯，有的被毒蛛咬死，有的却在毒蛛身上刺上一针。彩雪蛛虽是天下至毒，但蜂毒中得多了便渐渐僵硬而死。片刻间洞口的蛛网尽被冲烂，十余只毒蛛也尽数中刺僵毙。金轮法王可惜彩雪蛛全军覆没却不知是小龙女召来的野蜂。小龙女挑了一点蜂蜜向法王弹去，口中呼啸吆喝驱蜂向他冲去。法王大惊失色向前飞窜，身法快如黑烟霎时已窜出十余丈外。小龙女见逃走没抢到解药连连顿足。她出洞唤周伯通出来，周伯通跃出半空突然重重跌落——跌落引动彩雪蛛余毒发作全身打战如坠冰窖。小龙女用玉蜂针连刺又召野蜂叮他，周伯通脱光衣服让蜂针刺满全身，约莫一顿饭功夫蛛毒尽解。二人分别时小龙女说要上终南山去，周伯通说另有要紧事。小龙女转身走开，回头却见周伯通偷了她的玉瓶正在学驱蜂，把戏被拆穿后羞得满脸通红飞也似的逃下山去。小龙女哈哈大笑，空山隐隐传来几响回声，蓦地里只觉寂寞凄凉难以自遣，忍不住流下两行清泪。",
  "事件概要": "小龙女召来野蜂冲毁毒蛛网并逼退金轮法王，又以蜂针为周伯通解尽蛛毒；二人脱困后各自离开终南山外。",
  "insert": {
    "小龙女": {
      "人物经历": {
